/* KHBD Mĩ thuật Lớp 2 KNTT — Bút Xanh, tích hợp NLS+AI */
window.KHO_DATA_L2_MITHUAT = [
{"lop":2,"mon":"Mĩ thuật","tuan":1,"tiet":1,"bai":"Chủ đề 1: MĨ THUẬT TRONG CUỘC SỐNG","yccd":"1. Năng lực mĩ thuật\n- Nhận biết được hình thức và sự xuất hiện đa dạng của mĩ thuật trong cuộc sống.\n- Gọi được tên một số hình thức biểu hiện của mĩ thuật ở xung quanh (pa-nô, áp phích, sản phẩm thủ công, đồ lưu niệm...).\n- Nhận ra sự phong phú của mĩ thuật trong cuộc sống.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động quan sát tranh, ảnh, đồ vật xung quanh và kể lại những gì đã thấy.\n- Giao tiếp và hợp tác: mạnh dạn chia sẻ hiểu biết của mình trước lớp, lắng nghe ý kiến của bạn.\n3. Phẩm chất\n- Yêu thích một số hình thức biểu hiện của mĩ thuật trong cuộc sống xung quanh.\n- Có ý thức giữ gìn cảnh quan, sự vật, đồ vật có tính mĩ thuật.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS gọi tên được các hình thức mĩ thuật trong cuộc sống qua bộ ảnh.","dodung":"- Giáo viên: một số tác phẩm, sản phẩm mĩ thuật gần gũi ở địa phương; tranh ảnh, clip (nếu có điều kiện) về sự xuất hiện của mĩ thuật trong cuộc sống; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 2, Vở bài tập Mĩ thuật 2, bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS chơi trò chơi Tranh và tượng: chia hai nhóm, xem hình ảnh và tìm nhanh đâu là tranh, đâu là tượng.\n- GV nêu luật chơi, nhận xét, tuyên dương và dẫn vào chủ đề.","hs":"- HS tham gia trò chơi theo nhóm, quan sát và xác định tranh, tượng.\n- HS lắng nghe, mở bài học."},{"ten":"2. Khám phá — Mĩ thuật quanh em","gv":"- GV mời HS nêu hiểu biết của mình về các tác phẩm, sản phẩm mĩ thuật đã biết.\n- GV cho HS quan sát hình trang 5-7 SGK Mĩ thuật 2, đặt câu hỏi: Đây là tác phẩm, sản phẩm gì? Thường thấy ở đâu?\n- GV bổ sung, làm rõ các hình thức mĩ thuật: pa-nô, áp phích ngày lễ; cờ trang trí ngày khai giảng; sản phẩm thủ công, đồ lưu niệm, sản phẩm từ vật liệu tái sử dụng.","hs":"- HS nêu hiểu biết của mình.\n- HS quan sát hình, trả lời câu hỏi.\n- HS lắng nghe, ghi nhớ về các hình thức mĩ thuật trong cuộc sống."},{"ten":"3. Luyện tập — Kể và giới thiệu","gv":"- GV mời từng HS nói về tác phẩm, sản phẩm mĩ thuật đã nhìn thấy ở trường, ở nhà hoặc nơi em đã đến.\n- GV ghi tóm tắt câu trả lời lên bảng (không đánh giá), khen ngợi, động viên HS.","hs":"- HS giới thiệu về những sản phẩm mĩ thuật mà mình đã thấy.\n- HS lắng nghe bạn chia sẻ."},{"ten":"4. Vận dụng","gv":"- GV yêu cầu HS nêu lại kiến thức bài học và liên hệ: em sẽ giữ gìn những đồ vật, cảnh quan đẹp như thế nào?\n- GV dặn HS về xem trước Chủ đề 2: Sự thú vị của nét.","hs":"- HS nêu lại kiến thức, chia sẻ ý thức giữ gìn cái đẹp.\n- HS ghi nhớ nhiệm vụ chuẩn bị."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu bộ ảnh về mĩ thuật quanh ta: pa-nô ngoài đường, bìa sách, bao bì bánh kẹo, hoa văn trên áo, tượng ở công viên; mỗi ảnh được phóng to một góc để HS thấy người ta đã chọn hình, chọn màu, chọn chữ cho từng thứ ra sao.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) HS chỉ trên màn hình thứ nào là tranh, thứ nào là đồ thủ công, thứ nào là công trình kiến trúc và nói mình đã gặp thứ đó ở đâu.\n⚠ (Miền 4: An toàn) GV mở đúng tập ảnh đã chuẩn bị trước, không mở trang mạng có quảng cáo chen ngang trong giờ học; xem ảnh xong HS ra hành lang tìm những thứ có trang trí ở ngay trong trường mình.","hs":"- HS gọi tên được các hình thức mĩ thuật trong cuộc sống qua bộ ảnh.\n- HS kể được nơi mình đã gặp sản phẩm mĩ thuật đó ngoài đời."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":2,"tiet":2,"bai":"Chủ đề 2: SỰ THÚ VỊ CỦA NÉT — Tiết 1: Quan sát và thể hiện nét","yccd":"1. Năng lực mĩ thuật\n- Nhận ra được nét và các hình thức biểu hiện của nét trên sản phẩm mĩ thuật (nét cong, thẳng, gấp khúc...).\n- Nhận biết các chất liệu thực hiện sản phẩm mĩ thuật có sử dụng yếu tố nét.\n- Tạo được sản phẩm mĩ thuật làm nổi bật yếu tố nét bằng hình thức vẽ hoặc xé dán.\n2. Năng lực chung\n- Tự chủ và tự học: biết lựa chọn công cụ, chất liệu phù hợp để thực hành.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ cảm nhận về sản phẩm với bạn.\n3. Phẩm chất\n- Yêu thích sử dụng nét trong thực hành.\n- Có ý thức trao đổi, chia sẻ cảm nhận về sản phẩm mĩ thuật.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nhận ra các loại nét có trong đồ vật quen thuộc qua ảnh phóng to.","dodung":"- Giáo viên: một số tranh, ảnh, đồ vật được trang trí bằng nét; sản phẩm mĩ thuật có nhiều loại nét khác nhau; thiết bị trình chiếu.\n- Học sinh: SGK Mĩ thuật 2, Vở bài tập Mĩ thuật 2, bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS chơi trò chơi Đoán tên của nét: GV vẽ nhanh các nét, nhóm nào gọi đúng tên nhiều nét hơn thì thắng.\n- GV nhận xét, tuyên dương và giới thiệu chủ đề.","hs":"- HS tham gia trò chơi, gọi tên các nét.\n- HS lắng nghe, mở bài học."},{"ten":"2. Khám phá — Quan sát nét","gv":"- GV cho HS quan sát hình trang 8-9 SGK Mĩ thuật 2 và một số đồ vật có nét trang trí.\n- GV đặt câu hỏi: Nét có ở đâu trên sản phẩm? Đó là những nét nào (cong, thẳng, gấp khúc)? Sản phẩm được tạo bằng chất liệu gì?\n- GV chốt: nét có nhiều trên sản phẩm mĩ thuật, tạo bằng nhiều cách và chất liệu khác nhau.","hs":"- HS quan sát, trả lời câu hỏi theo cảm nhận.\n- HS nhận biết các loại nét và chất liệu.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập — Sáng tạo","gv":"- GV hướng dẫn HS tham khảo cách tạo nét trang 10 SGK Mĩ thuật 2 (vẽ hoặc xé, cắt dán giấy màu).\n- GV thị phạm trực tiếp và yêu cầu HS thực hành: dùng nét là chính để tạo một sản phẩm yêu thích.\n- GV quan sát, giúp đỡ HS hoàn thành, nhắc HS lưu giữ sản phẩm cho tiết sau.","hs":"- HS quan sát cách thị phạm, tiếp thu.\n- HS thực hành tạo sản phẩm làm nổi bật nét.\n- HS lưu giữ sản phẩm."},{"ten":"4. Vận dụng","gv":"- GV cho HS giới thiệu nhanh sản phẩm đang làm: em đã dùng những nét gì?\n- GV khen ngợi, động viên, dặn HS chuẩn bị tiếp cho tiết 2.","hs":"- HS chia sẻ về các nét trong sản phẩm.\n- HS ghi nhớ nhiệm vụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu ảnh chụp thật gần vân gỗ trên mặt bàn, đường chỉ trên tấm áo, sóng nước, mạng nhện; ảnh phóng to giúp HS nhận ra nét cong, nét thẳng, nét xoắn có sẵn trong đồ vật quanh mình mà nhìn lướt qua không thấy.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV dùng công cụ vẽ tô đè một đường lên ảnh để chỉ rõ đường nét muốn HS chú ý, tô xong lại xoá đi để chuyển sang ảnh khác.\n⚠ (Miền 4: An toàn) GV thao tác trên máy, HS ngồi tại chỗ quan sát; xem ảnh trên màn hình xong, HS sờ tay lên mặt bàn, lên tấm vải thật để cảm nhận nét bằng đầu ngón tay.","hs":"- HS nhận ra các loại nét có trong đồ vật quen thuộc qua ảnh phóng to.\n- HS chỉ ra được nét tương tự trên đồ vật thật trong lớp."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":3,"tiet":3,"bai":"Chủ đề 2: SỰ THÚ VỊ CỦA NÉT — Tiết 2: Thảo luận và vận dụng","yccd":"1. Năng lực mĩ thuật\n- Củng cố kiến thức, kĩ năng liên quan đến yếu tố nét và cách tạo nét đã học.\n- Nhận biết được sự lặp lại của nét trong trang trí đường diềm.\n- Sử dụng nét màu để trang trí một đồ vật em yêu thích.\n2. Năng lực chung\n- Giao tiếp và hợp tác: trao đổi nhóm, trình bày cảm nhận về sản phẩm.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách trang trí phù hợp với đồ vật.\n3. Phẩm chất\n- Chăm chỉ hoàn thành sản phẩm; yêu thích cái đẹp trong trang trí đồ vật.\n4. Tích hợp\n- Năng lực số 3.1 CB1a: Xác định được các cách tạo và chỉnh sửa nội dung đơn giản ở các định dạng đơn giản: HS nhận ra nhịp điệu của đường diềm sinh ra từ hoạ tiết lặp lại.","dodung":"- Giáo viên: sản phẩm mĩ thuật trang trí bằng nét; hình đường diềm mẫu; đồ vật để trang trí (đĩa nhựa, tấm thiệp, tấm bìa); thiết bị trình chiếu.\n- Học sinh: sản phẩm tiết 1, bút màu, giấy màu, kéo, hồ dán, đồ vật để trang trí.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV tổ chức trò chơi Chấm ở đâu, lồng ghép giải thích cách sắp xếp nét theo nguyên lí lặp lại.\n- GV nhận xét, tuyên dương, dẫn vào bài.","hs":"- HS tham gia trò chơi, lắng nghe.\n- HS mở bài học."},{"ten":"2. Khám phá — Thảo luận","gv":"- GV tổ chức cho HS trao đổi nhóm theo câu hỏi trang 11 SGK Mĩ thuật 2: Bài của bạn có những nét gì? Với những nét này có thể tạo hình gì khác? Em thích bài nào nhất?\n- GV gợi ý HS quan sát đường diềm để nhận biết sự lặp lại của hình con voi, bông hoa.\n- GV chỉ ra nguyên lí lặp lại, nhắc lại, nhịp điệu của nét.","hs":"- HS thảo luận nhóm, trả lời câu hỏi.\n- HS nhận biết sự lặp lại của nét trong đường diềm.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập — Vận dụng","gv":"- GV cho HS quan sát cách dùng nét trang trí một chiếc đĩa (trang 12 SGK Mĩ thuật 2).\n- GV gợi ý HS trang trí một đĩa nhựa, tấm thiệp hoặc tấm bìa bằng nét màu.\n- GV quan sát, giúp đỡ HS hoàn thiện sản phẩm.","hs":"- HS quan sát, nhận biết cách thực hiện.\n- HS thực hành trang trí đồ vật bằng nét màu.\n- HS hoàn thiện sản phẩm."},{"ten":"4. Vận dụng — Trưng bày","gv":"- GV tổ chức cho HS trưng bày sản phẩm, chia sẻ: Bạn tạo được sản phẩm gì? Nét thể hiện ở đâu? Em thích sản phẩm nào nhất?\n- GV cùng HS nhận xét, động viên; dặn xem trước Chủ đề 3.","hs":"- HS trưng bày, giới thiệu sản phẩm.\n- HS nhận xét, ghi nhớ nhiệm vụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV mở một trang trình chiếu, vẽ một hoạ tiết rồi dùng lệnh sao chép và dán cho hoạ tiết ấy lặp lại thành đường diềm dài; HS thấy ngay nhịp điệu của trang trí sinh ra từ sự lặp lại đều đặn, GV đổi khoảng cách giữa các hoạ tiết thì đường diềm đổi theo.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) HS quan sát cạnh đó ảnh đường diềm trên khăn, trên bát đĩa để đối chiếu với đường diềm vừa dựng trên máy.\n⚠ (Miền 4: An toàn) GV thao tác sao chép, dán; HS quan sát và nêu ý kiến rồi tự vẽ đường diềm bằng tay trên giấy, vì chỉ vẽ tay mới rèn được nét đều.","hs":"- HS nhận ra nhịp điệu của đường diềm sinh ra từ hoạ tiết lặp lại.\n- HS chọn được khoảng cách lặp lại cho đường diềm của mình."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":4,"tiet":4,"bai":"Chủ đề 3: SỰ KẾT HỢP CỦA CÁC HÌNH CƠ BẢN — Tiết 1: Quan sát và thể hiện (dạng 2D)","yccd":"1. Năng lực mĩ thuật\n- Nhận ra sự kết hợp của các hình cơ bản (tròn, vuông, chữ nhật, tam giác) để tạo nên hình dạng đồ vật, sự vật.\n- Củng cố kiến thức về hình cơ bản; nhận biết sự lặp lại của các hình.\n- Tạo được một vật có sự kết hợp của hình cơ bản dạng 2D bằng hình thức vẽ hoặc xé dán.\n2. Năng lực chung\n- Tự chủ và tự học: chọn nội dung, chất liệu phù hợp để thể hiện sản phẩm.\n- Giao tiếp và hợp tác: liên tưởng, chia sẻ ý tưởng với bạn.\n3. Phẩm chất\n- Yêu thích sử dụng các hình cơ bản trong thực hành; chăm chỉ, sáng tạo.\n4. Tích hợp\n- Năng lực số 1.2 CB1a: Phát hiện được độ tin cậy và độ chính xác của các nguồn chung của dữ liệu, thông tin và nội dung số: HS kể được các hình cơ bản trong một đồ vật có thật ở lớp.","dodung":"- Giáo viên: một số đồ vật có dạng kết hợp các hình cơ bản; hình cơ bản làm bằng dây thép, khối thạch cao (nếu có); hình ảnh, clip minh họa; thiết bị trình chiếu.\n- Học sinh: SGK Mĩ thuật 2, Vở bài tập Mĩ thuật 2, bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS chơi trò chơi Nhìn vật đoán hình: xem đồ vật và gọi tên các hình cơ bản tạo nên đồ vật đó.\n- GV nhận xét, tuyên dương, giới thiệu chủ đề.","hs":"- HS tham gia trò chơi, gọi tên hình cơ bản.\n- HS lắng nghe, mở bài học."},{"ten":"2. Khám phá — Quan sát sự kết hợp","gv":"- GV cho HS quan sát hình trang 13-15 SGK Mĩ thuật 2 và đồ vật thật.\n- GV đặt câu hỏi: Đồ vật này được kết hợp từ những hình cơ bản nào? (chữ nhật, vuông kết hợp tròn; kết hợp tam giác...).\n- GV gợi ý HS nhận ra sự lặp lại của hình cơ bản (đoàn tàu, đèn ông sao, chuồng chim...).","hs":"- HS quan sát, trả lời câu hỏi.\n- HS nhận biết sự kết hợp và lặp lại của các hình.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập — Sáng tạo (2D)","gv":"- GV hướng dẫn HS tham khảo sản phẩm vẽ, xé dán ở trang 16 SGK Mĩ thuật 2.\n- GV yêu cầu HS thực hành vẽ hoặc xé dán một vật đơn giản có sự kết hợp của các hình cơ bản (dạng 2D) và trang trí theo ý thích.\n- GV quan sát, giúp đỡ; nhắc HS lưu giữ sản phẩm cho tiết sau.","hs":"- HS tham khảo, nhận biết cách làm.\n- HS thực hành tạo vật 2D từ các hình cơ bản.\n- HS lưu giữ sản phẩm."},{"ten":"4. Vận dụng","gv":"- GV mời HS chia sẻ: vật em làm được kết hợp từ những hình nào?\n- GV khen ngợi, dặn HS chuẩn bị cho tiết 2.","hs":"- HS chia sẻ về sản phẩm.\n- HS ghi nhớ nhiệm vụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu ảnh ngôi nhà, ô tô, tàu thuỷ rồi bấm cho từng hình cơ bản tách rời ra khỏi ảnh: mái nhà là hình tam giác, thân nhà là hình chữ nhật, bánh xe là hình tròn; tách rồi ghép lại vài lần để HS nhìn thấy cách một đồ vật được dựng nên từ các hình.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) HS chọn một đồ vật có trong lớp và kể ra đồ vật đó gồm những hình cơ bản nào.\n⚠ (Miền 4: An toàn) GV để máy chiếu ở độ sáng vừa phải và nhắc HS không nhìn thẳng vào bóng đèn máy chiếu; xem xong HS xếp hình bằng bìa cắt sẵn để tự tay ghép lại.","hs":"- HS chỉ ra được các hình cơ bản tạo nên một đồ vật khi xem hình tách và ghép.\n- HS kể được các hình cơ bản trong một đồ vật có thật ở lớp."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":5,"tiet":5,"bai":"Chủ đề 3: SỰ KẾT HỢP CỦA CÁC HÌNH CƠ BẢN — Tiết 2: Thể hiện (dạng 3D)","yccd":"1. Năng lực mĩ thuật\n- Củng cố cách nhận biết sự kết hợp của các hình cơ bản trong đồ vật, sự vật.\n- Tạo được một vật có sự kết hợp của hình cơ bản dạng 3D bằng hình thức nặn hoặc tạo khối.\n- Biết sử dụng công cụ, vật liệu phù hợp để thực hành.\n2. Năng lực chung\n- Giải quyết vấn đề và sáng tạo: sắp xếp, kết hợp các hình để tạo vật 3D theo ý thích.\n- Giao tiếp và hợp tác: liên tưởng, trao đổi ý tưởng với bạn.\n3. Phẩm chất\n- Chăm chỉ, kiên trì hoàn thành sản phẩm; yêu thích sáng tạo hình khối.","dodung":"- GV: một số sản phẩm 3D ghép từ hình cơ bản (con lật đật, ô tô, ngôi nhà, con sâu) để HS quan sát; đất nặn nhiều màu, dao nhựa, tấm bìa lót khi nặn; thiết bị trình chiếu.\n- GV chuẩn bị vật liệu thay thế cho lớp thiếu đồ dùng: giấy báo cũ vò tròn, bìa carton, vỏ hộp sữa, vỏ hộp thuốc, lõi giấy, nắp chai, hột hạt, dây len, vải vụn.\n- HS: sản phẩm tiết 1, đất nặn (hoặc đất sét, bột nặn tự làm), giấy bìa, bút màu, kéo, hồ dán, vật liệu tái sử dụng đã rửa sạch, khăn lau tay, tờ báo cũ lót bàn.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV kiểm tra nhanh đồ dùng và sản phẩm tiết 1 của từng bàn, khen ngợi bạn chuẩn bị đủ, cho mượn vật liệu dự phòng với bạn còn thiếu.\n- GV tổ chức trò chơi Hình gì - Vật gì: GV giơ một thẻ hình (hình tròn, hình vuông, hình tam giác, hình chữ nhật), HS nói thật nhanh tên một đồ vật có dạng hình đó.\n- GV hỏi gợi mở: Quả bóng giống hình gì? Hộp bánh giống hình gì? Mái nhà giống hình gì? Dự kiến HS trả lời: quả bóng - hình tròn, hộp bánh - hình vuông hoặc hình chữ nhật, mái nhà - hình tam giác.\n- GV chốt: ghép nhiều hình lại với nhau ta có một vật mới; hôm nay cả lớp sẽ ghép các khối để tạo một vật dạng 3D.","hs":"- HS đặt sản phẩm tiết 1 và đồ dùng lên góc bàn cho GV kiểm tra.\n- HS chơi trò chơi, nói nhanh tên đồ vật ứng với hình GV giơ lên.\n- HS trả lời: quả bóng hình tròn, hộp bánh hình vuông, mái nhà hình tam giác, quyển sách hình chữ nhật.\n- HS lắng nghe và nhận ra nhiệm vụ của tiết học."},{"ten":"2. Khám phá — Liên hệ thực tế","gv":"- (7 phút) GV bày ba sản phẩm mẫu lên bàn giữa lớp, cho HS đi vòng quanh quan sát khoảng một phút.\n- GV nêu câu hỏi gợi mở: Con lật đật này ghép từ mấy khối? Khối nào to, khối nào nhỏ? Vì sao khối to lại đặt ở dưới? Dự kiến HS trả lời: ghép từ hai khối tròn, khối to ở dưới, khối nhỏ ở trên; đặt khối to ở dưới thì sản phẩm mới đứng vững.\n- GV hỏi tiếp: Ngoài đất nặn còn có thể làm bằng gì? Dự kiến HS trả lời: bằng vỏ hộp, bìa carton, giấy báo vò tròn, nắp chai.\n- GV chốt: các hình cơ bản khi cộng lại hoặc lặp lại sẽ gợi ra nhiều vật; khối to đặt dưới, khối nhỏ đặt trên thì sản phẩm cân đối và đứng vững.","hs":"- HS đi vòng quanh bàn mẫu, quan sát và sờ nhẹ vào sản phẩm.\n- HS đếm số khối trong sản phẩm và trả lời: hai khối tròn, khối to ở dưới cho vững.\n- HS kể thêm vật liệu thay thế đất nặn: vỏ hộp, bìa carton, giấy báo vò tròn, nắp chai.\n- HS nhắc lại ý chốt: khối to ở dưới, khối nhỏ ở trên thì sản phẩm cân đối."},{"ten":"3. Luyện tập — Sáng tạo (3D)","gv":"- (16 phút) GV làm mẫu chậm ở bước khó nhất là gắn khối: xoa nhẹ chỗ tiếp giáp cho hai khối đất dính chặt; nếu dùng vỏ hộp thì dán băng dính hai mặt rồi mới bọc giấy màu ra ngoài.\n- GV nêu các bước thực hành: bước 1 nghĩ mình sẽ làm vật gì; bước 2 chia đất hoặc chọn vỏ hộp cho từng bộ phận; bước 3 nặn hoặc gấp riêng từng khối; bước 4 ghép các khối theo thứ tự to ở dưới, nhỏ ở trên; bước 5 gắn chi tiết nhỏ như mắt, tai, bánh xe, hoa văn.\n- GV nhắc bạn thiếu đất nặn có thể dùng giấy báo cũ vò tròn bọc giấy màu, vỏ hộp sữa, lõi giấy, nắp chai, hột hạt làm mắt, dây len làm tóc, vải vụn làm áo.\n- GV đi từng bàn giúp bạn còn lúng túng; nhắc an toàn: mũi kéo luôn hướng xuống bàn, đưa kéo cho bạn thì cầm phần lưỡi, hồ dán bôi một lớp mỏng, không đưa đất nặn lên miệng.\n- GV báo trước khi còn 3 phút để HS kịp hoàn thiện và ghi tên vào mẩu giấy đặt cạnh sản phẩm.","hs":"- HS quan sát GV làm mẫu cách gắn khối cho chắc.\n- HS thực hành theo 5 bước: nghĩ ý tưởng, chia vật liệu, tạo từng khối, ghép các khối, gắn chi tiết nhỏ.\n- HS thiếu đất nặn chủ động dùng giấy báo vò tròn, vỏ hộp, nắp chai, hột hạt, dây len để thay thế.\n- HS giữ an toàn khi dùng kéo, hồ dán và giữ chỗ ngồi gọn gàng.\n- HS hoàn thiện sản phẩm, ghi tên mình vào mẩu giấy đặt cạnh sản phẩm."},{"ten":"4. Vận dụng","gv":"- (8 phút) GV cho HS đặt sản phẩm lên bàn nhóm thành một phòng tranh mini ở góc lớp, mỗi nhóm một khu riêng.\n- GV mời 4 đến 5 HS giới thiệu: Em làm vật gì? Em ghép mấy khối? Vì sao em chọn vật liệu đó? Dự kiến HS trả lời: em làm con sâu từ bốn khối tròn nối nhau, em dùng giấy báo vò tròn vì ở nhà có sẵn.\n- GV nêu tiêu chí nhận xét sản phẩm: một là ghép được từ hai khối trở lên; hai là các khối gắn chắc, sản phẩm đứng vững; ba là sắp xếp cân đối, nhìn ra được vật gì; bốn là bài sạch sẽ, có ý tưởng riêng.\n- GV cho HS đi xem một vòng, mỗi bạn dán một ngôi sao giấy vào sản phẩm mình thích rồi nói một câu vì sao thích.\n- GV khen ngợi, dặn cất sản phẩm vào hộp riêng để dùng cho tiết 3; nhắc lau bàn, nhặt vụn đất và giấy bỏ vào sọt rác, rửa tay trước khi ra chơi.","hs":"- HS đặt sản phẩm lên bàn nhóm theo khu vực của nhóm mình.\n- HS giới thiệu sản phẩm: tên vật, số khối đã ghép, vật liệu đã dùng.\n- HS nghe và nhắc lại 4 tiêu chí nhận xét sản phẩm.\n- HS đi xem, dán ngôi sao vào sản phẩm mình thích và nói một câu vì sao thích.\n- HS cất sản phẩm, lau bàn, nhặt vụn đất và giấy bỏ vào sọt rác rồi rửa tay."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":6,"tiet":6,"bai":"Chủ đề 3: SỰ KẾT HỢP CỦA CÁC HÌNH CƠ BẢN — Tiết 3: Thảo luận và vận dụng (xem tranh họa sĩ)","yccd":"1. Năng lực mĩ thuật\n- Củng cố kiến thức về hình cơ bản và sự kết hợp của chúng để tạo sản phẩm mĩ thuật.\n- Quan sát, tìm hiểu tranh của họa sĩ Pôn Cli (Paul Klee): Lâu đài và mặt trời, Những chiếc thuyền buồm; nhận ra sự kết hợp các hình cơ bản trong tranh.\n- Vẽ được một bức tranh có sử dụng sự kết hợp các hình cơ bản và vẽ màu theo ý thích.\n2. Năng lực chung\n- Giao tiếp và hợp tác: trao đổi, nêu cảm nhận về tác phẩm và sản phẩm của bạn.\n3. Phẩm chất\n- Yêu thích tác phẩm mĩ thuật; trân trọng sự sáng tạo trong nghệ thuật.\n4. Tích hợp\n- Năng lực số 3.3 CB1a: Xác định được các quy tắc đơn giản về bản quyền và giấy phép áp dụng cho dữ liệu, thông tin và nội dung số: HS hiểu vì sao phải ghi tên tác giả khi nói về một bức tranh.","dodung":"- Giáo viên: tranh Lâu đài và mặt trời, Những chiếc thuyền buồm của họa sĩ Pôn Cli; thiết bị trình chiếu học liệu số.\n- Học sinh: sản phẩm các tiết trước, bút chì, tẩy, màu vẽ, giấy vẽ.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV kiểm tra sản phẩm tiết 2, khen ngợi, động viên.\n- GV giới thiệu nội dung tiết học: xem tranh họa sĩ và sáng tạo tranh của em.","hs":"- HS trưng bày sản phẩm tiết 2.\n- HS lắng nghe, mở bài học."},{"ten":"2. Khám phá — Xem tranh họa sĩ","gv":"- GV cho HS quan sát tranh trang 18 SGK Mĩ thuật 2, đặt câu hỏi: Trong tranh Lâu đài và mặt trời có hình ảnh nào nổi bật? Lâu đài, thuyền buồm được kết hợp từ hình cơ bản nào? Em có nhận xét gì về màu sắc?\n- GV giới thiệu ngắn gọn về họa sĩ Pôn Cli và hai bức tranh.","hs":"- HS quan sát tranh, trả lời câu hỏi.\n- HS nhận ra sự kết hợp hình cơ bản và màu sắc trong tranh.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập — Sáng tạo","gv":"- GV yêu cầu HS vẽ một bức tranh có sử dụng sự kết hợp của các hình cơ bản đã học và vẽ màu theo ý thích.\n- GV gợi ý về nội dung, cách chọn hình ảnh, màu sắc; quan sát, giúp đỡ HS hoàn thiện.","hs":"- HS vẽ tranh từ các hình cơ bản.\n- HS vẽ màu, hoàn thiện sản phẩm."},{"ten":"4. Vận dụng — Trưng bày","gv":"- GV tổ chức cho HS trưng bày, chia sẻ: Sản phẩm được tạo từ những hình nào? Màu sắc thế nào? Em thích sản phẩm nào nhất?\n- GV cùng HS nhận xét, động viên; dặn xem trước Chủ đề 4.","hs":"- HS trưng bày, giới thiệu tranh.\n- HS nhận xét, ghi nhớ nhiệm vụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu bản chụp rõ nét bức tranh của hoạ sĩ Pôn Cli, phóng to từng mảng để HS thấy hoạ sĩ đã xếp các hình vuông, hình tam giác cạnh nhau và chọn màu nóng, màu lạnh thế nào; tranh in trong sách nhỏ, phóng to trên màn hình mới nhìn rõ từng mảng màu.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV chỉ dòng chữ ghi tên tranh và tên hoạ sĩ đặt cạnh bức tranh, giải thích xem tranh của ai thì phải nói rõ tranh của người ấy, cũng như bài của em thì ghi tên em.\n⚠ (Miền 4: An toàn) Bức tranh này là của hoạ sĩ, ta chỉ xem để học cách hoạ sĩ ghép hình chứ không vẽ lại y hệt rồi nói là tranh của mình; ảnh tranh do GV tải sẵn từ nguồn đáng tin.","hs":"- HS nêu được cách hoạ sĩ kết hợp hình và màu khi xem tranh phóng to.\n- HS hiểu vì sao phải ghi tên tác giả khi nói về một bức tranh."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":7,"tiet":7,"bai":"Chủ đề 4: NHỮNG MẢNG MÀU YÊU THÍCH — Tiết 1: Quan sát và thể hiện mảng màu","yccd":"1. Năng lực mĩ thuật\n- Nhận biết được màu sắc trong cuộc sống và trong tác phẩm mĩ thuật.\n- Tạo được những mảng màu yêu thích bằng hình thức tự chọn (vẽ, xé dán, in...).\n- Bước đầu nhận biết cách sắp đặt các màu cạnh nhau.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động lựa chọn màu sắc, hình thức thể hiện.\n- Giao tiếp và hợp tác: chia sẻ về những màu em yêu thích.\n3. Phẩm chất\n- Yêu thích màu sắc; cảm nhận cái đẹp của màu sắc trong cuộc sống.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nhận ra sự chuyển dần của màu trên bảng màu số.","dodung":"- Giáo viên: bảng màu, tranh ảnh có màu sắc phong phú; tác phẩm hội họa nhiều màu; thiết bị trình chiếu.\n- Học sinh: SGK Mĩ thuật 2, Vở bài tập Mĩ thuật 2, màu vẽ, giấy vẽ, giấy màu, kéo, hồ dán.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS chơi trò chơi Gọi tên màu sắc quanh em: nhìn nhanh đồ vật trong lớp và gọi tên màu.\n- GV nhận xét, tuyên dương, giới thiệu chủ đề.","hs":"- HS tham gia trò chơi, gọi tên màu sắc.\n- HS lắng nghe, mở bài học."},{"ten":"2. Khám phá — Màu sắc trong cuộc sống","gv":"- GV cho HS quan sát hình ảnh trang 19-20 SGK Mĩ thuật 2 và tranh ảnh nhiều màu.\n- GV đặt câu hỏi: Em thấy những màu nào? Màu nào em yêu thích? Các màu đứng cạnh nhau tạo cảm giác gì?\n- GV chốt: màu sắc rất phong phú, mỗi màu gợi một cảm xúc riêng.","hs":"- HS quan sát, kể tên màu sắc.\n- HS nêu màu yêu thích, cảm nhận về màu.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập — Sáng tạo","gv":"- GV hướng dẫn HS tham khảo cách tạo mảng màu trong SGK (vẽ, xé dán, in).\n- GV yêu cầu HS tạo những mảng màu yêu thích bằng hình thức tự chọn.\n- GV quan sát, giúp đỡ; nhắc HS lưu giữ sản phẩm cho tiết sau.","hs":"- HS tham khảo, chọn hình thức thể hiện.\n- HS thực hành tạo những mảng màu yêu thích.\n- HS lưu giữ sản phẩm."},{"ten":"4. Vận dụng","gv":"- GV cho HS chia sẻ: em đã tạo những mảng màu nào? Vì sao em thích?\n- GV khen ngợi, dặn HS chuẩn bị cho tiết 2.","hs":"- HS chia sẻ về mảng màu của mình.\n- HS ghi nhớ nhiệm vụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu một bảng màu số và di chuyển ô chọn để HS thấy màu chuyển dần từ đỏ sang cam rồi sang vàng; sự chuyển màu liên tục này hộp sáp chỉ có mấy màu rời rạc không cho thấy được.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) HS chỉ trên bảng màu hai màu đứng cạnh nhau nhìn hoà hợp và hai màu đứng xa nhau nhìn tương phản mạnh.\n⚠ (Miền 4: An toàn) GV thao tác trên máy; màu trên màn hình sáng hơn màu sáp trên giấy nên HS phải thử màu thật ra giấy nháp trước khi tô vào bài.","hs":"- HS nhận ra sự chuyển dần của màu trên bảng màu số.\n- HS chọn được cặp màu hoà hợp và cặp màu tương phản cho bài của mình."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":8,"tiet":8,"bai":"Chủ đề 4: NHỮNG MẢNG MÀU YÊU THÍCH — Tiết 2: Màu đậm, màu nhạt","yccd":"1. Năng lực mĩ thuật\n- Nhận biết màu sắc trong tác phẩm hội họa, chú ý đến sự sắp đặt các màu cạnh nhau, màu đậm, màu nhạt.\n- Tạo được những mảng màu thể hiện được màu đậm, màu nhạt.\n- Biết phối hợp màu đậm - nhạt để sản phẩm thêm sinh động.\n2. Năng lực chung\n- Giải quyết vấn đề và sáng tạo: lựa chọn, sắp xếp mảng màu đậm - nhạt hợp lí.\n- Giao tiếp và hợp tác: trao đổi cảm nhận về màu sắc với bạn.\n3. Phẩm chất\n- Chăm chỉ hoàn thành sản phẩm; yêu thích khám phá màu sắc.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nhận ra một màu có nhiều mức đậm nhạt khi xem ảnh được chỉnh sáng.","dodung":"- Giáo viên: tác phẩm hội họa có màu đậm, màu nhạt; bảng pha màu; thiết bị trình chiếu.\n- Học sinh: sản phẩm tiết 1, màu vẽ, giấy vẽ, giấy màu.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV kiểm tra đồ dùng và sản phẩm tiết 1, khen ngợi, động viên.\n- GV cho HS so sánh nhanh hai mảng màu đậm - nhạt, dẫn vào bài.","hs":"- HS trưng bày sản phẩm tiết 1.\n- HS quan sát, so sánh màu đậm - nhạt."},{"ten":"2. Khám phá — Màu đậm, màu nhạt","gv":"- GV cho HS quan sát tác phẩm hội họa, chỉ ra chỗ màu đậm, màu nhạt và cách các màu đứng cạnh nhau.\n- GV đặt câu hỏi: Màu nào đậm? Màu nào nhạt? Khi đặt cạnh nhau, chúng tạo cảm giác gì?\n- GV chốt: kết hợp màu đậm - nhạt làm bức tranh sinh động hơn.","hs":"- HS quan sát, chỉ ra màu đậm, màu nhạt.\n- HS trả lời câu hỏi.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập — Sáng tạo","gv":"- GV yêu cầu HS tạo những mảng màu thể hiện rõ màu đậm, màu nhạt.\n- GV gợi ý cách pha màu để có sắc đậm - nhạt; quan sát, giúp đỡ HS.","hs":"- HS thực hành tạo mảng màu đậm - nhạt.\n- HS hoàn thiện sản phẩm."},{"ten":"4. Vận dụng","gv":"- GV cho HS chia sẻ: sản phẩm của em có màu đậm, nhạt ở đâu?\n- GV khen ngợi, dặn HS chuẩn bị cho tiết 3.","hs":"- HS chia sẻ về màu đậm - nhạt trong sản phẩm.\n- HS ghi nhớ nhiệm vụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở một bức ảnh trong phần mềm xem ảnh rồi kéo thanh chỉnh độ sáng để cả bức chuyển từ đậm sang nhạt ngay trước mắt HS; kéo qua kéo lại vài lần cho HS thấy cùng một màu vẫn có nhiều mức đậm nhạt.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) HS chỉ ra trong ảnh chỗ nào đậm nhất, chỗ nào nhạt nhất và nói chỗ đậm đã làm hình nổi lên thế nào.\n⚠ (Miền 4: An toàn) GV điều khiển thanh chỉnh sáng; sau đó HS pha thêm nước hoặc tô chồng lớp trên giấy để tự tạo độ đậm nhạt bằng tay, màn hình chỉ giúp nhìn thấy trước kết quả.","hs":"- HS nhận ra một màu có nhiều mức đậm nhạt khi xem ảnh được chỉnh sáng.\n- HS tạo được mảng đậm, mảng nhạt trên bài vẽ của mình."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":9,"tiet":9,"bai":"Chủ đề 4: NHỮNG MẢNG MÀU YÊU THÍCH — Tiết 3: Thảo luận và vận dụng","yccd":"1. Năng lực mĩ thuật\n- Củng cố kiến thức về màu sắc, màu đậm, màu nhạt đã học.\n- Sử dụng những mảng màu yêu thích để trang trí một đồ vật.\n- Nêu được cảm nhận về màu sắc trong sản phẩm của mình và của bạn.\n2. Năng lực chung\n- Giao tiếp và hợp tác: trao đổi nhóm, trình bày cảm nhận.\n- Giải quyết vấn đề và sáng tạo: chọn màu phù hợp để trang trí đồ vật.\n3. Phẩm chất\n- Yêu thích cái đẹp; giữ gìn, trân trọng sản phẩm do mình tạo ra.\n4. Tích hợp\n- Năng lực số 1.3 CB1a: Xác định được cách tổ chức, lưu trữ và truy xuất dữ liệu, thông tin và nội dung một cách đơn giản trong môi trường số: HS lấy được ý tưởng sắp xếp mảng màu từ bộ ảnh đồ vật.","dodung":"- GV: một vài đồ vật đã trang trí bằng mảng màu (hộp bút, khung ảnh bìa, quạt giấy) làm mẫu; bảng màu đậm - nhạt; thiết bị trình chiếu.\n- GV chuẩn bị vật liệu thay thế cho lớp thiếu đồ dùng: bìa carton cắt thành khung, vỏ hộp sữa, hộp bánh cũ, giấy báo cũ, vải vụn, dây len, lá cây khô ép phẳng để dán thay giấy màu.\n- HS: sản phẩm các tiết trước, màu vẽ (sáp màu hoặc màu nước), giấy màu, một đồ vật để trang trí (hộp bút, vỏ hộp, tấm bìa), kéo, hồ dán, khăn lau tay, tờ báo cũ lót bàn.","hoatdong":[{"ten":"1. Khởi động","gv":"- (3 phút) GV kiểm tra sản phẩm tiết 2 của từng bàn, khen ngợi bạn hoàn thành đúng hạn, động viên bạn còn dở dang.\n- GV giơ nhanh hai tấm bìa cùng màu xanh nhưng một đậm một nhạt, hỏi: Hai tấm này khác nhau chỗ nào? Dự kiến HS trả lời: một tấm màu đậm, một tấm màu nhạt.\n- GV giới thiệu nhiệm vụ tiết học: cùng nhau nói về màu trong bài của bạn, sau đó dùng những mảng màu mình thích để trang trí một đồ vật.","hs":"- HS đặt sản phẩm tiết 2 lên bàn cho GV và các bạn cùng xem.\n- HS quan sát hai tấm bìa và trả lời: một tấm đậm hơn, một tấm nhạt hơn.\n- HS lắng nghe, nắm nhiệm vụ của tiết học và chuẩn bị đồ dùng."},{"ten":"2. Khám phá — Thảo luận","gv":"- (7 phút) GV chia lớp thành nhóm 4, mỗi nhóm đặt bài của các bạn ra giữa bàn để cùng xem.\n- GV nêu câu hỏi thảo luận, ghi sẵn lên bảng: Bài của bạn dùng những màu nào? Đâu là mảng màu đậm, đâu là mảng màu nhạt? Em thích mảng màu nào nhất, vì sao?\n- GV mời 3 nhóm trình bày. Dự kiến HS trả lời: bài của bạn có màu vàng, đỏ, xanh lá; mảng đỏ đậm nằm ở giữa, mảng vàng nhạt ở xung quanh; em thích mảng đỏ vì nhìn nổi bật.\n- GV chốt: mảng màu đậm đặt cạnh mảng màu nhạt thì cả hai đều nổi lên; nên chọn ít màu nhưng sắp xếp có chỗ to chỗ nhỏ, đừng tô kín một màu khắp bài.","hs":"- HS về nhóm 4, đặt bài của mình ra giữa bàn cùng xem.\n- HS lần lượt nói về bài của bạn theo ba câu hỏi trên bảng.\n- HS đại diện nhóm trình bày: kể tên màu, chỉ mảng đậm, mảng nhạt và nêu mảng mình thích.\n- HS nhắc lại ý chốt: đậm đặt cạnh nhạt, mảng có chỗ to chỗ nhỏ thì bài đẹp hơn."},{"ten":"3. Luyện tập — Vận dụng","gv":"- (14 phút) GV làm mẫu chậm bước khó: cắt giấy màu thành mảng to nhỏ khác nhau rồi ướm thử lên đồ vật trước, thấy ưng mới bôi hồ dán.\n- GV nêu các bước thực hành: bước 1 chọn đồ vật cần trang trí; bước 2 chọn hai đến ba màu mình thích; bước 3 cắt hoặc xé các mảng màu to nhỏ khác nhau; bước 4 ướm thử và sắp xếp mảng đậm xen mảng nhạt; bước 5 dán chắc rồi tô thêm chấm, vạch cho sinh động.\n- GV nhắc bạn không có giấy màu thì dùng giấy báo cũ tô màu, vỏ hộp bánh có màu sẵn, vải vụn, lá cây khô để dán thay.\n- GV đi từng bàn giúp đỡ, nhắc an toàn: mũi kéo hướng xuống bàn, hồ dán bôi mỏng và không cho tay bẩn lên mặt, màu nước rơi ra bàn thì lau ngay.","hs":"- HS quan sát GV làm mẫu cách ướm thử mảng màu trước khi dán.\n- HS thực hành theo 5 bước: chọn đồ vật, chọn màu, cắt mảng, ướm thử, dán và tô thêm chi tiết.\n- HS thiếu giấy màu thì dùng giấy báo tô màu, vỏ hộp bánh, vải vụn, lá cây khô thay thế.\n- HS giữ an toàn khi dùng kéo và hồ dán, lau ngay chỗ màu bị rơi ra bàn."},{"ten":"4. Vận dụng — Trưng bày","gv":"- (7 phút) GV cho các nhóm dán hoặc đặt sản phẩm lên bảng nhóm theo chủ đề, ghép lại thành một phòng tranh mini ở góc lớp.\n- GV mời HS giới thiệu: Em dùng những màu gì để trang trí? Mảng nào là mảng đậm? Em sẽ dùng đồ vật này vào việc gì?\n- GV nêu tiêu chí nhận xét sản phẩm: một là có đủ mảng màu đậm và mảng màu nhạt; hai là các mảng sắp xếp cân đối, không chen chúc một chỗ; ba là màu sắc hài hoà, nhìn dễ chịu; bốn là bài sạch sẽ, dán chắc, có ý tưởng riêng.\n- GV cho HS đi xem phòng tranh mini, mỗi bạn dán một ngôi sao vào sản phẩm mình thích và nói một câu vì sao thích.\n- GV nhận xét, động viên; dặn xem trước Chủ đề 5 và chuẩn bị đất nặn hoặc vỏ hộp; nhắc HS thu gom giấy vụn, lau bàn, rửa tay.","hs":"- HS cùng nhóm dán sản phẩm lên bảng nhóm, tạo thành phòng tranh mini.\n- HS giới thiệu sản phẩm: màu đã dùng, mảng đậm ở đâu, đồ vật dùng để làm gì.\n- HS nhắc lại 4 tiêu chí nhận xét trước khi đi xem bài.\n- HS đi xem, dán ngôi sao vào bài mình thích và nói một câu vì sao thích.\n- HS ghi nhớ việc chuẩn bị cho Chủ đề 5, thu gom giấy vụn, lau bàn và rửa tay."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu bộ ảnh đồ vật quen thuộc được trang trí bằng mảng màu: cặp sách, hộp bút, chiếc quạt giấy, tấm rèm; mỗi ảnh có ghi tên người làm hoặc nơi cung cấp ảnh.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV nêu rõ mỗi mẫu trang trí đều do một người nghĩ ra; HS xem để lấy ý tưởng rồi tự nghĩ cách sắp xếp mảng màu của riêng mình chứ không vẽ lại y hệt mẫu.\n⚠ (Miền 4: An toàn) Ảnh mẫu do GV chọn sẵn, HS không xin chụp lại ảnh mẫu bằng điện thoại; lấy ý tưởng từ mẫu thì được, chép nguyên mẫu rồi nhận là của mình thì không được.","hs":"- HS lấy được ý tưởng sắp xếp mảng màu từ bộ ảnh đồ vật.\n- HS nêu được điểm khác giữa bài của mình với mẫu đã xem."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":10,"tiet":10,"bai":"Chủ đề 5: SỰ KẾT HỢP THÚ VỊ CỦA KHỐI — Tiết 1: Quan sát và thể hiện khối","yccd":"1. Năng lực mĩ thuật\n- Liên tưởng được sự kết hợp của khối đến những vật trong cuộc sống.\n- Tạo được một sản phẩm mĩ thuật có sự kết hợp của khối bằng đất nặn hoặc vật liệu.\n- Bước đầu nhận biết khối cầu, khối trụ, khối hộp trong đồ vật.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động quan sát, liên tưởng và lựa chọn vật liệu.\n- Giao tiếp và hợp tác: chia sẻ ý tưởng tạo khối với bạn.\n3. Phẩm chất\n- Yêu thích tạo hình khối; chăm chỉ, sáng tạo.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nhận ra các khối cơ bản trong một hình dáng phức tạp qua mô hình xoay.","dodung":"- Giáo viên: một số đồ vật dạng khối (khối cầu, trụ, hộp); sản phẩm mĩ thuật từ khối; đất nặn; thiết bị trình chiếu.\n- Học sinh: SGK Mĩ thuật 2, Vở bài tập Mĩ thuật 2, đất nặn, vật liệu tái sử dụng, bút màu, kéo, hồ dán.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS chơi trò chơi Sờ vật đoán khối: sờ đồ vật trong túi và đoán đó là khối gì.\n- GV nhận xét, tuyên dương, giới thiệu chủ đề.","hs":"- HS tham gia trò chơi, đoán khối.\n- HS lắng nghe, mở bài học."},{"ten":"2. Khám phá — Quan sát khối","gv":"- GV cho HS quan sát đồ vật dạng khối và hình trong SGK Mĩ thuật 2.\n- GV đặt câu hỏi: Đồ vật này có dạng khối gì? Sự kết hợp của khối gợi em liên tưởng đến vật gì?\n- GV chốt: khối kết hợp với nhau tạo nên hình dạng nhiều đồ vật, con vật.","hs":"- HS quan sát, trả lời câu hỏi.\n- HS liên tưởng khối đến các vật trong cuộc sống.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập — Sáng tạo","gv":"- GV hướng dẫn HS tham khảo cách tạo sản phẩm từ khối trong SGK.\n- GV yêu cầu HS thực hành nặn hoặc ghép tạo một sản phẩm mĩ thuật có sự kết hợp của khối.\n- GV quan sát, giúp đỡ; nhắc HS lưu giữ sản phẩm cho tiết sau.","hs":"- HS tham khảo, tiếp thu cách làm.\n- HS thực hành tạo sản phẩm từ khối.\n- HS lưu giữ sản phẩm."},{"ten":"4. Vận dụng","gv":"- GV cho HS chia sẻ: sản phẩm của em kết hợp những khối nào?\n- GV khen ngợi, dặn HS chuẩn bị cho tiết 2.","hs":"- HS chia sẻ về sản phẩm.\n- HS ghi nhớ nhiệm vụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu mô hình ba chiều một con vật, một chiếc xe và xoay chậm, đồng thời tách dần từng khối cầu, khối trụ, khối hộp tạo nên nó; HS nhìn thấy bên trong một hình dáng phức tạp chỉ là mấy khối đơn giản ghép lại.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) HS chọn một đồ vật trong lớp và đoán đồ vật đó gồm những khối nào.\n⚠ (Miền 4: An toàn) GV thao tác xoay và tách khối; xem xong HS cầm hộp giấy, quả bóng, ống giấy thật để ghép thử bằng tay.","hs":"- HS nhận ra các khối cơ bản trong một hình dáng phức tạp qua mô hình xoay.\n- HS đoán được các khối tạo nên một đồ vật thật."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":11,"tiet":11,"bai":"Chủ đề 5: SỰ KẾT HỢP THÚ VỊ CỦA KHỐI — Tiết 2: Sắp xếp các khối","yccd":"1. Năng lực mĩ thuật\n- Liên tưởng được sự sắp xếp của khối đến những vật trong cuộc sống.\n- Sắp xếp các khối tạo nên một sản phẩm mĩ thuật yêu thích.\n- Biết sắp đặt các khối cân đối, hài hòa.\n2. Năng lực chung\n- Giải quyết vấn đề và sáng tạo: sắp xếp khối theo ý tưởng riêng.\n- Giao tiếp và hợp tác: phối hợp với bạn khi tạo sản phẩm.\n3. Phẩm chất\n- Chăm chỉ, kiên trì; yêu thích tạo hình từ khối.","dodung":"- GV: một sản phẩm mĩ thuật sắp xếp từ nhiều khối (ngôi nhà, tháp, con vật) để HS quan sát; đất nặn nhiều màu, dao nhựa, đế bìa để đặt sản phẩm; thiết bị trình chiếu.\n- GV chuẩn bị vật liệu thay thế cho lớp thiếu đồ dùng: vỏ hộp thuốc, hộp sữa, lõi giấy, nắp chai, bìa carton gấp thành khối, giấy báo cũ vò tròn, hột hạt, dây len, vải vụn.\n- HS: sản phẩm tiết 1, đất nặn hoặc đất sét, vật liệu tái sử dụng đã rửa sạch, bút màu, kéo, hồ dán, khăn lau tay, tờ báo cũ lót bàn.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV kiểm tra sản phẩm tiết 1 và đồ dùng của từng bàn, khen ngợi, động viên; cho mượn vật liệu dự phòng với bạn còn thiếu.\n- GV đặt lên bàn một sản phẩm sắp xếp từ nhiều khối và che bằng khăn, sau đó mở ra cho HS xem trong ít giây rồi hỏi: Em vừa nhìn thấy vật gì? Vật ấy gồm những khối nào?\n- Dự kiến HS trả lời: em thấy một ngôi nhà, có khối hộp làm thân nhà và khối tam giác làm mái.\n- GV dẫn vào bài: hôm nay cả lớp sẽ sắp xếp các khối để tạo một sản phẩm mĩ thuật mình yêu thích.","hs":"- HS đặt sản phẩm tiết 1 và đồ dùng lên bàn cho GV kiểm tra.\n- HS chăm chú quan sát sản phẩm khi GV mở khăn.\n- HS trả lời: đó là ngôi nhà, gồm khối hộp làm thân và khối tam giác làm mái.\n- HS lắng nghe và nắm nhiệm vụ của tiết học."},{"ten":"2. Khám phá — Sắp xếp khối","gv":"- (7 phút) GV cho HS mở SGK quan sát hình về cách sắp xếp khối, đồng thời chuyền tay sản phẩm mẫu để cả lớp nhìn gần.\n- GV nêu câu hỏi gợi mở: Các khối được sắp xếp thế nào, chồng lên nhau hay đặt cạnh nhau? Cách sắp xếp ấy gợi em liên tưởng đến vật gì? Làm sao để sản phẩm không bị đổ và nhìn cân đối?\n- Dự kiến HS trả lời: các khối vừa chồng lên nhau vừa đặt cạnh nhau; em liên tưởng đến toà nhà, đoàn tàu, con vật; muốn không đổ thì khối to và nặng phải đặt ở dưới.\n- GV chốt: sắp xếp khối cần chú ý ba điều là khối lớn đặt dưới làm bệ đỡ, các khối cao thấp xen kẽ cho đỡ đơn điệu, và chừa khoảng trống hợp lí để nhìn rõ từng khối.","hs":"- HS mở SGK quan sát hình và chuyền tay xem sản phẩm mẫu.\n- HS trả lời các câu hỏi: khối chồng lên nhau và đặt cạnh nhau, gợi liên tưởng đến toà nhà, đoàn tàu, con vật.\n- HS nêu cách giữ cho sản phẩm không đổ: đặt khối to, nặng ở dưới.\n- HS nhắc lại ba điều cần nhớ khi sắp xếp khối cho cân đối."},{"ten":"3. Luyện tập — Sáng tạo","gv":"- (16 phút) GV làm mẫu chậm bước khó là gắn khối cho vững: dùng một khối đất nhỏ làm chốt nối giữa hai khối, hoặc dán vỏ hộp bằng băng dính hai mặt rồi ấn giữ vài giây.\n- GV nêu các bước thực hành: bước 1 chọn vật mình muốn tạo; bước 2 nặn hoặc chuẩn bị đủ các khối cần dùng; bước 3 xếp thử các khối chưa gắn để xem có cân đối chưa; bước 4 gắn chắc từ dưới lên trên; bước 5 thêm chi tiết và màu cho sản phẩm sinh động.\n- GV nhắc bạn thiếu đất nặn có thể dùng vỏ hộp thuốc, hộp sữa, lõi giấy, nắp chai, bìa carton gấp lại, giấy báo cũ vò tròn bọc giấy màu.\n- GV đi từng bàn hỗ trợ, gợi ý riêng cho bạn chưa nghĩ ra ý tưởng bằng câu hỏi: Nhà em có con vật nào? Trên đường đi học em thấy công trình gì?\n- GV nhắc an toàn: mũi kéo hướng xuống bàn, không dùng vỏ hộp có cạnh sắc, không đưa đất nặn lên miệng; báo trước khi còn 3 phút để HS hoàn thiện.","hs":"- HS quan sát GV làm mẫu cách nối khối cho vững.\n- HS thực hành theo 5 bước: chọn vật, tạo các khối, xếp thử, gắn chắc từ dưới lên, thêm chi tiết và màu.\n- HS thiếu đất nặn thì dùng vỏ hộp, lõi giấy, nắp chai, bìa carton, giấy báo vò tròn thay thế.\n- HS trả lời gợi ý của GV để tìm ý tưởng cho sản phẩm của mình.\n- HS giữ an toàn khi dùng kéo và vật liệu, hoàn thiện sản phẩm đúng giờ."},{"ten":"4. Vận dụng","gv":"- (8 phút) GV cho HS đặt sản phẩm lên bàn nhóm, mỗi nhóm một khu, tạo thành phòng trưng bày mini ở góc lớp.\n- GV mời 4 đến 5 HS chia sẻ: Em sắp xếp các khối thành hình gì? Khối nào em đặt ở dưới cùng? Vì sao em chọn cách sắp xếp đó?\n- GV nêu tiêu chí nhận xét sản phẩm: một là có từ ba khối trở lên được sắp xếp; hai là sản phẩm đứng vững, gắn chắc; ba là các khối cao thấp cân đối, dễ nhận ra vật gì; bốn là bài sạch sẽ, có ý tưởng riêng.\n- GV cho HS đi xem một vòng, mỗi bạn dán một ngôi sao giấy vào sản phẩm mình thích rồi nói một câu vì sao thích.\n- GV khen ngợi, dặn HS cất sản phẩm cẩn thận vào hộp để dùng cho tiết 3, chuẩn bị thêm vật liệu cho sản phẩm nhóm; nhắc lau bàn, nhặt vụn đất, rửa tay.","hs":"- HS đặt sản phẩm lên bàn nhóm theo khu vực của nhóm mình.\n- HS chia sẻ: tên vật đã tạo, khối đặt dưới cùng và lí do chọn cách sắp xếp.\n- HS nghe và nhắc lại 4 tiêu chí nhận xét sản phẩm.\n- HS đi xem, dán ngôi sao vào sản phẩm mình thích và nói một câu vì sao thích.\n- HS cất sản phẩm, ghi nhớ việc chuẩn bị cho tiết 3, lau bàn, nhặt vụn đất và rửa tay."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":12,"tiet":12,"bai":"Chủ đề 5: SỰ KẾT HỢP THÚ VỊ CỦA KHỐI — Tiết 3: Thảo luận và vận dụng (sản phẩm nhóm)","yccd":"1. Năng lực mĩ thuật\n- Củng cố kiến thức về khối và sự kết hợp của khối đã học.\n- Sắp xếp các khối theo một chủ đề để tạo sản phẩm nhóm.\n- Nêu được cảm nhận về sản phẩm của mình và của nhóm bạn.\n2. Năng lực chung\n- Giao tiếp và hợp tác: phối hợp trong nhóm để tạo sản phẩm chung theo chủ đề.\n3. Phẩm chất\n- Đoàn kết, biết chia sẻ công việc; trân trọng sản phẩm chung.\n4. Tích hợp\n- Năng lực số 1.3 CB1a: Xác định được cách tổ chức, lưu trữ và truy xuất dữ liệu, thông tin và nội dung một cách đơn giản trong môi trường số: HS nêu được cách sắp xếp cao thấp, thưa dày cho mô hình nhóm.","dodung":"- GV: một mô hình nhóm mẫu (khu vườn nhỏ hoặc góc phố) đặt trên tấm bìa; đất nặn, vật liệu tạo khối, thẻ tên nhóm; thiết bị trình chiếu.\n- GV chuẩn bị vật liệu thay thế cho lớp thiếu đồ dùng: bìa carton làm đế, vỏ hộp sữa, hộp thuốc, lõi giấy, nắp chai, que kem, giấy báo cũ, lá cây khô, hột hạt, dây len, vải vụn.\n- HS: sản phẩm các tiết trước, đất nặn, vật liệu tái sử dụng đã rửa sạch, bút màu, kéo, hồ dán, một tấm bìa to làm đế chung của nhóm, khăn lau tay.","hoatdong":[{"ten":"1. Khởi động","gv":"- (3 phút) GV kiểm tra sản phẩm tiết 2 và vật liệu của từng nhóm, khen ngợi nhóm chuẩn bị đủ, cho mượn vật liệu dự phòng với nhóm còn thiếu.\n- GV đặt mô hình mẫu lên bàn giữa lớp và hỏi: Đây là nơi nào? Vì sao em nhận ra? Dự kiến HS trả lời: đây là một khu vườn vì có cây, có lối đi và hàng rào.\n- GV giới thiệu nhiệm vụ tiết học: mỗi nhóm sẽ ghép sản phẩm riêng của các bạn thành một mô hình chung theo một chủ đề mà nhóm tự chọn.","hs":"- HS đặt sản phẩm tiết 2 và vật liệu lên bàn nhóm cho GV kiểm tra.\n- HS quan sát mô hình mẫu và trả lời: đó là khu vườn vì có cây, lối đi và hàng rào.\n- HS lắng nghe, nắm nhiệm vụ tiết học và ngồi về vị trí nhóm của mình."},{"ten":"2. Khám phá — Thảo luận","gv":"- (7 phút) GV chia lớp thành các nhóm 4 đến 6 bạn, phát cho mỗi nhóm một tấm bìa làm đế chung và một thẻ ghi tên nhóm.\n- GV nêu câu hỏi thảo luận: Nhóm em sẽ tạo chủ đề gì, khu vườn, thành phố hay sở thú? Cần những khối nào cho chủ đề đó? Ai làm phần nào để không bạn nào ngồi chơi?\n- Dự kiến HS trả lời: nhóm em chọn khu vườn, cần khối trụ làm thân cây, khối tròn làm tán lá, khối hộp làm ghế đá; bạn A làm cây, bạn B làm hàng rào, bạn C làm lối đi, bạn D làm hoa.\n- GV chốt cách phối hợp nhóm: thống nhất chủ đề trước, chia việc rõ ràng, ai xong sớm thì giúp bạn, khi đặt lên đế chung phải hỏi ý cả nhóm chứ không tự ý dịch đồ của bạn.","hs":"- HS về nhóm, nhận tấm bìa làm đế chung và thẻ tên nhóm.\n- HS thảo luận và thống nhất chủ đề của nhóm mình.\n- HS kể các khối cần làm và tự nhận phần việc: cây, hàng rào, lối đi, hoa.\n- HS nhắc lại cách phối hợp: thống nhất trước, chia việc rõ, giúp bạn và hỏi ý cả nhóm khi sắp đặt."},{"ten":"3. Luyện tập — Sáng tạo nhóm","gv":"- (14 phút) GV làm mẫu chậm bước khó là cố định khối trên đế: bôi một chút hồ hoặc dùng viên đất nhỏ dán chân khối xuống bìa để mô hình không bị xô lệch khi bê đi.\n- GV nêu các bước thực hành: bước 1 nhóm vẽ nhẹ trên đế chỗ nào là lối đi, chỗ nào đặt vật; bước 2 mỗi bạn làm phần việc của mình; bước 3 cả nhóm xếp thử lên đế; bước 4 chỉnh cho chỗ cao chỗ thấp, chỗ thưa chỗ dày; bước 5 gắn chắc và ghi tên nhóm.\n- GV nhắc nhóm thiếu đất nặn thì dùng vỏ hộp, lõi giấy, que kem, nắp chai, giấy báo vò tròn, lá cây khô làm tán cây, dây len làm dây leo.\n- GV đi từng nhóm hỗ trợ, nhắc an toàn: mũi kéo hướng xuống bàn, không tranh giành vật liệu, không đưa đất nặn lên miệng; báo trước khi còn 3 phút để các nhóm hoàn thiện.","hs":"- HS quan sát GV làm mẫu cách cố định khối trên đế bìa.\n- HS làm theo 5 bước: vẽ bố trí trên đế, làm phần việc riêng, xếp thử, chỉnh cao thấp thưa dày, gắn chắc và ghi tên nhóm.\n- HS thiếu vật liệu thì dùng vỏ hộp, que kem, nắp chai, lá cây khô, dây len thay thế.\n- HS phối hợp trong nhóm, giữ an toàn khi dùng kéo và hoàn thiện mô hình đúng giờ."},{"ten":"4. Vận dụng — Trưng bày","gv":"- (7 phút) GV cho các nhóm bê mô hình đặt lên bàn kê thành hàng ở góc lớp, tạo thành một phòng trưng bày mini có thẻ tên nhóm đặt phía trước.\n- GV mời đại diện mỗi nhóm giới thiệu: Mô hình của nhóm em thể hiện chủ đề gì? Có những gì trong đó? Bạn nào làm phần nào?\n- GV nêu tiêu chí nhận xét sản phẩm nhóm: một là thể hiện đủ hình ảnh chính của chủ đề; hai là các khối sắp xếp cân đối, có cao có thấp, có chỗ trống làm lối đi; ba là gắn chắc, mô hình không đổ khi bê; bốn là mọi bạn trong nhóm đều có phần việc.\n- GV cho HS đi xem một vòng, mỗi bạn dán một ngôi sao vào mô hình nhóm mình thích rồi nói một câu vì sao thích.\n- GV nhận xét, động viên; dặn xem trước Chủ đề 6 và chuẩn bị màu vẽ, giấy vẽ; nhắc HS thu gom vụn đất, giấy, lau bàn và rửa tay.","hs":"- HS cùng nhóm bê mô hình đặt lên bàn trưng bày và đặt thẻ tên nhóm.\n- HS đại diện nhóm giới thiệu chủ đề, các hình ảnh chính và phần việc của từng bạn.\n- HS nghe và nhắc lại 4 tiêu chí nhận xét sản phẩm nhóm.\n- HS đi xem, dán ngôi sao vào mô hình mình thích và nói một câu vì sao thích.\n- HS ghi nhớ việc chuẩn bị cho Chủ đề 6, thu gom vụn đất và giấy, lau bàn, rửa tay."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu ảnh chụp từ trên cao một khu vườn, một góc phố để nhóm HS thấy cách người ta sắp xếp: chỗ nào cao, chỗ nào thấp, chỗ nào để trống làm lối đi.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 1) Mỗi nhóm bàn nhau chọn một cách sắp xếp và phân công ai làm khối nào; GV chụp ảnh mô hình của nhóm ở giữa giờ để nhóm nhìn lại tổng thể và chỉnh cho cân đối.\n⚠ (Miền 4: An toàn) Ảnh chụp mô hình chỉ dùng để nhóm tự chỉnh sản phẩm, không đưa ra ngoài lớp; khi bàn bạc, mỗi bạn đều được nói, không giành làm hết phần của bạn khác.","hs":"- HS nêu được cách sắp xếp cao thấp, thưa dày cho mô hình nhóm.\n- HS nhìn ảnh chụp giữa giờ và chỉnh lại mô hình cho cân đối."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":13,"tiet":13,"bai":"Chủ đề 6: SẮC MÀU THIÊN NHIÊN — Tiết 1: Quan sát và thể hiện sắc màu","yccd":"1. Năng lực mĩ thuật\n- Nhận biết được màu sắc trong thiên nhiên, cuộc sống.\n- Làm một sản phẩm mĩ thuật thể hiện sắc màu trong cuộc sống mình yêu thích (hình thức xé, dán, nặn).\n- Bước đầu cảm nhận vẻ đẹp của sắc màu thiên nhiên.\n2. Năng lực chung\n- Tự chủ và tự học: quan sát thiên nhiên, lựa chọn màu và hình thức thể hiện.\n- Giao tiếp và hợp tác: chia sẻ cảm nhận về sắc màu thiên nhiên.\n3. Phẩm chất\n- Yêu thiên nhiên; có ý thức bảo vệ môi trường, cảnh quan xung quanh.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nêu được màu chủ đạo của từng mùa sau khi xem phim tua nhanh.","dodung":"- Giáo viên: tranh ảnh thiên nhiên nhiều màu (bầu trời, cây cối, hoa lá, cánh đồng); thiết bị trình chiếu.\n- Học sinh: SGK Mĩ thuật 2, Vở bài tập Mĩ thuật 2, màu vẽ, giấy vẽ, giấy màu, đất nặn, kéo, hồ dán, lá cây, cành hoa khô.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS xem nhanh hình ảnh thiên nhiên và hỏi: Em thấy những màu nào trong thiên nhiên?\n- GV nhận xét, giới thiệu chủ đề.","hs":"- HS quan sát, kể tên màu sắc thiên nhiên.\n- HS lắng nghe, mở bài học."},{"ten":"2. Khám phá — Sắc màu thiên nhiên","gv":"- GV cho HS quan sát hình trong SGK Mĩ thuật 2 và tranh ảnh thiên nhiên.\n- GV đặt câu hỏi: Bầu trời, cây cối, hoa lá có màu gì? Sắc màu nào em yêu thích nhất?\n- GV chốt: thiên nhiên có sắc màu phong phú, tươi đẹp.","hs":"- HS quan sát, trả lời câu hỏi.\n- HS nêu sắc màu yêu thích.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập — Sáng tạo","gv":"- GV hướng dẫn HS tham khảo cách làm sản phẩm bằng xé, dán, nặn trong SGK.\n- GV yêu cầu HS làm một sản phẩm thể hiện sắc màu thiên nhiên mình yêu thích.\n- GV quan sát, giúp đỡ; nhắc HS lưu giữ sản phẩm cho tiết sau.","hs":"- HS tham khảo, chọn hình thức thể hiện.\n- HS thực hành làm sản phẩm về sắc màu thiên nhiên.\n- HS lưu giữ sản phẩm."},{"ten":"4. Vận dụng","gv":"- GV cho HS chia sẻ: sản phẩm của em thể hiện sắc màu gì của thiên nhiên?\n- GV khen ngợi, dặn HS chuẩn bị cho tiết 2.","hs":"- HS chia sẻ về sản phẩm.\n- HS ghi nhớ nhiệm vụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu đoạn phim tua nhanh một cây thay lá qua bốn mùa: xanh non, xanh đậm, vàng, trơ cành; cả năm trời được nén trong một phút nên HS thấy được sự đổi màu mà quan sát ngoài sân trong một tiết học không thể thấy.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) HS gọi tên màu chủ đạo của từng mùa và liên hệ với cây cối ở quê mình.\n⚠ (Miền 4: An toàn) GV mở đúng đoạn phim đã tải sẵn, không mở trang chia sẻ phim có nội dung gợi ý chen ngang; xem phim xong HS ra sân quan sát một cái cây thật để đối chiếu.","hs":"- HS nêu được màu chủ đạo của từng mùa sau khi xem phim tua nhanh.\n- HS kể được sự đổi màu của cây cối ở nơi mình sống."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":14,"tiet":14,"bai":"Chủ đề 6: SẮC MÀU THIÊN NHIÊN — Tiết 2: Vẽ tranh sắc màu thiên nhiên","yccd":"1. Năng lực mĩ thuật\n- Nhận biết màu sắc trong tác phẩm hội họa về thiên nhiên.\n- Vẽ được một bức tranh thể hiện vẻ sắc màu thiên nhiên (chú ý màu đậm, màu nhạt, sự kết hợp của màu).\n- Biết phối màu để tranh thêm sinh động.\n2. Năng lực chung\n- Giải quyết vấn đề và sáng tạo: chọn nội dung và màu sắc phù hợp để vẽ tranh.\n- Giao tiếp và hợp tác: chia sẻ cảm nhận về tranh của bạn.\n3. Phẩm chất\n- Yêu thiên nhiên; chăm chỉ, kiên trì hoàn thành tranh.","dodung":"- GV: hai đến ba tranh phong cảnh thiên nhiên in khổ to (cánh đồng, bờ biển, vườn cây); một tranh mẫu do GV vẽ để làm mẫu từng bước; thiết bị trình chiếu.\n- GV chuẩn bị vật liệu thay thế cho lớp thiếu đồ dùng: giấy báo cũ hoặc mặt sau tờ lịch để vẽ, bút chì màu dùng chung theo bàn, giấy màu, lá cây khô, vải vụn để xé dán thay cho vẽ màu.\n- HS: sản phẩm tiết 1, màu vẽ (sáp màu hoặc màu nước), giấy vẽ, bút chì, tẩy, khăn lau tay, tờ báo cũ lót bàn.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV kiểm tra sản phẩm tiết 1 và đồ dùng của từng bàn, khen ngợi, động viên; cho mượn màu và giấy dự phòng với bạn còn thiếu.\n- GV treo một bức tranh phong cảnh lên bảng và hỏi: Bức tranh vẽ cảnh gì? Nhìn tranh em thấy trời nắng hay trời mưa? Vì sao em biết?\n- Dự kiến HS trả lời: tranh vẽ cánh đồng; trời nắng vì bầu trời màu xanh sáng và cây cối màu vàng ấm.\n- GV dẫn vào bài: màu sắc giúp bức tranh kể được cả thời tiết và tình cảm; hôm nay cả lớp sẽ vẽ một bức tranh về sắc màu thiên nhiên.","hs":"- HS đặt sản phẩm tiết 1 và đồ dùng lên bàn cho GV kiểm tra.\n- HS quan sát bức tranh trên bảng và trả lời câu hỏi của GV.\n- HS nêu: tranh vẽ cánh đồng, trời nắng vì bầu trời xanh sáng, cây cối màu vàng.\n- HS lắng nghe và nắm nhiệm vụ của tiết học."},{"ten":"2. Khám phá — Xem tranh thiên nhiên","gv":"- (7 phút) GV cho HS quan sát lần lượt ba bức tranh phong cảnh, mỗi bức khoảng một phút, đồng thời chỉ vào từng mảng màu trên tranh.\n- GV nêu câu hỏi gợi mở: Tranh có những màu nào? Đâu là mảng màu đậm, đâu là mảng màu nhạt? Bầu trời và mặt đất được vẽ bằng những màu nào? Các màu ấy đứng cạnh nhau có hợp không?\n- Dự kiến HS trả lời: tranh có màu xanh, vàng, nâu; thân cây và bụi cỏ gần là mảng đậm, bầu trời xa là mảng nhạt; bầu trời màu xanh nhạt, mặt đất màu nâu vàng.\n- GV chốt: vật ở gần thường vẽ đậm và rõ, vật ở xa vẽ nhạt và mờ hơn; một bức tranh chỉ cần vài màu chính rồi thay đổi đậm nhạt là đã sinh động.","hs":"- HS quan sát lần lượt ba bức tranh và chỉ ra các mảng màu theo tay GV.\n- HS trả lời: tranh có màu xanh, vàng, nâu; mảng gần đậm, mảng xa nhạt.\n- HS nêu màu của bầu trời và mặt đất trong tranh.\n- HS nhắc lại ý chốt: gần thì đậm và rõ, xa thì nhạt và mờ."},{"ten":"3. Luyện tập — Sáng tạo","gv":"- (16 phút) GV làm mẫu chậm hai bước khó: vẽ đường chân trời chia giấy thành phần trời và phần đất, sau đó tô màu nền bằng nét đi cùng một chiều cho phẳng, không di loạn.\n- GV nêu các bước thực hành: bước 1 chọn cảnh mình yêu thích như vườn cây, cánh đồng, bờ biển; bước 2 vẽ đường chân trời và hình ảnh chính to ở giữa giấy; bước 3 vẽ thêm hình ảnh phụ như mây, chim, hoa; bước 4 tô màu nền trước rồi tô hình ảnh chính sau; bước 5 nhấn đậm ở vật gần và giữ nhạt ở vật xa.\n- GV nhắc bạn thiếu giấy vẽ có thể dùng mặt sau tờ lịch hoặc giấy báo cũ; thiếu màu thì mượn theo bàn hoặc xé dán giấy màu, lá cây khô, vải vụn để tạo mảng màu.\n- GV đi từng bàn hỗ trợ, gợi ý riêng cho bạn chưa nghĩ ra cảnh vẽ: Nhà em có cây gì? Đường em đi học có gì đẹp?\n- GV nhắc giữ vệ sinh: rửa bút trước khi đổi màu, không vẩy màu sang bài của bạn; báo trước khi còn 3 phút để HS hoàn thiện và ghi tên vào góc tranh.","hs":"- HS quan sát GV làm mẫu cách vẽ đường chân trời và cách tô màu nền cho phẳng.\n- HS thực hành theo 5 bước: chọn cảnh, vẽ chân trời và hình chính, vẽ hình phụ, tô nền rồi tô hình chính, nhấn đậm vật ở gần.\n- HS thiếu giấy hoặc màu thì dùng mặt sau tờ lịch, giấy báo, giấy màu, lá cây khô, vải vụn.\n- HS trả lời gợi ý của GV để chọn được cảnh thiên nhiên mình muốn vẽ.\n- HS giữ vệ sinh khi dùng màu, hoàn thiện tranh và ghi tên vào góc tranh."},{"ten":"4. Vận dụng","gv":"- (8 phút) GV cho HS dán tranh lên bảng nhóm theo chủ đề, ghép các bảng nhóm thành một phòng tranh mini ở góc lớp.\n- GV mời 4 đến 5 HS chia sẻ: Tranh của em thể hiện cảnh thiên nhiên nào? Em đã dùng những màu gì? Chỗ nào trong tranh em tô đậm nhất?\n- GV nêu tiêu chí nhận xét sản phẩm: một là thể hiện rõ cảnh thiên nhiên với hình ảnh chính to, dễ nhận ra; hai là bố cục cân đối, không dồn hết về một góc; ba là màu sắc hài hoà, có đậm có nhạt; bốn là bài sạch sẽ, có ý tưởng riêng.\n- GV cho HS đi xem phòng tranh mini, mỗi bạn dán một ngôi sao vào bức tranh mình thích rồi nói một câu vì sao thích.\n- GV khen ngợi, dặn HS lưu giữ tranh cho tiết 3 và chuẩn bị lá cây, củ quả, màu nước để học in; nhắc lau bàn, cất màu, rửa tay.","hs":"- HS dán tranh của mình lên bảng nhóm cùng các bạn.\n- HS chia sẻ: cảnh đã vẽ, các màu đã dùng và chỗ tô đậm nhất trong tranh.\n- HS nghe và nhắc lại 4 tiêu chí nhận xét tranh.\n- HS đi xem, dán ngôi sao vào tranh mình thích và nói một câu vì sao thích.\n- HS lưu giữ tranh, ghi nhớ việc chuẩn bị lá cây và củ quả cho tiết 3, lau bàn và rửa tay."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":15,"tiet":15,"bai":"Chủ đề 6: SẮC MÀU THIÊN NHIÊN — Tiết 3: Trang trí bằng hình thức in","yccd":"1. Năng lực mĩ thuật\n- Củng cố kiến thức về sắc màu thiên nhiên đã học.\n- Trang trí một đồ vật bằng hình thức in (từ củ, quả, lá cây).\n- Biết tạo họa tiết lặp lại bằng cách in để trang trí.\n2. Năng lực chung\n- Giải quyết vấn đề và sáng tạo: lựa chọn vật liệu tự nhiên để in họa tiết.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ cách in với bạn.\n3. Phẩm chất\n- Yêu thiên nhiên; có ý thức sử dụng vật liệu tự nhiên để sáng tạo.","dodung":"- GV: một vài sản phẩm in mẫu (khăn giấy, túi giấy, bìa vở in họa tiết lá); củ khoai, quả mướp đắng, đoạn thân chuối cắt ngang, lá bàng, lá khoai; màu nước, đĩa nhựa đựng màu, giẻ lau; thiết bị trình chiếu.\n- GV chuẩn bị vật liệu thay thế cho lớp thiếu đồ dùng: lá cây nhặt ở sân trường, cùi bắp, nắp chai, ống hút cắt ngắn, vỏ hộp bìa carton cắt hình, giấy báo cũ để in nháp, giấy màu để dán nền.\n- HS: sản phẩm các tiết trước, lá cây, củ quả mang từ nhà, màu nước hoặc màu bột, giấy, một đồ vật để trang trí (bìa vở, túi giấy, hộp bút), khăn lau tay, tờ báo cũ lót bàn.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV kiểm tra sản phẩm tiết 2 và vật liệu HS mang tới, khen ngợi bạn chuẩn bị đủ lá cây, củ quả; chia bớt vật liệu dự phòng cho bạn còn thiếu.\n- GV giơ một tờ giấy đã in sẵn họa tiết lá và hỏi: Hình chiếc lá này cô làm bằng cách nào, vẽ hay in? Vì sao em đoán vậy?\n- Dự kiến HS trả lời: hình này in ra vì các chiếc lá giống hệt nhau và nhìn rõ gân lá.\n- GV dẫn vào bài: hôm nay cả lớp sẽ dùng lá cây, củ quả chấm màu để in họa tiết trang trí cho một đồ vật.","hs":"- HS đặt sản phẩm tiết 2 và vật liệu đã mang lên bàn cho GV kiểm tra.\n- HS quan sát tờ giấy in mẫu và trả lời câu hỏi của GV.\n- HS nêu: hình được in ra vì các chiếc lá giống hệt nhau và có gân lá.\n- HS lắng nghe và nắm nhiệm vụ của tiết học."},{"ten":"2. Khám phá — Kĩ thuật in","gv":"- (7 phút) GV cho HS chuyền tay xem các sản phẩm in mẫu và các vật liệu sẽ dùng để in: lá bàng, nửa củ khoai, lát thân chuối, nắp chai.\n- GV nêu câu hỏi gợi mở: In tạo ra họa tiết như thế nào? Vì sao mặt sau của lá lại in rõ hơn mặt trước? Muốn họa tiết in sắc nét thì cần chú ý gì?\n- Dự kiến HS trả lời: in ra nhiều hình giống nhau; mặt sau lá có gân nổi nên in rõ hơn; cần chấm màu vừa phải và ấn đều tay.\n- GV thị phạm chậm cả quy trình: phết một lớp màu mỏng lên mặt sau chiếc lá, đặt lá úp xuống giấy, lấy tờ giấy sạch đè lên rồi miết đều từ giữa ra ngoài, cuối cùng nhấc lá lên thật nhẹ.\n- GV chốt: màu quá loãng thì hình bị nhoè, màu quá đặc thì hình bị bết; miết đều tay và nhấc nhẹ thì họa tiết sẽ sắc nét.","hs":"- HS chuyền tay xem sản phẩm in mẫu và các vật liệu dùng để in.\n- HS trả lời: in cho ra nhiều hình giống nhau, mặt sau lá có gân nổi nên in rõ hơn.\n- HS quan sát GV thị phạm từng thao tác phết màu, úp lá, miết đều và nhấc nhẹ.\n- HS nhắc lại lưu ý: màu vừa phải, miết đều tay, nhấc lá thật nhẹ."},{"ten":"3. Luyện tập — Sáng tạo","gv":"- (16 phút) GV cho HS in thử một lần lên giấy báo cũ để quen tay, sau đó mới in lên đồ vật thật.\n- GV nêu các bước thực hành: bước 1 chọn đồ vật cần trang trí; bước 2 chọn hai đến ba vật liệu in và hai đến ba màu; bước 3 in thử trên giấy nháp; bước 4 in họa tiết lặp lại trên đồ vật theo hàng, theo đường viền hoặc rải đều; bước 5 chờ khô rồi vẽ thêm chấm, vạch cho họa tiết sinh động.\n- GV nhắc bạn không mang được củ quả thì dùng lá cây nhặt ở sân trường, cùi bắp, nắp chai, ống hút cắt ngắn, bìa carton cắt hình để in; không có màu nước thì hoà màu bột hoặc dùng sáp màu chà xát lên lá đặt dưới giấy.\n- GV đi từng bàn hỗ trợ, làm mẫu lại cho bạn in bị nhoè; nhắc an toàn: chỉ GV cắt củ quả bằng dao, HS không dùng dao; màu dính tay thì lau vào giẻ, không quệt lên quần áo và không đưa tay lên miệng.\n- GV báo trước khi còn 3 phút để HS hoàn thiện và đặt sản phẩm ra chỗ thoáng cho khô.","hs":"- HS in thử lên giấy báo cũ để quen tay trước khi in lên đồ vật.\n- HS thực hành theo 5 bước: chọn đồ vật, chọn vật liệu và màu, in thử, in họa tiết lặp lại, vẽ thêm chi tiết.\n- HS thiếu vật liệu thì dùng lá nhặt ở sân trường, cùi bắp, nắp chai, ống hút, bìa carton cắt hình.\n- HS giữ an toàn, không dùng dao, lau tay vào giẻ khi dính màu.\n- HS hoàn thiện sản phẩm và đặt ra chỗ thoáng cho khô."},{"ten":"4. Vận dụng — Trưng bày","gv":"- (8 phút) GV cho HS xếp sản phẩm lên bàn nhóm theo chủ đề, tạo thành phòng tranh mini ở góc lớp; sản phẩm còn ướt thì đặt riêng một hàng.\n- GV mời 4 đến 5 HS chia sẻ: Em in bằng vật liệu gì? Họa tiết của em được sắp xếp thế nào? Em thích chỗ nào nhất trên sản phẩm của mình?\n- GV nêu tiêu chí nhận xét sản phẩm: một là in được họa tiết rõ nét, không nhoè; hai là họa tiết lặp lại có trật tự, sắp xếp cân đối trên đồ vật; ba là màu sắc hài hoà; bốn là bài sạch sẽ, có ý tưởng riêng.\n- GV cho HS đi xem một vòng, mỗi bạn dán một ngôi sao vào sản phẩm mình thích rồi nói một câu vì sao thích.\n- GV nhận xét, động viên; dặn chuẩn bị cho tiết sau giấy màu, lá khô, vật liệu tái sử dụng; nhắc HS rửa dụng cụ in, lau bàn, nhặt rác và rửa tay sạch.","hs":"- HS xếp sản phẩm lên bàn nhóm, để riêng những bài còn ướt màu.\n- HS chia sẻ: vật liệu đã in, cách sắp xếp họa tiết và chỗ mình thích nhất.\n- HS nghe và nhắc lại 4 tiêu chí nhận xét sản phẩm in.\n- HS đi xem, dán ngôi sao vào sản phẩm mình thích và nói một câu vì sao thích.\n- HS ghi nhớ việc chuẩn bị cho tiết sau, rửa dụng cụ in, lau bàn, nhặt rác và rửa tay."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":16,"tiet":16,"bai":"Chủ đề 6: SẮC MÀU THIÊN NHIÊN — Tiết 4: Trang trí bằng thủ công, kết hợp chất liệu","yccd":"1. Năng lực mĩ thuật\n- Trang trí một đồ vật bằng hình thức thủ công, kết hợp nhiều chất liệu (giấy màu, lá khô, vật liệu tái sử dụng).\n- Hoàn thiện sản phẩm về sắc màu thiên nhiên.\n- Nêu được cảm nhận về sản phẩm của mình và của bạn.\n2. Năng lực chung\n- Giải quyết vấn đề và sáng tạo: kết hợp linh hoạt các chất liệu để trang trí.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ cách làm với bạn.\n3. Phẩm chất\n- Yêu thiên nhiên; tiết kiệm, tận dụng vật liệu tái sử dụng.","dodung":"- GV: hai đến ba sản phẩm thủ công mẫu kết hợp chất liệu (khung ảnh dán lá khô, hộp bút dán vải vụn, tranh dán hột hạt); khay đựng vật liệu chia theo loại; thiết bị trình chiếu.\n- GV chuẩn bị vật liệu thay thế cho lớp thiếu đồ dùng: giấy báo cũ, bìa carton, vỏ hộp sữa, lá cây khô ép phẳng, hột hạt, vỏ trấu, dây len, vải vụn, nắp chai, ống hút cũ cắt ngắn.\n- HS: sản phẩm các tiết trước, giấy màu, lá khô, vật liệu tái sử dụng đã rửa sạch, kéo, hồ dán, màu vẽ, khăn lau tay, tờ báo cũ lót bàn.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV kiểm tra sản phẩm tiết 3 và vật liệu HS mang tới, khen ngợi bạn sưu tầm được nhiều lá khô và vỏ hộp đẹp; chia vật liệu dự phòng cho bạn còn thiếu.\n- GV đưa ra một khung ảnh dán lá khô và hỏi: Sản phẩm này làm từ những chất liệu gì? Nếu chỉ vẽ bằng màu thì có được như thế này không?\n- Dự kiến HS trả lời: sản phẩm có lá khô, giấy màu và hột hạt; nếu chỉ vẽ thì không sờ thấy gồ ghề và không đẹp bằng.\n- GV dẫn vào bài: hôm nay cả lớp sẽ kết hợp nhiều chất liệu để trang trí một đồ vật về sắc màu thiên nhiên.","hs":"- HS đặt sản phẩm tiết 3 và vật liệu đã mang lên bàn cho GV kiểm tra.\n- HS quan sát khung ảnh mẫu và kể tên các chất liệu nhìn thấy.\n- HS trả lời: có lá khô, giấy màu, hột hạt; chỉ vẽ thì không có bề mặt gồ ghề như vậy.\n- HS lắng nghe và nắm nhiệm vụ của tiết học."},{"ten":"2. Khám phá — Kết hợp chất liệu","gv":"- (7 phút) GV bày các sản phẩm mẫu và các khay vật liệu lên bàn giữa lớp, cho HS đi vòng quanh quan sát và sờ nhẹ vào từng chất liệu.\n- GV nêu câu hỏi gợi mở: Sản phẩm dùng những chất liệu gì? Chất liệu nào nhẵn, chất liệu nào sần? Người làm đã đặt lá khô ở đâu, đặt hột hạt ở đâu? Kết hợp thế nào cho đẹp?\n- Dự kiến HS trả lời: có giấy màu nhẵn, lá khô và vải vụn sần; lá khô dán làm tán cây, hột hạt rắc làm mặt đất; nên chọn hai đến ba chất liệu thôi, nhiều quá sẽ rối.\n- GV chốt: chọn chất liệu theo hình ảnh cần thể hiện, dán mảng nền trước rồi mới dán chi tiết nhỏ lên trên, hồ bôi mỏng ở mép để vật liệu không bị cong.","hs":"- HS đi vòng quanh bàn mẫu, quan sát và sờ nhẹ vào các chất liệu.\n- HS trả lời: giấy màu nhẵn, lá khô và vải vụn sần; lá khô làm tán cây, hột hạt làm mặt đất.\n- HS nêu ý kiến: chỉ nên chọn hai đến ba chất liệu cho khỏi rối.\n- HS nhắc lại ý chốt: dán nền trước, chi tiết sau, bôi hồ mỏng ở mép."},{"ten":"3. Luyện tập — Sáng tạo","gv":"- (16 phút) GV làm mẫu chậm bước khó là dán lá khô: đặt lá lên tờ giấy nháp, bôi hồ mỏng ở mặt sau theo gân lá rồi đặt nhẹ lên bài và dùng ngón tay ấn giữ vài giây cho khỏi bong.\n- GV nêu các bước thực hành: bước 1 chọn đồ vật và nghĩ hình ảnh thiên nhiên sẽ thể hiện; bước 2 phác nhẹ bằng bút chì vị trí các hình ảnh chính; bước 3 chọn và xếp thử vật liệu lên chỗ đã phác; bước 4 dán mảng nền trước, dán chi tiết nhỏ sau; bước 5 vẽ hoặc tô thêm màu cho các khoảng còn trống.\n- GV nhắc bạn thiếu giấy màu thì dùng giấy báo cũ tô màu, vỏ hộp sữa cắt mảng, vải vụn, dây len, vỏ trấu, hột hạt để thay thế.\n- GV đi từng bàn hỗ trợ, nhắc an toàn: mũi kéo hướng xuống bàn, không dùng vỏ hộp có cạnh sắc, hồ dán chỉ bôi một lớp mỏng, không đưa tay dính hồ lên mắt và miệng.\n- GV báo trước khi còn 3 phút để HS hoàn thiện và ghi tên vào mặt sau sản phẩm.","hs":"- HS quan sát GV làm mẫu cách bôi hồ và dán lá khô cho khỏi bong.\n- HS thực hành theo 5 bước: chọn đồ vật, phác vị trí, xếp thử vật liệu, dán nền rồi dán chi tiết, tô thêm màu.\n- HS thiếu vật liệu thì dùng giấy báo tô màu, vỏ hộp, vải vụn, dây len, vỏ trấu, hột hạt.\n- HS giữ an toàn khi dùng kéo và hồ dán, giữ chỗ ngồi gọn gàng.\n- HS hoàn thiện sản phẩm và ghi tên vào mặt sau."},{"ten":"4. Vận dụng — Trưng bày","gv":"- (8 phút) GV cho các nhóm dán sản phẩm lên bảng nhóm theo chủ đề sắc màu thiên nhiên, ghép thành một phòng tranh mini ở góc lớp.\n- GV mời 4 đến 5 HS chia sẻ: Em dùng những chất liệu gì? Chất liệu nào khó dán nhất? Em thích sản phẩm nào của bạn nhất, vì sao?\n- GV nêu tiêu chí nhận xét sản phẩm: một là thể hiện đủ hình ảnh chính về thiên nhiên; hai là các chất liệu được sắp xếp cân đối, dán chắc, không bong; ba là màu sắc và chất liệu hài hoà; bốn là bài sạch sẽ, tận dụng được vật liệu tái sử dụng.\n- GV cho HS đi xem một vòng, mỗi bạn dán một ngôi sao vào sản phẩm mình thích rồi nói một câu vì sao thích.\n- GV nhận xét, động viên; dặn HS chuẩn bị đồ dùng đầy đủ cho tiết kiểm tra cuối học kì I; nhắc thu gom vụn giấy, vụn lá, lau bàn và rửa tay sạch.","hs":"- HS cùng nhóm dán sản phẩm lên bảng nhóm tạo thành phòng tranh mini.\n- HS chia sẻ: chất liệu đã dùng, chất liệu khó dán nhất và sản phẩm mình thích.\n- HS nghe và nhắc lại 4 tiêu chí nhận xét sản phẩm.\n- HS đi xem, dán ngôi sao vào sản phẩm mình thích và nói một câu vì sao thích.\n- HS ghi nhớ việc chuẩn bị cho tiết kiểm tra cuối học kì I, thu gom rác, lau bàn và rửa tay."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":17,"tiet":17,"bai":"KIỂM TRA, ĐÁNH GIÁ CUỐI HỌC KÌ I","yccd":"1. Năng lực mĩ thuật\n- Vận dụng tổng hợp kiến thức, kĩ năng về nét, hình cơ bản, khối, màu sắc đã học ở học kì I để tạo một sản phẩm mĩ thuật theo chủ đề tự chọn.\n- Trưng bày, giới thiệu và nêu được cảm nhận về sản phẩm của mình.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động hoàn thành sản phẩm đánh giá.\n- Giao tiếp và hợp tác: tự tin giới thiệu sản phẩm trước lớp.\n3. Phẩm chất\n- Chăm chỉ, trung thực trong đánh giá; trân trọng sản phẩm do mình và bạn tạo ra.\n4. Tích hợp\n- Năng lực số 3.1 CB1a: Xác định được các cách tạo và chỉnh sửa nội dung đơn giản ở các định dạng đơn giản: HS xem lại chuỗi sản phẩm của mình trong học kì.","dodung":"- GV: bảng tiêu chí đánh giá viết to treo trên bảng lớp; bảng nhóm và dây kẹp để trưng bày; một vài sản phẩm của HS ở các tiết trước làm gợi ý; thiết bị trình chiếu.\n- GV chuẩn bị vật liệu thay thế cho bạn thiếu đồ dùng: giấy báo cũ, mặt sau tờ lịch, bìa carton, vỏ hộp sữa, lá cây khô, hột hạt, dây len, vải vụn, nắp chai, đất nặn dùng chung theo bàn.\n- HS: đồ dùng mĩ thuật đầy đủ (bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, đất nặn, kéo, hồ dán, vật liệu tái sử dụng), khăn lau tay, tờ báo cũ lót bàn.","hoatdong":[{"ten":"1. Khởi động","gv":"- (3 phút) GV ổn định lớp, kiểm tra nhanh đồ dùng của từng bàn và cho mượn vật liệu dự phòng để bạn nào cũng có đủ đồ làm bài.\n- GV nêu mục đích tiết học: đây là tiết kiểm tra, đánh giá cuối học kì I, mỗi bạn tự làm một sản phẩm mĩ thuật theo chủ đề mình thích.\n- GV treo bảng tiêu chí và đọc chậm cho HS nghe: một là chọn được chủ đề rõ ràng; hai là dùng được kiến thức đã học về nét, hình, khối hoặc màu; ba là sắp xếp cân đối, màu sắc hài hoà; bốn là bài sạch sẽ, hoàn thành đúng giờ.\n- GV động viên: bài làm cần là của chính mình, ai cũng có thể làm tốt theo cách riêng.","hs":"- HS ổn định chỗ ngồi, bày đồ dùng lên bàn cho GV kiểm tra.\n- HS lắng nghe, nắm mục đích của tiết kiểm tra, đánh giá cuối học kì I.\n- HS đọc thầm và nhắc lại 4 tiêu chí đánh giá trên bảng.\n- HS chuẩn bị tinh thần tự làm bài của mình, không nhìn bài bạn."},{"ten":"2. Khám phá — Ôn nhanh kiến thức","gv":"- (7 phút) GV cho HS nhắc lại nhanh các nội dung đã học trong học kì I bằng hình thức hỏi đáp nhanh theo tổ.\n- GV nêu câu hỏi: Nét có những loại nào? Kể tên các hình cơ bản. Khi sắp xếp khối cần chú ý gì? Thế nào là màu đậm, màu nhạt?\n- Dự kiến HS trả lời: có nét thẳng, nét cong, nét gấp khúc; hình tròn, vuông, tam giác, chữ nhật; khối to đặt dưới cho vững, có cao có thấp; màu đậm nhìn nổi và tối hơn, màu nhạt nhìn sáng và nhẹ hơn.\n- GV gợi ý chọn chủ đề: ngôi nhà của em, con vật em yêu, vườn hoa, đồ chơi của em; hỏi thêm: Em sẽ vẽ, xé dán hay nặn? Em cần vật liệu gì?\n- GV chốt và cho HS ghi tên chủ đề mình chọn vào góc giấy để nhớ và làm cho đúng.","hs":"- HS tham gia hỏi đáp nhanh theo tổ, nhắc lại kiến thức đã học.\n- HS trả lời: nét thẳng, nét cong, nét gấp khúc; hình tròn, vuông, tam giác, chữ nhật.\n- HS nêu cách sắp xếp khối và phân biệt màu đậm, màu nhạt.\n- HS chọn chủ đề và hình thức thể hiện cho sản phẩm của mình.\n- HS ghi tên chủ đề đã chọn vào góc giấy."},{"ten":"3. Luyện tập — Thực hành đánh giá","gv":"- (14 phút) GV nêu các bước làm bài: bước 1 nghĩ kĩ hình ảnh chính của chủ đề; bước 2 phác nhẹ hoặc chuẩn bị vật liệu cho hình ảnh chính; bước 3 làm hình ảnh chính to ở giữa bài; bước 4 thêm hình ảnh phụ và màu nền; bước 5 xem lại toàn bài, chỉnh chỗ chưa cân đối rồi ghi tên.\n- GV nhắc bạn thiếu giấy vẽ dùng mặt sau tờ lịch hoặc giấy báo cũ; thiếu đất nặn thì dùng vỏ hộp, bìa carton, giấy báo vò tròn; thiếu giấy màu thì dùng lá khô, vải vụn, hột hạt.\n- GV đi quanh lớp quan sát, ghi nhận cách làm việc của từng HS để đánh giá cả quá trình, chỉ gợi ý chứ không làm hộ.\n- GV nhắc an toàn: mũi kéo hướng xuống bàn, hồ dán bôi mỏng, không đưa đất nặn và tay dính màu lên miệng, giữ chỗ ngồi gọn.\n- GV báo trước khi còn 3 phút để HS kịp hoàn thiện sản phẩm.","hs":"- HS làm bài theo 5 bước: nghĩ hình ảnh chính, phác hoặc chuẩn bị vật liệu, làm hình chính, thêm hình phụ và nền, chỉnh lại rồi ghi tên.\n- HS thiếu đồ dùng thì dùng mặt sau tờ lịch, giấy báo, vỏ hộp, lá khô, vải vụn thay thế.\n- HS tự làm bài của mình, hỏi GV khi thật sự gặp khó.\n- HS giữ an toàn khi dùng kéo, hồ dán và giữ chỗ ngồi gọn gàng.\n- HS hoàn thiện sản phẩm đúng thời gian quy định."},{"ten":"4. Vận dụng — Trưng bày, đánh giá","gv":"- (7 phút) GV cho HS treo hoặc đặt sản phẩm lên bảng nhóm theo chủ đề, ghép các bảng thành phòng tranh mini cuối học kì ở góc lớp.\n- GV mời một số HS giới thiệu: Sản phẩm của em nói về điều gì? Em đã dùng kiến thức nào đã học? Em thấy mình làm tốt nhất ở chỗ nào?\n- GV cùng HS đối chiếu với 4 tiêu chí đã nêu đầu giờ để nhận xét, luôn nói điều làm được trước rồi mới nói điều cần cố gắng.\n- GV cho HS đi xem một vòng, mỗi bạn dán một ngôi sao vào sản phẩm mình thích và nói một câu vì sao thích.\n- GV tổng kết học kì I, khen ngợi sự tiến bộ của cả lớp; dặn giữ lại sản phẩm vào bìa hồ sơ cá nhân và chuẩn bị đồ dùng cho chủ đề học kì II; nhắc lau bàn, nhặt rác, rửa tay.","hs":"- HS treo hoặc đặt sản phẩm lên bảng nhóm theo chủ đề.\n- HS giới thiệu sản phẩm: nội dung, kiến thức đã dùng và điều mình làm tốt nhất.\n- HS nghe nhận xét, đối chiếu bài của mình với 4 tiêu chí.\n- HS đi xem, dán ngôi sao vào sản phẩm mình thích và nói một câu vì sao thích.\n- HS cất sản phẩm vào bìa hồ sơ cá nhân, lau bàn, nhặt rác và rửa tay."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV chụp ảnh sản phẩm của từng HS trong học kì và xếp thành một trang ảnh riêng cho mỗi bạn theo thứ tự thời gian; mở trang của mình, HS thấy được cả quá trình từ bài đầu tiên đến bài mới nhất.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 1) HS nhìn trang ảnh của mình và tự nói một điều mình làm tốt hơn so với hồi đầu năm.\n⚠ (Miền 4: An toàn) Trang ảnh của bạn nào thì chỉ bạn ấy và GV cùng xem; không mang ảnh bài của bạn ra so bì hơn kém trước cả lớp.","hs":"- HS xem lại chuỗi sản phẩm của mình trong học kì.\n- HS tự nêu được một tiến bộ của bản thân."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":18,"tiet":18,"bai":"Chủ đề 7: GƯƠNG MẶT THÂN QUEN — Tiết 1: Quan sát và thể hiện chân dung (2D)","yccd":"1. Năng lực mĩ thuật\n- Quan sát ảnh chân dung để tìm hiểu các bộ phận trên gương mặt (mắt, mũi, miệng, tai, tóc).\n- Thể hiện được một chân dung bằng hình thức 2D (vẽ hoặc xé dán).\n- Bước đầu nhận biết đặc điểm riêng của mỗi gương mặt.\n2. Năng lực chung\n- Tự chủ và tự học: quan sát, ghi nhớ đặc điểm gương mặt để thể hiện.\n- Giao tiếp và hợp tác: chia sẻ về gương mặt người thân, bạn bè.\n3. Phẩm chất\n- Yêu quý, kính trọng người thân; biết quan tâm đến người xung quanh.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nêu được vị trí mắt, mũi, miệng trên khuôn mặt nhờ trục kẻ trên ảnh.","dodung":"- Giáo viên: ảnh chân dung; tranh chân dung của họa sĩ; thiết bị trình chiếu.\n- Học sinh: SGK Mĩ thuật 2, Vở bài tập Mĩ thuật 2, bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, hồ dán.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS chơi trò chơi Đoán bạn qua đặc điểm gương mặt.\n- GV nhận xét, giới thiệu chủ đề.","hs":"- HS tham gia trò chơi, đoán bạn.\n- HS lắng nghe, mở bài học."},{"ten":"2. Khám phá — Các bộ phận gương mặt","gv":"- GV cho HS quan sát ảnh chân dung, hình trong SGK Mĩ thuật 2.\n- GV đặt câu hỏi: Trên gương mặt có những bộ phận nào? Mắt, mũi, miệng ở vị trí nào? Điều gì làm mỗi gương mặt khác nhau?\n- GV chốt về các bộ phận và đặc điểm riêng của gương mặt.","hs":"- HS quan sát, trả lời câu hỏi.\n- HS nhận biết các bộ phận và đặc điểm gương mặt.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập — Sáng tạo (2D)","gv":"- GV hướng dẫn HS tham khảo cách thể hiện chân dung trong SGK.\n- GV yêu cầu HS vẽ hoặc xé dán một chân dung (bản thân, bạn hoặc người thân) dạng 2D.\n- GV quan sát, giúp đỡ; nhắc HS lưu giữ sản phẩm cho tiết sau.","hs":"- HS tham khảo, tiếp thu cách làm.\n- HS thực hành thể hiện chân dung 2D.\n- HS lưu giữ sản phẩm."},{"ten":"4. Vận dụng","gv":"- GV cho HS chia sẻ: em vẽ chân dung của ai? Đặc điểm nổi bật là gì?\n- GV khen ngợi, dặn HS chuẩn bị cho tiết 2.","hs":"- HS chia sẻ về chân dung của mình.\n- HS ghi nhớ nhiệm vụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu một bức ảnh chân dung và dùng công cụ vẽ kẻ trục dọc, trục ngang lên ảnh để HS thấy hai mắt nằm ngang nhau ở khoảng giữa khuôn mặt, mũi và miệng nằm trên trục dọc; kẻ rồi xoá đi được nhiều lần, việc mà kẻ lên ảnh giấy không làm được.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) HS soi gương hoặc nhìn bạn cùng bàn để kiểm tra lại nhận xét ấy trên khuôn mặt thật.\n⚠ (Miền 4: An toàn) GV chỉ dùng ảnh chân dung đã chuẩn bị sẵn hoặc ảnh của chính GV; không chiếu ảnh của HS lên màn hình khi chưa hỏi bạn và gia đình bạn.","hs":"- HS nêu được vị trí mắt, mũi, miệng trên khuôn mặt nhờ trục kẻ trên ảnh.\n- HS kiểm tra lại tỉ lệ ấy trên khuôn mặt bạn và của mình."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":19,"tiet":19,"bai":"Chủ đề 7: GƯƠNG MẶT THÂN QUEN — Tiết 2: Thể hiện chân dung (3D)","yccd":"1. Năng lực mĩ thuật\n- Quan sát sản phẩm, tác phẩm mĩ thuật thể hiện về gương mặt.\n- Thể hiện được một chân dung bằng hình thức 3D (nặn hoặc tạo khối).\n- Biết thể hiện đặc điểm gương mặt qua sản phẩm 3D.\n2. Năng lực chung\n- Giải quyết vấn đề và sáng tạo: tạo hình chân dung 3D theo ý tưởng.\n- Giao tiếp và hợp tác: trao đổi cách làm với bạn.\n3. Phẩm chất\n- Yêu quý người thân; kiên trì, chăm chỉ hoàn thành sản phẩm.","dodung":"- GV: hai sản phẩm chân dung 3D mẫu (một khuôn mặt tròn, một khuôn mặt dài) để HS so sánh; đất nặn nhiều màu, dao nhựa, tấm bìa lót; thiết bị trình chiếu.\n- GV chuẩn bị vật liệu thay thế cho lớp thiếu đồ dùng: giấy báo cũ vò tròn bọc giấy màu, đĩa giấy, nắp hộp tròn, bìa carton, vỏ hộp sữa, hột hạt làm mắt, dây len làm tóc, vải vụn làm khăn, lá khô làm vành nón.\n- HS: sản phẩm tiết 1, đất nặn hoặc đất sét, vật liệu tái sử dụng đã rửa sạch, bút màu, kéo, hồ dán, khăn lau tay, tờ báo cũ lót bàn.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV kiểm tra sản phẩm tiết 1 và đồ dùng của từng bàn, khen ngợi, động viên; cho mượn vật liệu dự phòng với bạn còn thiếu.\n- GV cho HS quay sang bạn bên cạnh, nhìn kĩ khuôn mặt bạn trong mười giây rồi hỏi: Mặt bạn hình tròn hay hình trái xoan? Bạn có nét gì riêng dễ nhận ra nhất?\n- Dự kiến HS trả lời: mặt bạn hơi tròn; bạn có tóc buộc hai bên, có má lúm, có kính, có răng sún.\n- GV đưa sản phẩm chân dung 3D mẫu và dẫn vào bài: hôm nay cả lớp sẽ nặn hoặc tạo khối một gương mặt thân quen của mình.","hs":"- HS đặt sản phẩm tiết 1 và đồ dùng lên bàn cho GV kiểm tra.\n- HS quay sang quan sát khuôn mặt bạn bên cạnh trong mười giây.\n- HS trả lời: mặt bạn hơi tròn, bạn có tóc buộc hai bên, có má lúm hoặc răng sún.\n- HS quan sát sản phẩm mẫu và nắm nhiệm vụ của tiết học."},{"ten":"2. Khám phá — Chân dung 3D","gv":"- (7 phút) GV cho HS quan sát hai sản phẩm chân dung 3D mẫu và hình trong SGK, chuyền tay để cả lớp nhìn gần.\n- GV nêu câu hỏi gợi mở: Sản phẩm thể hiện gương mặt bằng chất liệu gì? Mắt, mũi, miệng được tạo bằng cách nào? Vì sao nhìn vào ta nhận ra ngay đó là bà, là mẹ hay là em bé?\n- Dự kiến HS trả lời: làm bằng đất nặn và vỏ hộp; mắt là hai viên đất tròn nhỏ, mũi vê dài rồi gắn lên, miệng dùng dao nhựa rạch một đường cong; nhận ra nhờ tóc, nếp nhăn, chiếc khăn hoặc cái kính.\n- GV chốt cách tạo chân dung 3D: làm khối mặt trước, chia nhẩm mặt thành hai phần để đặt mắt ở khoảng giữa, mũi ở giữa mặt, miệng ở phần dưới, cuối cùng gắn tóc và chi tiết riêng.","hs":"- HS quan sát và chuyền tay xem hai sản phẩm chân dung 3D mẫu.\n- HS trả lời: sản phẩm làm bằng đất nặn, vỏ hộp; mắt là viên đất tròn, mũi vê dài, miệng rạch bằng dao nhựa.\n- HS nêu dấu hiệu nhận ra nhân vật: tóc, nếp nhăn, chiếc khăn, cái kính.\n- HS nhắc lại cách đặt mắt, mũi, miệng trên khối mặt cho cân đối."},{"ten":"3. Luyện tập — Sáng tạo (3D)","gv":"- (16 phút) GV làm mẫu chậm bước khó là gắn chi tiết nhỏ lên khối mặt: viên đất làm mắt phải ấn nhẹ và xoa quanh mép cho dính hẳn, tóc bằng dây len thì bôi hồ theo một đường rồi mới đặt len lên.\n- GV nêu các bước thực hành: bước 1 chọn người mình muốn thể hiện là ông, bà, bố, mẹ hay bạn; bước 2 tạo khối mặt tròn hoặc trái xoan; bước 3 gắn mắt, mũi, miệng theo vị trí đã chốt; bước 4 làm tóc, tai; bước 5 thêm một chi tiết riêng để ai cũng nhận ra nhân vật.\n- GV nhắc bạn thiếu đất nặn thì dùng giấy báo vò tròn bọc giấy màu, đĩa giấy, nắp hộp tròn làm mặt, hột hạt làm mắt, dây len làm tóc, vải vụn làm khăn.\n- GV đi từng bàn hỗ trợ, hỏi riêng bạn còn lúng túng: Người em định làm có mái tóc thế nào? Có hay đeo gì trên mặt không?\n- GV nhắc an toàn: không dùng dao nhựa chọc về phía bạn, mũi kéo hướng xuống bàn, không đưa đất nặn lên miệng; báo trước khi còn 3 phút để HS hoàn thiện.","hs":"- HS quan sát GV làm mẫu cách gắn mắt và cách dán tóc bằng dây len.\n- HS thực hành theo 5 bước: chọn nhân vật, tạo khối mặt, gắn mắt mũi miệng, làm tóc và tai, thêm chi tiết riêng.\n- HS thiếu đất nặn thì dùng giấy báo vò tròn, đĩa giấy, nắp hộp, hột hạt, dây len, vải vụn.\n- HS trả lời gợi ý của GV để nhớ ra đặc điểm riêng của nhân vật mình làm.\n- HS giữ an toàn khi dùng dao nhựa và kéo, hoàn thiện sản phẩm đúng giờ."},{"ten":"4. Vận dụng","gv":"- (8 phút) GV cho HS đặt sản phẩm lên bàn nhóm, mỗi nhóm một khu, tạo thành phòng trưng bày chân dung mini ở góc lớp.\n- GV mời 4 đến 5 HS chia sẻ: Em thể hiện gương mặt của ai? Đặc điểm nào của người đó em làm rõ nhất? Em muốn nói điều gì với người ấy?\n- GV nêu tiêu chí nhận xét sản phẩm: một là thể hiện đủ các bộ phận chính của gương mặt; hai là mắt, mũi, miệng đặt cân đối trên khuôn mặt; ba là có ít nhất một chi tiết riêng để nhận ra nhân vật; bốn là gắn chắc, bài sạch sẽ.\n- GV cho HS đi xem một vòng, mỗi bạn dán một ngôi sao giấy vào sản phẩm mình thích rồi nói một câu vì sao thích.\n- GV khen ngợi, dặn HS cất sản phẩm cẩn thận cho tiết 3 và chuẩn bị thêm giấy bìa, đất nặn để học đắp nổi; nhắc lau bàn, nhặt vụn đất và rửa tay.","hs":"- HS đặt sản phẩm lên bàn nhóm theo khu vực của nhóm mình.\n- HS chia sẻ: người mình thể hiện, đặc điểm làm rõ nhất và điều muốn nói với người ấy.\n- HS nghe và nhắc lại 4 tiêu chí nhận xét sản phẩm.\n- HS đi xem, dán ngôi sao vào sản phẩm mình thích và nói một câu vì sao thích.\n- HS cất sản phẩm, ghi nhớ việc chuẩn bị cho tiết 3, lau bàn và rửa tay."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":20,"tiet":20,"bai":"Chủ đề 7: GƯƠNG MẶT THÂN QUEN — Tiết 3: Vận dụng (đắp nổi)","yccd":"1. Năng lực mĩ thuật\n- Củng cố kiến thức, kĩ năng về tạo hình chân dung đã học.\n- Sử dụng tạo hình chân dung để trang trí một sản phẩm theo hình thức đắp nổi.\n- Biết phối hợp màu sắc, chất liệu để sản phẩm sinh động.\n2. Năng lực chung\n- Giải quyết vấn đề và sáng tạo: vận dụng tạo hình chân dung vào trang trí.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ cách làm với bạn.\n3. Phẩm chất\n- Yêu quý người thân; chăm chỉ, kiên trì.","dodung":"- GV: một sản phẩm đắp nổi mẫu (chân dung nổi trên nền bìa) và một sản phẩm vẽ phẳng cùng nội dung để HS so sánh; đất nặn, dao nhựa, tấm bìa nền; thiết bị trình chiếu.\n- GV chuẩn bị vật liệu thay thế cho lớp thiếu đồ dùng: bìa carton làm nền, nắp hộp, giấy báo cũ vò nhỏ đắp thành mảng nổi, giấy màu vò rồi dán, hột hạt, vỏ trấu, dây len, vải vụn, lá khô.\n- HS: sản phẩm các tiết trước, đất nặn, giấy bìa hoặc nắp hộp làm nền, bút màu, keo dán, kéo, khăn lau tay, tờ báo cũ lót bàn.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV kiểm tra sản phẩm tiết 2 và đồ dùng của từng bàn, khen ngợi bạn giữ sản phẩm cẩn thận, cho mượn vật liệu dự phòng với bạn còn thiếu.\n- GV đưa ra hai sản phẩm cùng vẽ một gương mặt, một bức phẳng và một bức đắp nổi, rồi hỏi: Hai bức này khác nhau ở chỗ nào? Bức nào sờ vào thấy gồ ghề?\n- Dự kiến HS trả lời: một bức phẳng, một bức nổi lên khỏi mặt bìa; bức đắp nổi sờ vào thấy gồ ghề và nhìn nghiêng vẫn thấy rõ hình.\n- GV giới thiệu hình thức đắp nổi và dẫn vào bài: hôm nay cả lớp dùng gương mặt đã học để trang trí một sản phẩm theo cách đắp nổi.","hs":"- HS đặt sản phẩm tiết 2 và đồ dùng lên bàn cho GV kiểm tra.\n- HS quan sát, sờ nhẹ hai sản phẩm mẫu và so sánh.\n- HS trả lời: một bức phẳng, một bức nổi lên, bức nổi sờ thấy gồ ghề.\n- HS lắng nghe và nắm nhiệm vụ của tiết học."},{"ten":"2. Khám phá — Đắp nổi chân dung","gv":"- (7 phút) GV cho HS chuyền tay xem sản phẩm đắp nổi mẫu, quan sát kĩ chỗ nào nổi cao, chỗ nào nổi thấp.\n- GV nêu câu hỏi gợi mở: Chân dung được đắp trên nền gì? Bộ phận nào nổi cao nhất? Vì sao mũi lại nổi cao hơn má? Muốn đất bám chắc vào nền thì làm thế nào?\n- Dự kiến HS trả lời: đắp trên nền bìa cứng hoặc nắp hộp; mũi nổi cao nhất vì mũi nhô ra khỏi mặt; muốn bám chắc thì ấn nhẹ và miết mép đất xuống nền.\n- GV thị phạm chậm: dàn một lớp đất mỏng làm khuôn mặt trên nền bìa, miết mép cho phẳng, sau đó đắp thêm đất làm mũi, gò má, môi và miết chân các chi tiết cho liền với nền.\n- GV chốt: đắp từ mảng to đến chi tiết nhỏ, luôn miết chân chi tiết cho liền nền thì sản phẩm mới không bong.","hs":"- HS chuyền tay xem sản phẩm đắp nổi mẫu và chỉ chỗ nổi cao, nổi thấp.\n- HS trả lời: đắp trên nền bìa, mũi nổi cao nhất, muốn bám chắc thì miết mép đất xuống nền.\n- HS quan sát GV thị phạm cách dàn lớp đất nền và đắp các chi tiết.\n- HS nhắc lại ý chốt: đắp mảng to trước, chi tiết nhỏ sau, luôn miết chân chi tiết."},{"ten":"3. Luyện tập — Sáng tạo","gv":"- (16 phút) GV nêu các bước thực hành: bước 1 chọn nền là tấm bìa, nắp hộp hay vỏ hộp; bước 2 dàn lớp đất hoặc dán lớp giấy làm khuôn mặt; bước 3 đắp mũi, gò má, môi từ mảng to đến nhỏ; bước 4 làm tóc và trang phục bằng dây len, vải vụn, giấy vò; bước 5 thêm màu và chi tiết trang trí quanh khung.\n- GV làm mẫu lại một lần thao tác khó là miết chân chi tiết, vừa làm vừa đếm chậm để HS nhìn rõ.\n- GV nhắc bạn thiếu đất nặn thì vò giấy báo cũ thành mảng nhỏ dán chồng lên nhau để tạo độ nổi, dùng giấy màu vò, hột hạt, vỏ trấu, dây len, vải vụn, lá khô.\n- GV đi từng bàn hỗ trợ, nhắc HS làm mảng lớn trước cho kịp giờ; nhắc an toàn: mũi kéo hướng xuống bàn, keo dán bôi mỏng, không đưa tay dính keo lên mắt, không đưa đất nặn lên miệng.\n- GV báo trước khi còn 3 phút để HS ghi tên vào mặt sau sản phẩm và cất đúng chỗ cho tiết 4.","hs":"- HS thực hành theo 5 bước: chọn nền, dàn lớp mặt, đắp các chi tiết, làm tóc và trang phục, thêm màu trang trí.\n- HS quan sát lại thao tác miết chân chi tiết do GV làm mẫu.\n- HS thiếu đất nặn thì dùng giấy báo vò, giấy màu vò, hột hạt, vỏ trấu, dây len, vải vụn.\n- HS giữ an toàn khi dùng kéo và keo dán, giữ chỗ ngồi sạch sẽ.\n- HS ghi tên vào mặt sau sản phẩm và cất đúng chỗ để dùng cho tiết 4."},{"ten":"4. Vận dụng","gv":"- (8 phút) GV cho HS đặt sản phẩm đang làm lên bàn nhóm thành một phòng tranh mini để cả lớp cùng xem giữa chừng.\n- GV mời 4 đến 5 HS chia sẻ nhanh: Em đắp nổi gương mặt của ai? Phần nào em thấy khó nhất? Em định làm thêm gì ở tiết sau?\n- GV nêu tiêu chí để HS tự soi lại bài: một là gương mặt nổi rõ trên nền; hai là các bộ phận đặt cân đối; ba là chi tiết dán chắc, không bong; bốn là bài sạch sẽ, có ý tưởng riêng.\n- GV cho HS đi xem một vòng, mỗi bạn dán một ngôi sao vào sản phẩm mình thích rồi nói một câu vì sao thích.\n- GV khen ngợi, dặn HS chuẩn bị màu, keo và một ít vật liệu trang trí cho tiết 4 để hoàn thiện và trưng bày; nhắc lau bàn, nhặt vụn đất và giấy, rửa tay sạch.","hs":"- HS đặt sản phẩm đang làm lên bàn nhóm cho cả lớp cùng xem.\n- HS chia sẻ: nhân vật mình đắp nổi, phần khó nhất và dự định cho tiết sau.\n- HS nghe và tự soi lại bài của mình theo 4 tiêu chí.\n- HS đi xem, dán ngôi sao vào sản phẩm mình thích và nói một câu vì sao thích.\n- HS ghi nhớ việc chuẩn bị cho tiết 4, lau bàn, nhặt vụn đất và giấy, rửa tay."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":21,"tiet":21,"bai":"Chủ đề 7: GƯƠNG MẶT THÂN QUEN — Tiết 4: Vận dụng (đắp nổi, tiếp theo) và trưng bày","yccd":"1. Năng lực mĩ thuật\n- Hoàn thiện sản phẩm trang trí bằng tạo hình chân dung theo hình thức đắp nổi.\n- Trưng bày, giới thiệu và nêu cảm nhận về sản phẩm của mình và của bạn.\n- Biết đánh giá sản phẩm theo tiêu chí đơn giản.\n2. Năng lực chung\n- Giao tiếp và hợp tác: tự tin giới thiệu sản phẩm, lắng nghe nhận xét.\n3. Phẩm chất\n- Yêu quý người thân; trân trọng sản phẩm do mình và bạn tạo ra.\n4. Tích hợp\n- Năng lực số 3.3 CB1a: Xác định được các quy tắc đơn giản về bản quyền và giấy phép áp dụng cho dữ liệu, thông tin và nội dung số: HS xem trang trưng bày và nhận ra tên tác giả của từng bức.","dodung":"- GV: bảng trưng bày hoặc dây kẹp treo sản phẩm; bảng tiêu chí đánh giá viết to; thẻ tên tác giả và ngôi sao giấy cắt sẵn; thiết bị trình chiếu.\n- GV chuẩn bị vật liệu thay thế cho lớp thiếu đồ dùng: bìa carton, giấy báo cũ, giấy màu vò, hột hạt, vỏ trấu, dây len, vải vụn, lá khô, nắp chai để HS bổ sung chi tiết.\n- HS: sản phẩm tiết 3, đất nặn, bút màu, keo dán, kéo để hoàn thiện; khăn lau tay, tờ báo cũ lót bàn.","hoatdong":[{"ten":"1. Khởi động","gv":"- (3 phút) GV cho HS lấy sản phẩm tiết 3 đặt lên bàn, kiểm tra nhanh xem bài nào bị bong chi tiết để nhắc HS dán lại ngay.\n- GV hỏi: Bài của em còn thiếu phần nào? Em định thêm gì cho gương mặt sinh động hơn? Dự kiến HS trả lời: bài em còn thiếu tóc, thiếu màu nền, em định thêm chiếc nón và mấy bông hoa quanh khung.\n- GV nêu nhiệm vụ tiết học: hoàn thiện sản phẩm đắp nổi và trưng bày thành phòng tranh chân dung của lớp.","hs":"- HS lấy sản phẩm tiết 3 đặt lên bàn và kiểm tra chi tiết bị bong.\n- HS trả lời: bài còn thiếu tóc, thiếu màu nền, định thêm nón và hoa quanh khung.\n- HS lắng nghe, nắm nhiệm vụ của tiết học và chuẩn bị đồ dùng."},{"ten":"2. Khám phá — Hoàn thiện","gv":"- (7 phút) GV treo bảng tiêu chí đánh giá và đọc chậm để HS biết cần hoàn thiện những gì.\n- GV gợi ý các cách làm cho sản phẩm sinh động hơn: thêm tóc bằng dây len hoặc giấy vò, thêm màu nền để gương mặt nổi bật, viền quanh khung bằng hột hạt hoặc lá khô, chấm thêm màu má hồng.\n- GV hỏi gợi mở: Nếu nền cùng màu với gương mặt thì có nhìn rõ không? Nên chọn nền màu đậm hay nhạt? Dự kiến HS trả lời: nếu cùng màu sẽ không nhìn rõ; nên chọn nền khác màu, mặt sáng thì nền đậm hơn.\n- GV làm mẫu chậm cách viền khung: bôi keo thành một đường quanh mép nền rồi rắc hột hạt lên, ấn nhẹ và đợi một lát cho khô.","hs":"- HS đọc thầm bảng tiêu chí và biết mình cần hoàn thiện những gì.\n- HS nghe gợi ý và chọn cách làm cho sản phẩm của mình sinh động hơn.\n- HS trả lời: nền cùng màu thì không nhìn rõ, nên chọn nền khác màu với gương mặt.\n- HS quan sát GV làm mẫu cách viền khung bằng hột hạt."},{"ten":"3. Luyện tập — Hoàn thiện sản phẩm","gv":"- (14 phút) GV nêu các bước hoàn thiện: bước 1 dán lại các chi tiết bị bong; bước 2 bổ sung tóc, tai, trang phục; bước 3 tô hoặc dán màu nền; bước 4 trang trí viền khung; bước 5 ghi tên tác giả vào thẻ tên đặt cạnh sản phẩm.\n- GV nhắc bạn thiếu vật liệu thì dùng giấy báo cũ vò, giấy màu vò, vải vụn, dây len, lá khô, nắp chai, vỏ trấu.\n- GV đi từng bàn hỗ trợ HS gặp khó, giúp bạn có bài chưa xong ưu tiên làm phần gương mặt trước rồi mới trang trí.\n- GV nhắc an toàn và vệ sinh: mũi kéo hướng xuống bàn, keo bôi mỏng, không đưa tay dính keo lên mắt và miệng, giấy vụn gom vào một góc bàn.\n- GV báo trước khi còn 3 phút để HS hoàn thiện và mang sản phẩm ra khu trưng bày.","hs":"- HS hoàn thiện theo 5 bước: dán lại chi tiết bong, bổ sung tóc và trang phục, làm màu nền, trang trí viền khung, ghi thẻ tên.\n- HS thiếu vật liệu thì dùng giấy báo vò, vải vụn, dây len, lá khô, nắp chai, vỏ trấu.\n- HS chưa xong thì ưu tiên hoàn thiện phần gương mặt trước.\n- HS giữ an toàn khi dùng kéo và keo, gom giấy vụn vào một góc bàn.\n- HS hoàn thiện đúng giờ và mang sản phẩm ra khu trưng bày."},{"ten":"4. Vận dụng — Trưng bày","gv":"- (7 phút) GV cho HS treo sản phẩm lên dây kẹp hoặc dán lên bảng nhóm theo chủ đề gương mặt thân quen, đặt thẻ tên tác giả dưới mỗi bức để thành phòng tranh mini của lớp.\n- GV mời HS giới thiệu: Sản phẩm của em thể hiện gương mặt ai? Em muốn tặng sản phẩm này cho ai? Em thích sản phẩm nào của bạn nhất, vì sao?\n- GV nêu tiêu chí nhận xét sản phẩm: một là gương mặt nổi rõ, đủ các bộ phận chính; hai là các bộ phận đặt cân đối trên nền; ba là màu sắc và chất liệu hài hoà, chi tiết dán chắc; bốn là bài sạch sẽ, có ý tưởng riêng.\n- GV cho HS đi xem một vòng, mỗi bạn dán một ngôi sao vào bức mình thích rồi nói một câu vì sao thích.\n- GV nhận xét, động viên; dặn xem trước Chủ đề 8 và chuẩn bị đất nặn, vật liệu tái sử dụng; nhắc HS lau bàn, nhặt rác và rửa tay sạch.","hs":"- HS treo hoặc dán sản phẩm lên khu trưng bày và đặt thẻ tên tác giả.\n- HS giới thiệu: gương mặt đã thể hiện, người mình muốn tặng và bức mình thích.\n- HS nghe và nhắc lại 4 tiêu chí nhận xét sản phẩm.\n- HS đi xem, dán ngôi sao vào bức mình thích và nói một câu vì sao thích.\n- HS ghi nhớ việc chuẩn bị cho Chủ đề 8, lau bàn, nhặt rác và rửa tay."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV chụp các bức chân dung đắp nổi từ hướng chếch để thấy rõ độ nổi, rồi ghép thành một trang trưng bày có ghi tên tác giả dưới mỗi ảnh.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 1) HS đoán xem mỗi bức chân dung vẽ ai; bạn được vẽ nghe lời khen thì nói lời cảm ơn.\n⚠ (Miền 4: An toàn) Chỉ chụp sản phẩm, không chụp mặt bạn khi bạn chưa đồng ý; trang trưng bày chỉ mở trong lớp, không gửi ra ngoài.","hs":"- HS xem trang trưng bày và nhận ra tên tác giả của từng bức.\n- HS khen bạn và đáp lại lời khen một cách lịch sự."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":22,"tiet":22,"bai":"Chủ đề 8: BỮA CƠM GIA ĐÌNH — Tiết 1: Quan sát và thể hiện (2D)","yccd":"1. Năng lực mĩ thuật\n- Tìm hiểu hình ảnh thể hiện về bữa cơm gia đình.\n- Tạo được một sản phẩm mĩ thuật thể hiện về chủ đề dạng 2D (vẽ hoặc xé dán).\n- Bước đầu biết sắp xếp hình ảnh có nội dung, có nhân vật.\n2. Năng lực chung\n- Tự chủ và tự học: quan sát, nhớ lại bữa cơm gia đình để thể hiện.\n- Giao tiếp và hợp tác: chia sẻ về bữa cơm gia đình mình.\n3. Phẩm chất\n- Yêu gia đình; trân trọng những bữa cơm sum họp bên người thân.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nêu được điểm giống và khác giữa các bữa cơm gia đình qua bộ ảnh.","dodung":"- Giáo viên: tranh ảnh về bữa cơm gia đình; sản phẩm mĩ thuật mẫu; thiết bị trình chiếu.\n- Học sinh: SGK Mĩ thuật 2, Vở bài tập Mĩ thuật 2, bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, hồ dán.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS hát/nghe một bài hát về gia đình, hỏi: Bữa cơm gia đình em thường có những ai?\n- GV nhận xét, giới thiệu chủ đề.","hs":"- HS hát/nghe, trả lời câu hỏi.\n- HS lắng nghe, mở bài học."},{"ten":"2. Khám phá — Hình ảnh bữa cơm","gv":"- GV cho HS quan sát tranh ảnh về bữa cơm gia đình và hình trong SGK.\n- GV đặt câu hỏi: Bữa cơm có những ai? Mọi người làm gì? Không khí bữa cơm thế nào?\n- GV chốt về nội dung, hình ảnh, không khí bữa cơm gia đình.","hs":"- HS quan sát, trả lời câu hỏi.\n- HS nhận biết cách thể hiện hình ảnh bữa cơm.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập — Sáng tạo (2D)","gv":"- GV hướng dẫn HS tham khảo cách thể hiện trong SGK.\n- GV yêu cầu HS vẽ hoặc xé dán một sản phẩm về bữa cơm gia đình dạng 2D.\n- GV quan sát, giúp đỡ; nhắc HS lưu giữ sản phẩm cho tiết sau.","hs":"- HS tham khảo, tiếp thu cách làm.\n- HS thực hành thể hiện chủ đề dạng 2D.\n- HS lưu giữ sản phẩm."},{"ten":"4. Vận dụng","gv":"- GV cho HS chia sẻ: bức tranh của em thể hiện bữa cơm với ai?\n- GV khen ngợi, dặn HS chuẩn bị cho tiết 2.","hs":"- HS chia sẻ về sản phẩm.\n- HS ghi nhớ nhiệm vụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu bộ ảnh bữa cơm của các gia đình ở nhiều vùng miền: mâm cơm đồng bằng, mâm cơm miền núi, mâm cơm ngày Tết; HS thấy được sự khác nhau về món ăn, chỗ ngồi và cách bày mâm.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) HS kể lại bữa cơm nhà mình: ai ngồi cạnh ai, mâm cơm đặt ở đâu, thường có món gì.\n⚠ (Miền 4: An toàn) GV dùng ảnh tư liệu đã chuẩn bị; HS không mang ảnh chụp gia đình mình đến chiếu lên màn hình vì đó là chuyện riêng của mỗi nhà.","hs":"- HS nêu được điểm giống và khác giữa các bữa cơm gia đình qua bộ ảnh.\n- HS kể được bữa cơm nhà mình để lấy ý cho bài vẽ."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":23,"tiet":23,"bai":"Chủ đề 8: BỮA CƠM GIA ĐÌNH — Tiết 2: Thể hiện (3D)","yccd":"1. Năng lực mĩ thuật\n- Tìm hiểu cách thể hiện hình ảnh về người thân qua một số sản phẩm mĩ thuật.\n- Thể hiện được một sản phẩm mĩ thuật về chủ đề ở dạng 3D (nặn, tạo khối).\n- Biết tạo hình nhân vật, đồ vật trong bữa cơm bằng chất liệu 3D.\n2. Năng lực chung\n- Giải quyết vấn đề và sáng tạo: tạo hình nhân vật, đồ vật 3D theo chủ đề.\n- Giao tiếp và hợp tác: phối hợp với bạn khi tạo sản phẩm.\n3. Phẩm chất\n- Yêu gia đình; chăm chỉ, kiên trì hoàn thành sản phẩm.","dodung":"- GV: một mô hình 3D mẫu về bữa cơm gia đình (mâm cơm, bát đũa, hai ba nhân vật ngồi quanh) đặt trên đế bìa; đất nặn nhiều màu, dao nhựa; thiết bị trình chiếu.\n- GV chuẩn bị vật liệu thay thế cho lớp thiếu đồ dùng: nắp chai làm bát đĩa, que kem làm đũa, giấy báo cũ vò tròn làm cơm, bìa carton làm mâm, vỏ hộp sữa làm thân người, hột hạt, dây len, vải vụn, lá khô.\n- HS: sản phẩm tiết 1, đất nặn hoặc đất sét, vật liệu tái sử dụng đã rửa sạch, bút màu, kéo, hồ dán, khăn lau tay, tờ báo cũ lót bàn.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV kiểm tra sản phẩm tiết 1 và đồ dùng của từng bàn, khen ngợi, động viên; cho mượn vật liệu dự phòng với bạn còn thiếu.\n- GV hỏi để gợi cảm xúc: Bữa cơm nhà em thường có những ai? Món ăn nào em thích nhất? Ai là người dọn mâm cơm?\n- Dự kiến HS trả lời: nhà em có ông bà, bố mẹ và em; em thích canh cua và trứng rán; mẹ và em cùng dọn mâm.\n- GV đưa mô hình mẫu ra và dẫn vào bài: hôm nay cả lớp sẽ nặn, tạo khối một sản phẩm 3D về bữa cơm gia đình mình.","hs":"- HS đặt sản phẩm tiết 1 và đồ dùng lên bàn cho GV kiểm tra.\n- HS kể về bữa cơm nhà mình: những người cùng ăn, món ăn mình thích.\n- HS trả lời: nhà em có ông bà, bố mẹ và em; mẹ và em cùng dọn mâm cơm.\n- HS quan sát mô hình mẫu và nắm nhiệm vụ của tiết học."},{"ten":"2. Khám phá — Tạo hình 3D","gv":"- (7 phút) GV đặt mô hình mẫu lên bàn giữa lớp, cho HS đi vòng quanh quan sát khoảng một phút rồi trở về chỗ.\n- GV nêu câu hỏi gợi mở: Sản phẩm thể hiện những gì? Nhân vật được nặn từ mấy khối? Cái bát, đôi đũa được làm bằng gì? Vì sao mâm cơm lại đặt ở giữa?\n- Dự kiến HS trả lời: có mâm cơm, bát đũa và mấy người ngồi quanh; nhân vật gồm khối tròn làm đầu và khối trụ làm thân; bát làm từ nắp chai, đũa làm từ que tăm; mâm đặt ở giữa để mọi người cùng quây quần.\n- GV chốt cách tạo hình 3D theo chủ đề: làm hình ảnh chính là mâm cơm trước, sau đó nặn nhân vật bằng những khối đơn giản, cuối cùng đặt nhân vật quay mặt vào mâm cho thành một cảnh sum họp.","hs":"- HS đi vòng quanh quan sát mô hình mẫu rồi trở về chỗ ngồi.\n- HS trả lời: sản phẩm có mâm cơm, bát đũa và các nhân vật ngồi quanh.\n- HS nêu cách nặn nhân vật từ khối tròn làm đầu và khối trụ làm thân.\n- HS nhắc lại ý chốt: làm mâm cơm trước, nặn nhân vật sau, đặt nhân vật quay vào mâm."},{"ten":"3. Luyện tập — Sáng tạo (3D)","gv":"- (16 phút) GV làm mẫu chậm bước khó là dựng nhân vật cho đứng vững: vê khối trụ hơi to ở chân, cắm một que tăm nhỏ nối đầu với thân rồi ấn chân nhân vật xuống đế bìa.\n- GV nêu các bước thực hành: bước 1 nghĩ xem bữa cơm nhà mình có ai và có món gì; bước 2 làm mâm cơm và các món ăn; bước 3 nặn nhân vật từ khối tròn và khối trụ; bước 4 gắn nhân vật lên đế, quay mặt vào mâm; bước 5 thêm chi tiết như bát, đũa, ghế, bình hoa.\n- GV nhắc bạn thiếu đất nặn thì dùng nắp chai làm bát đĩa, que kem làm đũa, giấy báo vò tròn làm cơm và món ăn, vỏ hộp sữa làm thân người, dây len làm tóc, vải vụn làm áo.\n- GV đi từng bàn hỗ trợ, hỏi riêng bạn còn lúng túng: Người ngồi cạnh em trong bữa cơm là ai? Trên mâm có mấy cái bát?\n- GV nhắc an toàn: que tăm chỉ dùng để nối, không chĩa về phía bạn; mũi kéo hướng xuống bàn; không đưa đất nặn lên miệng; báo trước khi còn 3 phút để HS hoàn thiện.","hs":"- HS quan sát GV làm mẫu cách dựng nhân vật cho đứng vững.\n- HS thực hành theo 5 bước: nghĩ nội dung, làm mâm cơm, nặn nhân vật, gắn lên đế, thêm chi tiết.\n- HS thiếu đất nặn thì dùng nắp chai, que kem, giấy báo vò, vỏ hộp sữa, dây len, vải vụn.\n- HS trả lời gợi ý của GV để nhớ lại cảnh bữa cơm nhà mình.\n- HS giữ an toàn khi dùng que tăm và kéo, hoàn thiện sản phẩm đúng giờ."},{"ten":"4. Vận dụng","gv":"- (8 phút) GV cho HS đặt sản phẩm lên bàn nhóm, mỗi nhóm một khu, tạo thành phòng trưng bày mini về bữa cơm gia đình ở góc lớp.\n- GV mời 4 đến 5 HS chia sẻ: Sản phẩm của em thể hiện điều gì? Trong mâm cơm có món gì? Em thích nhất bữa cơm nhà mình ở điểm nào?\n- GV nêu tiêu chí nhận xét sản phẩm: một là thể hiện đủ hình ảnh chính gồm mâm cơm và nhân vật; hai là các hình sắp xếp cân đối, nhân vật đứng vững; ba là màu sắc hài hoà, dễ nhận ra món ăn; bốn là bài sạch sẽ, có ý tưởng riêng.\n- GV cho HS đi xem một vòng, mỗi bạn dán một ngôi sao vào sản phẩm mình thích rồi nói một câu vì sao thích.\n- GV khen ngợi, dặn HS cất sản phẩm cho tiết 3 và chuẩn bị chai lọ nhựa, giấy màu để tạo dáng lọ hoa; nhắc lau bàn, nhặt vụn đất và rửa tay.","hs":"- HS đặt sản phẩm lên bàn nhóm theo khu vực của nhóm mình.\n- HS chia sẻ: nội dung sản phẩm, món ăn trong mâm cơm và điều mình thích nhất.\n- HS nghe và nhắc lại 4 tiêu chí nhận xét sản phẩm.\n- HS đi xem, dán ngôi sao vào sản phẩm mình thích và nói một câu vì sao thích.\n- HS cất sản phẩm, ghi nhớ việc chuẩn bị cho tiết 3, lau bàn và rửa tay."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":24,"tiet":24,"bai":"Chủ đề 8: BỮA CƠM GIA ĐÌNH — Tiết 3: Vận dụng (tạo dáng lọ hoa)","yccd":"1. Năng lực mĩ thuật\n- Củng cố kiến thức, kĩ năng đã học về chủ đề gia đình.\n- Tạo dáng và trang trí một lọ hoa để làm đẹp bữa cơm, không gian gia đình.\n- Biết kết hợp tạo dáng và trang trí trên sản phẩm.\n2. Năng lực chung\n- Giải quyết vấn đề và sáng tạo: tạo dáng, trang trí lọ hoa theo ý tưởng.\n- Giao tiếp và hợp tác: trao đổi cách làm với bạn.\n3. Phẩm chất\n- Yêu gia đình; biết làm đẹp không gian sống.","dodung":"- GV: hai lọ hoa mẫu làm từ vỏ chai nhựa và lon giấy, một lọ dáng thấp tròn và một lọ dáng cao thon để HS so sánh; kéo, dao rọc do GV dùng khi cắt sẵn miệng chai; thiết bị trình chiếu.\n- GV chuẩn bị vật liệu thay thế cho lớp thiếu đồ dùng: lõi giấy, hộp sữa, lon giấy, bìa carton cuộn tròn, giấy báo cũ bọc ngoài, dây len quấn thân lọ, vải vụn, hột hạt, lá khô, nắp chai.\n- HS: sản phẩm các tiết trước, chai hoặc lọ nhựa đã rửa sạch, giấy màu, đất nặn, màu vẽ, kéo, keo dán, khăn lau tay, tờ báo cũ lót bàn.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV kiểm tra sản phẩm tiết 2 và vật liệu HS mang tới, khen ngợi bạn mang được chai lọ sạch, chia vật liệu dự phòng cho bạn còn thiếu.\n- GV đặt lên bàn một lọ hoa đã trang trí và một vỏ chai chưa trang trí rồi hỏi: Em thích cái nào hơn? Vì sao? Nếu đặt lên mâm cơm thì cái nào làm bữa cơm đẹp hơn?\n- Dự kiến HS trả lời: em thích cái đã trang trí vì có màu và hoa văn; đặt lên mâm cơm thì nhìn ấm cúng hơn.\n- GV dẫn vào bài: hôm nay cả lớp sẽ tạo dáng và trang trí một lọ hoa từ vật liệu tái sử dụng để làm đẹp bữa cơm gia đình.","hs":"- HS đặt sản phẩm tiết 2 và vật liệu đã mang lên bàn cho GV kiểm tra.\n- HS quan sát hai vật mẫu và trả lời câu hỏi của GV.\n- HS nêu: thích cái đã trang trí vì có màu và hoa văn, nhìn ấm cúng hơn.\n- HS lắng nghe và nắm nhiệm vụ của tiết học."},{"ten":"2. Khám phá — Tạo dáng lọ hoa","gv":"- (7 phút) GV cho HS quan sát hai lọ hoa mẫu và hình trong SGK, chuyền tay để cả lớp nhìn gần.\n- GV nêu câu hỏi gợi mở: Lọ hoa có dáng thế nào, thấp tròn hay cao thon? Lọ được trang trí bằng họa tiết gì? Làm từ vật liệu nào? Vì sao đáy lọ phải to hơn miệng lọ?\n- Dự kiến HS trả lời: một lọ thấp tròn, một lọ cao thon; trang trí bằng chấm tròn, đường lượn, hoa lá; làm từ vỏ chai và lon giấy; đáy to hơn để lọ không bị đổ khi cắm hoa.\n- GV thị phạm chậm cách làm: bọc giấy màu quanh thân chai đã cắt sẵn miệng, dán mép giấy chồng nhau khoảng một đốt ngón tay, sau đó dán họa tiết và quấn dây len ở cổ lọ.\n- GV chốt: chọn dáng trước, bọc nền sau, cuối cùng mới trang trí họa tiết lặp lại quanh thân lọ.","hs":"- HS quan sát và chuyền tay xem hai lọ hoa mẫu.\n- HS trả lời: một lọ thấp tròn, một lọ cao thon, trang trí bằng chấm tròn, đường lượn, hoa lá.\n- HS nêu lí do đáy lọ phải to hơn miệng lọ để không bị đổ.\n- HS quan sát GV thị phạm cách bọc giấy và quấn dây len, nhắc lại thứ tự làm."},{"ten":"3. Luyện tập — Sáng tạo","gv":"- (16 phút) GV phát vỏ chai đã được GV cắt sẵn miệng cho những bạn cần, tuyệt đối không để HS tự cắt chai nhựa.\n- GV nêu các bước thực hành: bước 1 chọn vật liệu và hình dung dáng lọ; bước 2 bọc giấy màu hoặc quấn dây len làm nền; bước 3 cắt họa tiết từ giấy màu, lá khô, vải vụn; bước 4 dán họa tiết lặp lại quanh thân lọ; bước 5 trang trí thêm ở cổ lọ và đáy lọ cho cân đối.\n- GV nhắc bạn không có chai nhựa thì dùng lõi giấy, hộp sữa, lon giấy, bìa carton cuộn tròn dán đáy làm lọ.\n- GV đi từng bàn hỗ trợ, gợi ý bạn còn lúng túng chọn một họa tiết đơn giản rồi lặp lại cho đều quanh lọ.\n- GV nhắc an toàn: mũi kéo hướng xuống bàn, không dùng chai lọ thuỷ tinh, không cầm mép nhựa vừa cắt vì dễ đứt tay, keo bôi mỏng; báo trước khi còn 3 phút để HS hoàn thiện và ghi tên vào đáy lọ.","hs":"- HS nhận vỏ chai đã được GV cắt sẵn, không tự cắt chai nhựa.\n- HS thực hành theo 5 bước: chọn dáng, bọc nền, cắt họa tiết, dán họa tiết lặp lại, trang trí cổ và đáy lọ.\n- HS không có chai nhựa thì dùng lõi giấy, hộp sữa, lon giấy, bìa carton cuộn tròn.\n- HS chọn một họa tiết đơn giản và lặp lại cho đều quanh thân lọ.\n- HS giữ an toàn khi dùng kéo, hoàn thiện sản phẩm và ghi tên vào đáy lọ."},{"ten":"4. Vận dụng","gv":"- (8 phút) GV cho HS xếp lọ hoa lên bàn nhóm thành một hàng ở góc lớp, lọ cao đặt phía sau, lọ thấp đặt phía trước để nhìn rõ cả hàng.\n- GV mời 4 đến 5 HS chia sẻ nhanh: Lọ hoa của em có dáng gì? Em trang trí bằng họa tiết nào? Em sẽ đặt lọ hoa ở đâu trong nhà?\n- GV nêu tiêu chí để HS tự soi lại bài: một là lọ đứng vững, đáy chắc; hai là họa tiết lặp lại đều quanh thân lọ; ba là màu sắc hài hoà; bốn là bài sạch sẽ, có ý tưởng riêng.\n- GV cho HS đi xem một vòng, mỗi bạn dán một ngôi sao vào lọ hoa mình thích rồi nói một câu vì sao thích.\n- GV khen ngợi, dặn HS lưu giữ lọ hoa cho tiết 4 và chuẩn bị giấy màu để làm hoa cắm vào lọ; nhắc HS thu gom giấy vụn, lau bàn và rửa tay.","hs":"- HS xếp lọ hoa lên bàn nhóm, lọ cao ở sau, lọ thấp ở trước.\n- HS chia sẻ: dáng lọ, họa tiết đã trang trí và nơi sẽ đặt lọ hoa trong nhà.\n- HS nghe và tự soi lại bài của mình theo 4 tiêu chí.\n- HS đi xem, dán ngôi sao vào lọ hoa mình thích và nói một câu vì sao thích.\n- HS lưu giữ sản phẩm, ghi nhớ việc chuẩn bị cho tiết 4, lau bàn và rửa tay."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":25,"tiet":25,"bai":"Chủ đề 8: BỮA CƠM GIA ĐÌNH — Tiết 4: Vận dụng (hoàn thiện lọ hoa) và trưng bày","yccd":"1. Năng lực mĩ thuật\n- Hoàn thiện lọ hoa đã tạo dáng và trang trí ở tiết trước.\n- Trưng bày, giới thiệu và nêu cảm nhận về sản phẩm của mình và của bạn.\n- Biết đánh giá sản phẩm theo tiêu chí đơn giản.\n2. Năng lực chung\n- Giao tiếp và hợp tác: tự tin giới thiệu sản phẩm, lắng nghe nhận xét.\n3. Phẩm chất\n- Yêu gia đình; trân trọng sản phẩm và biết làm đẹp không gian sống.\n4. Tích hợp\n- Năng lực số 3.1 CB1a: Xác định được các cách tạo và chỉnh sửa nội dung đơn giản ở các định dạng đơn giản: HS nhận ra ảnh chụp sản phẩm đẹp hơn khi nền gọn và đủ sáng.","dodung":"- GV: bàn kê làm khu trưng bày có trải khăn hoặc giấy nền trơn; bảng tiêu chí đánh giá viết to; thẻ tên và ngôi sao giấy cắt sẵn; thiết bị trình chiếu.\n- GV chuẩn bị vật liệu thay thế cho lớp thiếu đồ dùng: giấy báo cũ và giấy màu để cuốn hoa, ống hút cũ hoặc que tre làm cành, lá khô, vải vụn, dây len, hột hạt, nắp chai để trang trí thêm.\n- HS: lọ hoa của tiết 3, giấy màu, màu vẽ, keo dán, kéo để hoàn thiện và làm hoa cắm vào lọ; khăn lau tay, tờ báo cũ lót bàn.","hoatdong":[{"ten":"1. Khởi động","gv":"- (3 phút) GV cho HS lấy lọ hoa của tiết 3 đặt lên bàn, kiểm tra nhanh xem lọ nào bị bong họa tiết hoặc chưa đứng vững để nhắc HS chỉnh lại ngay.\n- GV hỏi: Lọ hoa của em còn thiếu gì? Dự kiến HS trả lời: lọ em còn thiếu hoa cắm vào, còn trống một khoảng chưa trang trí, đáy lọ hơi lung lay.\n- GV nêu nhiệm vụ tiết học: hoàn thiện lọ hoa, làm hoa cắm vào lọ và trưng bày thành một góc đẹp của lớp.","hs":"- HS lấy lọ hoa tiết 3 đặt lên bàn và kiểm tra lại sản phẩm của mình.\n- HS trả lời: lọ còn thiếu hoa, còn khoảng trống chưa trang trí, đáy chưa vững.\n- HS lắng nghe, nắm nhiệm vụ của tiết học và chuẩn bị đồ dùng."},{"ten":"2. Khám phá — Hoàn thiện","gv":"- (7 phút) GV treo bảng tiêu chí và đọc chậm cho HS nghe để biết cần hoàn thiện những gì.\n- GV gợi ý các cách làm lọ hoa đẹp hơn: bổ sung họa tiết ở khoảng còn trống, quấn dây len ở cổ lọ, dán một dải giấy màu ở đáy cho lọ vững, chọn hoa có màu khác với màu thân lọ để nổi bật.\n- GV hỏi gợi mở: Nếu hoa và lọ cùng một màu thì nhìn có rõ không? Cắm mấy bông là vừa? Dự kiến HS trả lời: cùng màu thì không rõ, nên chọn màu khác; cắm ba đến năm bông cao thấp khác nhau là vừa đẹp.\n- GV làm mẫu chậm cách cuốn một bông hoa giấy: cắt dải giấy màu rộng bằng hai đốt ngón tay, cuốn tròn từ đầu này sang đầu kia, dán chân hoa vào que rồi bẻ nhẹ mép cánh cho xoè ra.","hs":"- HS đọc thầm bảng tiêu chí và biết mình cần hoàn thiện những gì.\n- HS nghe gợi ý và chọn cách làm cho lọ hoa của mình đẹp hơn.\n- HS trả lời: hoa nên khác màu thân lọ, cắm ba đến năm bông cao thấp khác nhau.\n- HS quan sát GV làm mẫu cách cuốn bông hoa giấy và gắn vào cành."},{"ten":"3. Luyện tập — Hoàn thiện sản phẩm","gv":"- (14 phút) GV nêu các bước hoàn thiện: bước 1 dán lại họa tiết bị bong và làm chắc đáy lọ; bước 2 bổ sung họa tiết vào khoảng còn trống; bước 3 cuốn hoa giấy và gắn vào cành; bước 4 cắm hoa vào lọ, bông cao ở giữa, bông thấp ở hai bên; bước 5 lau sạch lọ và ghi tên vào thẻ đặt cạnh sản phẩm.\n- GV nhắc bạn thiếu giấy màu thì cuốn hoa bằng giấy báo cũ rồi tô màu, dùng lá khô, vải vụn, hột hạt, nắp chai để trang trí thêm.\n- GV đi từng bàn hỗ trợ, giúp bạn có lọ chưa vững chèn thêm một viên đất hoặc mẩu giấy vò vào đáy.\n- GV nhắc an toàn và vệ sinh: mũi kéo hướng xuống bàn, không cầm mép nhựa vừa cắt, keo bôi mỏng, giấy vụn gom vào một góc bàn rồi bỏ vào sọt rác.\n- GV báo trước khi còn 3 phút để HS hoàn thiện và mang lọ hoa ra khu trưng bày.","hs":"- HS hoàn thiện theo 5 bước: dán lại họa tiết, bổ sung trang trí, cuốn hoa giấy, cắm hoa vào lọ, lau sạch lọ và ghi thẻ tên.\n- HS thiếu giấy màu thì cuốn hoa bằng giấy báo cũ tô màu, dùng lá khô, vải vụn, hột hạt.\n- HS có lọ chưa vững thì chèn thêm đất hoặc giấy vò vào đáy.\n- HS giữ an toàn khi dùng kéo và keo, gom giấy vụn bỏ vào sọt rác.\n- HS hoàn thiện đúng giờ và mang lọ hoa ra khu trưng bày."},{"ten":"4. Vận dụng — Trưng bày","gv":"- (7 phút) GV cho HS đặt lọ hoa lên bàn trưng bày đã trải nền trơn, xếp lọ cao ở hàng sau, lọ thấp ở hàng trước, thẻ tên đặt phía trước mỗi sản phẩm.\n- GV mời HS giới thiệu: Lọ hoa của em làm từ vật liệu gì? Em trang trí bằng họa tiết nào? Em muốn tặng lọ hoa này cho ai trong nhà?\n- GV nêu tiêu chí nhận xét sản phẩm: một là lọ đứng vững, hoa cắm chắc; hai là họa tiết trang trí sắp xếp cân đối quanh thân lọ; ba là màu của hoa và lọ hài hoà, nổi bật; bốn là sản phẩm sạch sẽ, tận dụng được vật liệu tái sử dụng.\n- GV cho HS đi xem một vòng, mỗi bạn dán một ngôi sao vào sản phẩm mình thích rồi nói một câu vì sao thích.\n- GV nhận xét, động viên; dặn xem trước Chủ đề 9 và chuẩn bị giấy màu, bút màu; nhắc HS mang lọ hoa về nhà cẩn thận, lau bàn, nhặt rác và rửa tay.","hs":"- HS đặt lọ hoa lên bàn trưng bày theo hàng cao thấp và đặt thẻ tên phía trước.\n- HS giới thiệu: vật liệu đã dùng, họa tiết trang trí và người mình muốn tặng.\n- HS nghe và nhắc lại 4 tiêu chí nhận xét sản phẩm.\n- HS đi xem, dán ngôi sao vào sản phẩm mình thích và nói một câu vì sao thích.\n- HS ghi nhớ việc chuẩn bị cho Chủ đề 9, lau bàn, nhặt rác và rửa tay."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV xếp các lọ hoa của HS lên một mặt bàn có phông nền sạch, chụp cả nhóm rồi chụp riêng từng chiếc; HS thấy cùng một sản phẩm nhưng đặt nền gọn, đủ sáng thì ảnh đẹp hơn hẳn.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 1) HS nói cho cả lớp nghe mình đã tận dụng vỏ chai, vỏ hộp gì để làm lọ hoa.\n⚠ (Miền 4: An toàn) Không dùng chai lọ thuỷ tinh vỡ hay sắc cạnh; đặt sản phẩm chắc chắn rồi mới chụp; ảnh sản phẩm chỉ chiếu trong lớp và cho cha mẹ xem.","hs":"- HS nhận ra ảnh chụp sản phẩm đẹp hơn khi nền gọn và đủ sáng.\n- HS giới thiệu được vật liệu tái sử dụng mình đã dùng."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":26,"tiet":26,"bai":"Chủ đề 9: THẦY CÔ CỦA EM — Tiết 1: Quan sát và thể hiện (theo liên tưởng)","yccd":"1. Năng lực mĩ thuật\n- Tìm hiểu, mô tả được hình ảnh liên quan đến chủ đề thầy cô.\n- Thể hiện được về chủ đề từ hình ảnh đã liên tưởng (vẽ hoặc xé dán).\n- Bước đầu biết chọn hình ảnh, hoạt động tiêu biểu về thầy cô.\n2. Năng lực chung\n- Tự chủ và tự học: nhớ lại, liên tưởng hình ảnh thầy cô để thể hiện.\n- Giao tiếp và hợp tác: chia sẻ tình cảm với thầy cô.\n3. Phẩm chất\n- Kính trọng, biết ơn thầy cô giáo; chăm ngoan, lễ phép.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS kể được những việc thầy cô làm hằng ngày sau khi xem phim, ảnh.","dodung":"- Giáo viên: tranh ảnh về thầy cô và hoạt động dạy học; sản phẩm mĩ thuật mẫu; thiết bị trình chiếu.\n- Học sinh: SGK Mĩ thuật 2, Vở bài tập Mĩ thuật 2, bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, hồ dán.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS hát/nghe một bài hát về thầy cô, hỏi: Em nhớ nhất hình ảnh nào của thầy cô?\n- GV nhận xét, giới thiệu chủ đề.","hs":"- HS hát/nghe, trả lời câu hỏi.\n- HS lắng nghe, mở bài học."},{"ten":"2. Khám phá — Hình ảnh thầy cô","gv":"- GV cho HS quan sát tranh ảnh về thầy cô và hình trong SGK.\n- GV đặt câu hỏi: Thầy cô đang làm gì? Hình ảnh nào gợi cho em nhiều cảm xúc? Em muốn thể hiện thầy cô trong hoạt động nào?\n- GV chốt về cách chọn hình ảnh, hoạt động tiêu biểu.","hs":"- HS quan sát, trả lời câu hỏi.\n- HS liên tưởng, chọn hình ảnh về thầy cô.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập — Sáng tạo","gv":"- GV hướng dẫn HS tham khảo cách thể hiện trong SGK.\n- GV yêu cầu HS vẽ hoặc xé dán một sản phẩm về chủ đề thầy cô từ hình ảnh đã liên tưởng.\n- GV quan sát, giúp đỡ; nhắc HS lưu giữ sản phẩm cho tiết sau.","hs":"- HS tham khảo, tiếp thu cách làm.\n- HS thực hành thể hiện chủ đề thầy cô.\n- HS lưu giữ sản phẩm."},{"ten":"4. Vận dụng","gv":"- GV cho HS chia sẻ: em thể hiện thầy cô trong hoạt động nào?\n- GV khen ngợi, dặn HS chuẩn bị cho tiết 2.","hs":"- HS chia sẻ về sản phẩm.\n- HS ghi nhớ nhiệm vụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu bộ ảnh và đoạn phim ngắn về công việc hằng ngày của thầy cô: soạn bài, chấm bài, hướng dẫn HS tập thể dục, tưới cây cùng HS; HS nhận ra nhiều việc thầy cô làm mà lúc học các em không nhìn thấy.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) HS chọn một việc trong phim để đưa vào tranh của mình và tả lại việc đó bằng lời.\n⚠ (Miền 4: An toàn) Phim, ảnh về thầy cô do nhà trường và GV cung cấp; HS không tự quay, chụp thầy cô hay các bạn khi chưa xin phép.","hs":"- HS kể được những việc thầy cô làm hằng ngày sau khi xem phim, ảnh.\n- HS chọn được một việc để thể hiện trong tranh của mình."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":27,"tiet":27,"bai":"Chủ đề 9: THẦY CÔ CỦA EM — Tiết 2: Thể hiện (theo cách yêu thích)","yccd":"1. Năng lực mĩ thuật\n- Tìm hiểu về chủ đề thông qua một số bức tranh.\n- Thể hiện được một sản phẩm mĩ thuật về chủ đề theo cách mình yêu thích.\n- Biết chọn hình thức, chất liệu phù hợp để thể hiện.\n2. Năng lực chung\n- Giải quyết vấn đề và sáng tạo: chọn cách thể hiện riêng về chủ đề thầy cô.\n- Giao tiếp và hợp tác: chia sẻ, trao đổi với bạn.\n3. Phẩm chất\n- Kính trọng, biết ơn thầy cô; chăm chỉ, sáng tạo.","dodung":"- GV: ba bức tranh về chủ đề thầy cô thể hiện bằng ba cách khác nhau (vẽ màu sáp, xé dán giấy, đắp nổi đất nặn) để HS so sánh; sản phẩm mẫu; thiết bị trình chiếu.\n- GV chuẩn bị vật liệu thay thế cho lớp thiếu đồ dùng: mặt sau tờ lịch, giấy báo cũ, bìa carton, giấy màu, lá khô, vải vụn, dây len, hột hạt, nắp chai, đất nặn dùng chung theo bàn.\n- HS: sản phẩm tiết 1, màu vẽ, giấy vẽ, giấy màu, đất nặn, kéo, hồ dán, khăn lau tay, tờ báo cũ lót bàn.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV kiểm tra sản phẩm tiết 1 và đồ dùng của từng bàn, khen ngợi, động viên; cho mượn vật liệu dự phòng với bạn còn thiếu.\n- GV hỏi để gợi cảm xúc: Thầy cô nào để lại cho em ấn tượng nhất? Em nhớ nhất hình ảnh thầy cô đang làm gì?\n- Dự kiến HS trả lời: em nhớ cô đang giảng bài bên bảng, cô cầm tay em tập viết, thầy dạy cả lớp tập thể dục ngoài sân.\n- GV treo ba bức tranh về thầy cô lên bảng và dẫn vào bài: hôm nay mỗi bạn sẽ thể hiện một sản phẩm về thầy cô theo cách mình yêu thích.","hs":"- HS đặt sản phẩm tiết 1 và đồ dùng lên bàn cho GV kiểm tra.\n- HS nhớ lại và kể về thầy cô của mình.\n- HS trả lời: em nhớ cô giảng bài bên bảng, cô cầm tay em tập viết, thầy dạy thể dục.\n- HS quan sát ba bức tranh trên bảng và nắm nhiệm vụ của tiết học."},{"ten":"2. Khám phá — Xem tranh về thầy cô","gv":"- (7 phút) GV cho HS quan sát lần lượt ba bức tranh, mỗi bức khoảng một phút, vừa chỉ vừa nêu tên cách thể hiện của từng bức.\n- GV nêu câu hỏi gợi mở: Tranh thể hiện hoạt động gì? Bức nào vẽ bằng màu, bức nào xé dán, bức nào đắp nổi? Màu sắc trong tranh cho em cảm giác gì? Em thích cách thể hiện nào nhất, vì sao?\n- Dự kiến HS trả lời: tranh vẽ cô giảng bài và các bạn ngồi học; bức thứ nhất vẽ bằng sáp màu, bức thứ hai xé dán giấy, bức thứ ba đắp nổi; màu ấm làm em thấy vui; em thích xé dán vì dễ làm và nhìn ngộ nghĩnh.\n- GV chốt: cùng một chủ đề có nhiều cách thể hiện; hãy chọn cách nào mình làm tốt nhất và có đủ vật liệu, quan trọng là hình ảnh chính phải rõ và có tình cảm.","hs":"- HS quan sát lần lượt ba bức tranh theo tay chỉ của GV.\n- HS trả lời: tranh thể hiện cô giảng bài, các bạn ngồi học; nhận ra ba cách thể hiện khác nhau.\n- HS nêu cảm nhận về màu sắc và cách thể hiện mình thích nhất.\n- HS nhắc lại ý chốt: chọn cách mình làm tốt nhất, hình ảnh chính phải rõ."},{"ten":"3. Luyện tập — Sáng tạo","gv":"- (16 phút) GV làm mẫu chậm bước khó của hai cách hay dùng: khi vẽ thì phác hình người bằng vài nét đơn giản là đầu tròn, thân hình chữ nhật, tay chân là nét; khi xé dán thì xé từng mảng to trước rồi mới xé chi tiết nhỏ.\n- GV nêu các bước thực hành: bước 1 chọn hình ảnh muốn thể hiện; bước 2 chọn cách làm là vẽ, xé dán hay nặn; bước 3 làm hình ảnh chính to ở giữa bài; bước 4 thêm hình ảnh phụ như bảng lớp, bàn ghế, cây, hoa; bước 5 tô màu nền và xem lại toàn bài.\n- GV nhắc bạn thiếu giấy vẽ thì dùng mặt sau tờ lịch hoặc giấy báo cũ; thiếu giấy màu thì dùng giấy báo tô màu, lá khô, vải vụn, dây len; thiếu đất nặn thì vò giấy báo thành mảng đắp lên bìa.\n- GV đi từng bàn hỗ trợ, gợi ý bạn chưa nghĩ ra: Cô thường mặc áo màu gì? Trong lớp có những gì phía sau cô?\n- GV nhắc an toàn: mũi kéo hướng xuống bàn, hồ dán bôi mỏng, không đưa tay dính màu và hồ lên mắt, miệng; báo trước khi còn 3 phút để HS hoàn thiện, ghi tên và cất bài cho tiết sau.","hs":"- HS quan sát GV làm mẫu cách phác hình người và cách xé mảng to trước.\n- HS thực hành theo 5 bước: chọn hình ảnh, chọn cách làm, làm hình chính, thêm hình phụ, tô nền và xem lại bài.\n- HS thiếu đồ dùng thì dùng mặt sau tờ lịch, giấy báo, lá khô, vải vụn, dây len thay thế.\n- HS trả lời gợi ý của GV để nhớ rõ hình ảnh thầy cô mình muốn thể hiện.\n- HS giữ an toàn khi dùng kéo và hồ dán, hoàn thiện bài, ghi tên và cất bài cho tiết sau."},{"ten":"4. Vận dụng","gv":"- (8 phút) GV cho HS dán hoặc đặt sản phẩm lên bảng nhóm theo chủ đề thầy cô, ghép các bảng nhóm thành phòng tranh mini ở góc lớp.\n- GV mời 4 đến 5 HS chia sẻ: Em chọn cách thể hiện nào? Vì sao em chọn cách ấy? Sản phẩm của em kể lại chuyện gì về thầy cô?\n- GV nêu tiêu chí nhận xét sản phẩm: một là thể hiện rõ hình ảnh thầy cô và hoạt động ở lớp; hai là hình ảnh chính to, sắp xếp cân đối; ba là màu sắc hài hoà, phù hợp với tình cảm muốn thể hiện; bốn là bài sạch sẽ, có ý tưởng riêng.\n- GV cho HS đi xem một vòng, mỗi bạn dán một ngôi sao vào sản phẩm mình thích rồi nói một câu vì sao thích.\n- GV khen ngợi, dặn HS lưu giữ sản phẩm cho tiết 3 và chuẩn bị giấy màu, kéo, keo để làm quà lưu niệm; nhắc thu gom giấy vụn, lau bàn và rửa tay.","hs":"- HS dán hoặc đặt sản phẩm lên bảng nhóm tạo thành phòng tranh mini.\n- HS chia sẻ: cách thể hiện đã chọn, lí do chọn và câu chuyện trong sản phẩm.\n- HS nghe và nhắc lại 4 tiêu chí nhận xét sản phẩm.\n- HS đi xem, dán ngôi sao vào sản phẩm mình thích và nói một câu vì sao thích.\n- HS lưu giữ sản phẩm, ghi nhớ việc chuẩn bị cho tiết 3, lau bàn và rửa tay."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":28,"tiet":28,"bai":"Chủ đề 9: THẦY CÔ CỦA EM — Tiết 3: Thảo luận và vận dụng (làm món quà lưu niệm)","yccd":"1. Năng lực mĩ thuật\n- Củng cố kiến thức, kĩ năng đã học về chủ đề thầy cô.\n- Làm được một món quà lưu niệm (thiệp, hoa giấy, khung ảnh nhỏ...) tặng thầy cô.\n- Nêu được cảm nhận về sản phẩm của mình và của bạn.\n2. Năng lực chung\n- Giải quyết vấn đề và sáng tạo: lựa chọn hình thức món quà phù hợp.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ cách làm với bạn.\n3. Phẩm chất\n- Kính trọng, biết ơn thầy cô; biết thể hiện tình cảm qua món quà tự làm.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS làm được món quà theo phim hướng dẫn và biết tua chậm lại bước khó.","dodung":"- GV: ba món quà lưu niệm mẫu (tấm thiệp gấp đôi, bông hoa giấy, khung ảnh nhỏ bằng bìa) để HS chọn cách làm; giấy màu, ruy băng, khay đựng vật liệu; thiết bị trình chiếu.\n- GV chuẩn bị vật liệu thay thế cho lớp thiếu đồ dùng: bìa carton cắt sẵn khung, giấy báo cũ tô màu, mặt sau tờ lịch, lá khô ép phẳng, vải vụn, dây len, hột hạt, nắp chai, ống hút cũ.\n- HS: sản phẩm các tiết trước, giấy màu, bút màu, kéo, keo dán, vật liệu trang trí sưu tầm được, khăn lau tay, tờ báo cũ lót bàn.","hoatdong":[{"ten":"1. Khởi động","gv":"- (3 phút) GV kiểm tra sản phẩm tiết 2 và vật liệu HS mang tới, khen ngợi, động viên; chia vật liệu dự phòng cho bạn còn thiếu.\n- GV đưa ra một tấm thiệp tự làm và hỏi: Nếu được tặng thiệp này, thầy cô sẽ thấy thế nào? Vì sao món quà tự làm lại quý?\n- Dự kiến HS trả lời: thầy cô sẽ rất vui; món quà tự làm quý vì mình bỏ công sức và tình cảm vào đó.\n- GV dẫn vào bài: hôm nay cả lớp sẽ tự làm một món quà lưu niệm để tặng thầy cô.","hs":"- HS đặt sản phẩm tiết 2 và vật liệu lên bàn cho GV kiểm tra.\n- HS quan sát tấm thiệp mẫu và trả lời câu hỏi của GV.\n- HS nêu: thầy cô sẽ vui vì món quà tự làm chứa tình cảm của mình.\n- HS lắng nghe và nắm nhiệm vụ của tiết học."},{"ten":"2. Khám phá — Thảo luận và tìm hiểu quà lưu niệm","gv":"- (7 phút) GV cho HS thảo luận theo nhóm đôi trong hai phút với câu hỏi: Em muốn làm món quà gì tặng thầy cô? Cần những vật liệu nào? Vì sao em chọn món quà ấy?\n- GV mời vài nhóm trình bày. Dự kiến HS trả lời: em làm tấm thiệp có bông hoa nổi vì cô thích hoa; em làm khung ảnh nhỏ để cô đặt lên bàn; em làm hoa giấy vì ở nhà có nhiều giấy màu.\n- GV cho HS chuyền tay xem ba món quà mẫu, chỉ rõ chỗ khó của từng món: nếp gấp của thiệp phải miết thẳng, cánh hoa phải bẻ đều, khung ảnh phải dán vuông góc.\n- GV chốt cách làm: chọn món quà vừa sức, làm phần chính cho chắc trước, trang trí sau, cuối cùng mới viết lời chúc.","hs":"- HS thảo luận nhóm đôi và chọn món quà mình sẽ làm.\n- HS trình bày: món quà đã chọn, vật liệu cần dùng và lí do chọn.\n- HS chuyền tay xem ba món quà mẫu và ghi nhớ chỗ khó của từng món.\n- HS nhắc lại thứ tự làm: phần chính trước, trang trí sau, viết lời chúc cuối cùng."},{"ten":"3. Luyện tập — Sáng tạo","gv":"- (14 phút) GV làm mẫu chậm hai bước khó: gấp đôi tờ bìa rồi miết nếp bằng cạnh móng tay cho thẳng; cắt dải giấy màu rồi cuốn thành bông hoa, dán chân hoa vào mặt thiệp.\n- GV nêu các bước thực hành: bước 1 chọn món quà và vật liệu; bước 2 làm phần chính là tấm thiệp, bông hoa hoặc khung ảnh; bước 3 cắt và dán họa tiết trang trí; bước 4 viết lời chúc ngắn và ghi tên mình; bước 5 xem lại, dán chắc những chỗ còn bong.\n- GV nhắc bạn thiếu giấy màu thì dùng bìa carton, giấy báo cũ tô màu, mặt sau tờ lịch, lá khô, vải vụn, dây len, hột hạt để trang trí.\n- GV đi từng bàn hỗ trợ, nhắc HS viết lời chúc ngắn, chữ rõ ràng; nhắc an toàn: mũi kéo hướng xuống bàn, đưa kéo cho bạn thì cầm phần lưỡi, keo bôi mỏng, không cho tay dính keo lên mắt.\n- GV báo trước khi còn 3 phút để HS hoàn thiện và đặt sản phẩm lên bàn nhóm.","hs":"- HS quan sát GV làm mẫu cách miết nếp gấp và cách cuốn bông hoa giấy.\n- HS thực hành theo 5 bước: chọn quà, làm phần chính, trang trí, viết lời chúc, dán lại chỗ bong.\n- HS thiếu giấy màu thì dùng bìa carton, giấy báo tô màu, lá khô, vải vụn, dây len.\n- HS viết lời chúc ngắn, chữ rõ ràng và giữ an toàn khi dùng kéo, keo dán.\n- HS hoàn thiện đúng giờ và đặt sản phẩm lên bàn nhóm."},{"ten":"4. Vận dụng — Trưng bày","gv":"- (7 phút) GV cho HS bày quà lưu niệm lên bàn nhóm theo từng loại, thiệp một hàng, hoa giấy một hàng, khung ảnh một hàng, tạo thành góc quà của lớp.\n- GV mời HS giới thiệu: Em làm món quà gì? Em muốn tặng thầy cô nào? Lời chúc của em viết thế nào?\n- GV nêu tiêu chí nhận xét sản phẩm: một là món quà làm chắc chắn, không bong, không rách; hai là họa tiết trang trí sắp xếp cân đối; ba là màu sắc hài hoà, chữ viết rõ ràng; bốn là sản phẩm sạch sẽ, có ý tưởng riêng và thể hiện được tình cảm.\n- GV cho HS đi xem một vòng, mỗi bạn dán một ngôi sao vào món quà mình thích rồi nói một câu vì sao thích.\n- GV nhận xét, động viên; dặn HS giữ quà cẩn thận và chuẩn bị giấy màu, bút màu cho tiết sau để hoàn thiện và trưng bày; nhắc thu gom giấy vụn, lau bàn, rửa tay.","hs":"- HS bày quà lưu niệm lên bàn nhóm theo từng loại.\n- HS giới thiệu: món quà đã làm, người muốn tặng và lời chúc đã viết.\n- HS nghe và nhắc lại 4 tiêu chí nhận xét sản phẩm.\n- HS đi xem, dán ngôi sao vào món quà mình thích và nói một câu vì sao thích.\n- HS giữ quà cẩn thận, ghi nhớ việc chuẩn bị cho tiết sau, lau bàn và rửa tay."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu đoạn phim hướng dẫn gấp hoa giấy, làm thiếp nổi, dừng lại và tua chậm ở bước khó để HS xem lại vài lần trước khi tự làm; xem GV làm mẫu một lần thì bạn ngồi xa không kịp nhìn rõ.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 1) HS làm theo từng bước; bạn nào làm được trước thì quay sang giúp bạn bên cạnh.\n⚠ (Miền 4: An toàn) Cẩn thận với kéo và keo dán khi làm theo phim; chỉ mở đúng đoạn phim GV đã tải sẵn, không bấm sang phim khác đang gợi ý bên cạnh.","hs":"- HS làm được món quà theo phim hướng dẫn và biết tua chậm lại bước khó.\n- HS giúp bạn bên cạnh hoàn thành sản phẩm."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":29,"tiet":29,"bai":"Chủ đề 9: THẦY CÔ CỦA EM — Tiết 4: Vận dụng (hoàn thiện quà lưu niệm) và trưng bày","yccd":"1. Năng lực mĩ thuật\n- Hoàn thiện món quà lưu niệm tặng thầy cô.\n- Trưng bày, giới thiệu và nêu cảm nhận về sản phẩm của mình và của bạn.\n- Biết đánh giá sản phẩm theo tiêu chí đơn giản.\n2. Năng lực chung\n- Giao tiếp và hợp tác: tự tin giới thiệu sản phẩm, lắng nghe nhận xét.\n3. Phẩm chất\n- Kính trọng, biết ơn thầy cô; trân trọng sản phẩm tự làm.\n4. Tích hợp\n- Năng lực số 2.5 CB1a: Phân biệt được chuẩn mực hành vi đơn giản và biết cách sử dụng công nghệ số và tương tác trong môi trường số: HS viết và đọc được lời chúc lễ phép, chân thành.","dodung":"- GV: bảng trưng bày hoặc bàn kê trải khăn làm góc quà của lớp; bảng tiêu chí đánh giá viết to; thẻ tên, ngôi sao giấy cắt sẵn; thiết bị trình chiếu.\n- GV chuẩn bị vật liệu thay thế cho lớp thiếu đồ dùng: bìa carton, giấy báo cũ tô màu, mặt sau tờ lịch, giấy màu vụn, lá khô, vải vụn, dây len, hột hạt, ruy băng cũ để trang trí thêm.\n- HS: sản phẩm tiết 3, giấy màu, bút màu, keo dán, kéo để hoàn thiện; khăn lau tay, tờ báo cũ lót bàn.","hoatdong":[{"ten":"1. Khởi động","gv":"- (3 phút) GV cho HS lấy món quà của tiết 3 đặt lên bàn, kiểm tra nhanh xem bài nào còn bong keo, rách mép để nhắc HS sửa ngay.\n- GV hỏi: Món quà của em còn thiếu gì? Dự kiến HS trả lời: quà em còn thiếu lời chúc, còn một góc chưa trang trí, cánh hoa bị bong keo.\n- GV nêu nhiệm vụ tiết học: hoàn thiện món quà, viết lời chúc và trưng bày thành góc quà của lớp để tặng thầy cô.","hs":"- HS lấy món quà tiết 3 đặt lên bàn và kiểm tra lại sản phẩm.\n- HS trả lời: quà còn thiếu lời chúc, còn góc chưa trang trí, cánh hoa bị bong.\n- HS lắng nghe, nắm nhiệm vụ của tiết học và chuẩn bị đồ dùng."},{"ten":"2. Khám phá — Hoàn thiện","gv":"- (7 phút) GV treo bảng tiêu chí và đọc chậm cho HS nghe để biết cần hoàn thiện những gì.\n- GV gợi ý cách làm quà đẹp hơn: thêm viền quanh mép thiệp, dán thêm một lớp giấy khác màu phía sau cho món quà cứng cáp, thêm nơ bằng dây len hoặc ruy băng, chấm thêm hạt nhỏ ở góc.\n- GV hướng dẫn viết lời chúc: viết một đến hai câu ngắn, có tên thầy cô ở đầu và tên mình ở cuối; GV viết mẫu lên bảng một câu để HS tham khảo chứ không chép y nguyên.\n- GV hỏi gợi mở: Lời chúc thế nào là lễ phép và chân thành? Dự kiến HS trả lời: nói lời cảm ơn thật lòng, xưng hô lễ phép, không viết đùa cợt, chữ viết cẩn thận.","hs":"- HS đọc thầm bảng tiêu chí và biết mình cần hoàn thiện những gì.\n- HS nghe gợi ý và chọn cách trang trí thêm cho món quà của mình.\n- HS quan sát câu mẫu trên bảng rồi tự nghĩ lời chúc của riêng mình.\n- HS trả lời: lời chúc lễ phép là nói thật lòng, xưng hô đúng, chữ viết cẩn thận."},{"ten":"3. Luyện tập — Hoàn thiện sản phẩm","gv":"- (14 phút) GV nêu các bước hoàn thiện: bước 1 dán lại các chỗ bong, sửa mép rách; bước 2 bổ sung trang trí ở chỗ còn trống; bước 3 viết lời chúc bằng chữ rõ ràng, ghi tên mình; bước 4 làm nơ hoặc viền để món quà thêm đẹp; bước 5 lau sạch mặt sản phẩm và đặt vào phong bì hoặc túi giấy nếu có.\n- GV nhắc bạn thiếu vật liệu thì dùng giấy báo cũ tô màu, bìa carton, mặt sau tờ lịch, lá khô, vải vụn, dây len, ruy băng cũ.\n- GV đi từng bàn hỗ trợ, giúp bạn viết chữ chưa đều bằng cách kẻ nhẹ hai dòng chì rồi viết lên trên, viết xong tẩy đi.\n- GV nhắc an toàn và vệ sinh: mũi kéo hướng xuống bàn, keo bôi mỏng, không đưa tay dính keo lên mắt và miệng, giấy vụn gom lại bỏ vào sọt rác.\n- GV báo trước khi còn 3 phút để HS hoàn thiện và mang sản phẩm ra góc trưng bày.","hs":"- HS hoàn thiện theo 5 bước: dán lại chỗ bong, bổ sung trang trí, viết lời chúc, làm nơ hoặc viền, lau sạch sản phẩm.\n- HS thiếu vật liệu thì dùng giấy báo tô màu, bìa carton, lá khô, vải vụn, dây len.\n- HS kẻ nhẹ hai dòng chì để viết lời chúc cho đều rồi tẩy đi.\n- HS giữ an toàn khi dùng kéo và keo, gom giấy vụn bỏ vào sọt rác.\n- HS hoàn thiện đúng giờ và mang sản phẩm ra góc trưng bày."},{"ten":"4. Vận dụng — Trưng bày","gv":"- (7 phút) GV cho HS bày quà lên bàn trưng bày đã trải khăn, xếp theo từng loại và đặt thẻ tên phía trước mỗi món quà, tạo thành góc quà lưu niệm của lớp.\n- GV mời HS giới thiệu và đọc lời chúc của mình trước lớp: Em thích món quà nào nhất? Vì sao? Lời chúc của em muốn nói điều gì?\n- GV nêu tiêu chí nhận xét sản phẩm: một là món quà hoàn chỉnh, chắc chắn, không bong rách; hai là trang trí cân đối, hài hoà về màu sắc; ba là lời chúc lễ phép, chữ viết rõ ràng; bốn là sản phẩm sạch sẽ, có ý tưởng riêng.\n- GV cho HS đi xem một vòng, mỗi bạn dán một ngôi sao vào món quà mình thích rồi nói một câu vì sao thích.\n- GV nhận xét, động viên; dặn xem trước Chủ đề 10 và chuẩn bị vỏ chai, hộp giấy, nắp chai đã rửa sạch; nhắc HS lau bàn, nhặt rác và rửa tay.","hs":"- HS bày quà lên bàn trưng bày theo từng loại và đặt thẻ tên phía trước.\n- HS giới thiệu món quà, đọc lời chúc của mình trước lớp.\n- HS nghe và nhắc lại 4 tiêu chí nhận xét sản phẩm.\n- HS đi xem, dán ngôi sao vào món quà mình thích và nói một câu vì sao thích.\n- HS ghi nhớ việc chuẩn bị cho Chủ đề 10, lau bàn, nhặt rác và rửa tay."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV chụp món quà của HS kèm tấm thiếp ghi lời chúc, ghép thành một trang trưng bày của lớp để tặng thầy cô xem.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 1) HS đọc to lời chúc của mình, cả lớp góp ý để lời chúc chân thành và lễ phép hơn.\n⚠ (Miền 4: An toàn) Trang trưng bày chỉ gửi tới thầy cô trong trường, không đăng lên mạng; lời chúc ghi tên người nhận nhưng không ghi số điện thoại, địa chỉ của ai.","hs":"- HS viết và đọc được lời chúc lễ phép, chân thành.\n- HS xem trang trưng bày quà của cả lớp và nhận xét tích cực."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":30,"tiet":30,"bai":"Chủ đề 10: ĐỒ CHƠI TỪ TẠO HÌNH CON VẬT — Tiết 1: Quan sát và thể hiện (chiếc mặt nạ)","yccd":"1. Năng lực mĩ thuật\n- Tìm hiểu, mô tả một số đồ chơi dân gian truyền thống Việt Nam.\n- Thể hiện được về chiếc mặt nạ con vật (vẽ, xé dán hoặc tạo hình trên bìa).\n- Bước đầu biết tạo dáng, trang trí mặt nạ con vật.\n2. Năng lực chung\n- Tự chủ và tự học: quan sát, lựa chọn con vật để tạo mặt nạ.\n- Giao tiếp và hợp tác: chia sẻ về đồ chơi dân gian.\n3. Phẩm chất\n- Yêu quý đồ chơi dân gian truyền thống; tự hào về nét đẹp văn hóa dân tộc.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS kể được một số đồ chơi dân gian và vật liệu làm ra chúng.","dodung":"- Giáo viên: một số đồ chơi dân gian (mặt nạ, đèn ông sao...); mặt nạ con vật mẫu; thiết bị trình chiếu.\n- Học sinh: SGK Mĩ thuật 2, Vở bài tập Mĩ thuật 2, giấy bìa, màu vẽ, giấy màu, kéo, keo dán, dây.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS xem một số đồ chơi dân gian, hỏi: Em biết những đồ chơi dân gian nào?\n- GV nhận xét, giới thiệu chủ đề.","hs":"- HS quan sát, kể tên đồ chơi dân gian.\n- HS lắng nghe, mở bài học."},{"ten":"2. Khám phá — Đồ chơi dân gian và mặt nạ","gv":"- GV cho HS quan sát đồ chơi dân gian, mặt nạ con vật và hình trong SGK.\n- GV đặt câu hỏi: Mặt nạ có hình con vật gì? Được trang trí thế nào? Làm từ vật liệu nào?\n- GV chốt về đặc điểm, cách làm mặt nạ con vật.","hs":"- HS quan sát, trả lời câu hỏi.\n- HS nhận biết cách tạo dáng, trang trí mặt nạ.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập — Sáng tạo","gv":"- GV hướng dẫn HS tham khảo cách làm mặt nạ trong SGK.\n- GV yêu cầu HS thể hiện một chiếc mặt nạ con vật yêu thích (vẽ, xé dán, tạo hình trên bìa).\n- GV quan sát, giúp đỡ; nhắc HS lưu giữ sản phẩm cho tiết sau.","hs":"- HS tham khảo, tiếp thu cách làm.\n- HS thực hành làm mặt nạ con vật.\n- HS lưu giữ sản phẩm."},{"ten":"4. Vận dụng","gv":"- GV cho HS chia sẻ: em làm mặt nạ con vật gì? Trang trí thế nào?\n- GV khen ngợi, dặn HS chuẩn bị cho tiết 2.","hs":"- HS chia sẻ về sản phẩm.\n- HS ghi nhớ nhiệm vụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu phim tư liệu về đồ chơi dân gian Việt Nam: mặt nạ giấy bồi, tò he, đèn ông sao, con giống bột; phim quay cận cảnh bàn tay người thợ nên HS thấy rõ từng thao tác nặn, phết màu.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) HS gọi tên các đồ chơi trong phim và nói món nào mình đã từng chơi.\n⚠ (Miền 4: An toàn) GV mở đoạn phim đã tải sẵn; HS xem để hiểu công sức của người thợ làm ra một món đồ chơi, không đòi mua đồ chơi theo quảng cáo chen trong các phim trên mạng.","hs":"- HS kể được một số đồ chơi dân gian và vật liệu làm ra chúng.\n- HS nêu được cảm nhận về công sức của người thợ thủ công."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":31,"tiet":31,"bai":"Chủ đề 10: ĐỒ CHƠI TỪ TẠO HÌNH CON VẬT — Tiết 2: Thể hiện (đồ chơi từ vật liệu tái sử dụng)","yccd":"1. Năng lực mĩ thuật\n- Tìm hiểu đồ chơi làm từ vật liệu tái sử dụng.\n- Thể hiện được một món đồ chơi con vật từ vật liệu tái sử dụng.\n- Biết kết hợp tạo dáng và trang trí đồ chơi.\n2. Năng lực chung\n- Giải quyết vấn đề và sáng tạo: tận dụng vật liệu tái sử dụng để tạo đồ chơi.\n- Giao tiếp và hợp tác: phối hợp với bạn khi làm sản phẩm.\n3. Phẩm chất\n- Yêu thiên nhiên, bảo vệ môi trường; tiết kiệm, tận dụng vật liệu tái sử dụng.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS làm được đồ chơi con vật từ vật liệu tái sử dụng theo phim hướng dẫn.","dodung":"- GV: ba món đồ chơi con vật mẫu làm từ vỏ chai, hộp giấy và nắp chai (con lợn, con thỏ, con rùa); khay chia vật liệu theo loại; thiết bị trình chiếu.\n- GV chuẩn bị vật liệu thay thế cho lớp thiếu đồ dùng: hộp sữa, lõi giấy, vỏ hộp bánh, bìa carton, giấy báo cũ, nắp chai, ống hút cũ, que kem, dây len, vải vụn, hột hạt, lá khô.\n- HS: sản phẩm tiết 1, chai hoặc lọ nhựa, hộp giấy, nắp chai đã rửa sạch và để khô, vải vụn, màu vẽ, kéo, keo dán, khăn lau tay, tờ báo cũ lót bàn.","hoatdong":[{"ten":"1. Khởi động","gv":"- (3 phút) GV kiểm tra sản phẩm tiết 1 và vật liệu HS mang tới, khen ngợi bạn mang vỏ hộp đã rửa sạch, chia vật liệu dự phòng cho bạn còn thiếu.\n- GV giơ một vỏ chai nhựa và hỏi: Nếu bỏ đi thì vỏ chai này thành gì? Nếu giữ lại thì có thể làm gì?\n- Dự kiến HS trả lời: bỏ đi thì thành rác làm bẩn môi trường; giữ lại có thể làm lọ hoa, ống đựng bút, con vật đồ chơi.\n- GV đưa ba món đồ chơi mẫu ra và dẫn vào bài: hôm nay cả lớp sẽ biến vật liệu bỏ đi thành đồ chơi con vật.","hs":"- HS đặt sản phẩm tiết 1 và vật liệu đã mang lên bàn cho GV kiểm tra.\n- HS quan sát vỏ chai và trả lời câu hỏi của GV.\n- HS nêu: bỏ đi thành rác, giữ lại có thể làm lọ hoa, ống bút, con vật đồ chơi.\n- HS quan sát ba món đồ chơi mẫu và nắm nhiệm vụ của tiết học."},{"ten":"2. Khám phá — Đồ chơi từ vật liệu tái sử dụng","gv":"- (7 phút) GV cho HS chuyền tay xem ba món đồ chơi mẫu, mỗi bàn xem khoảng nửa phút rồi chuyển tiếp.\n- GV nêu câu hỏi gợi mở: Đồ chơi làm từ vật liệu gì? Bộ phận nào của con vật được làm từ nắp chai? Vì sao nên tái sử dụng vật liệu thay vì vứt đi?\n- Dự kiến HS trả lời: làm từ vỏ chai, hộp giấy, nắp chai; nắp chai làm chân và mắt; tái sử dụng để đỡ rác, giữ môi trường sạch và tiết kiệm tiền mua đồ chơi.\n- GV chỉ rõ mẹo nhìn ra con vật trong vật liệu: chai nằm ngang giống thân con lợn, hộp giấy đứng giống thân con thỏ, hai nắp chai úp lại giống mai con rùa.\n- GV chốt: nhìn hình dáng vật liệu để chọn con vật cho phù hợp, sau đó chỉ cần thêm tai, mắt, chân, đuôi là ra con vật.","hs":"- HS chuyền tay xem ba món đồ chơi mẫu và quan sát kĩ từng bộ phận.\n- HS trả lời: đồ chơi làm từ vỏ chai, hộp giấy, nắp chai; nắp chai làm chân và mắt.\n- HS nêu ích lợi của việc tái sử dụng vật liệu: đỡ rác, giữ môi trường sạch.\n- HS nhắc lại mẹo: nhìn dáng vật liệu để chọn con vật rồi thêm tai, mắt, chân, đuôi."},{"ten":"3. Luyện tập — Sáng tạo","gv":"- (14 phút) GV làm mẫu chậm bước khó là gắn chân và tai cho chắc: chấm keo vào chỗ gắn, ấn giữ và đếm chậm đến mười rồi mới buông tay; chỗ khó dính thì dán thêm một mẩu băng dính bên trong.\n- GV nêu các bước thực hành: bước 1 chọn vật liệu và nghĩ xem nó giống con vật gì; bước 2 làm thân con vật; bước 3 gắn tai, chân, đuôi; bước 4 dán hoặc vẽ mắt, mũi, miệng; bước 5 trang trí thêm hoa văn và thử xem đồ chơi có đứng vững không.\n- GV nhắc bạn thiếu vỏ chai thì dùng hộp sữa, lõi giấy, vỏ hộp bánh, bìa carton cuộn lại, giấy báo vò tròn; dùng que kem làm chân, ống hút làm râu, dây len làm đuôi, hột hạt làm mắt.\n- GV đi từng bàn hỗ trợ, khuyến khích hai bạn cùng bàn góp vật liệu để làm được con vật to hơn.\n- GV nhắc an toàn: GV cắt sẵn phần nhựa cứng, HS không tự cắt vỏ chai; mũi kéo hướng xuống bàn, không cầm mép nhựa vừa cắt; vỏ hộp phải khô ráo mới dùng.","hs":"- HS quan sát GV làm mẫu cách gắn chân, tai và giữ cho keo dính chắc.\n- HS thực hành theo 5 bước: chọn vật liệu, làm thân, gắn tai chân đuôi, làm mặt, trang trí và thử độ vững.\n- HS thiếu vỏ chai thì dùng hộp sữa, lõi giấy, bìa carton, giấy báo vò, que kem, ống hút, dây len.\n- HS cùng bàn góp vật liệu để làm được con vật to và đẹp hơn.\n- HS giữ an toàn, không tự cắt vỏ chai, chỉ dùng phần đã được GV cắt sẵn."},{"ten":"4. Vận dụng","gv":"- (7 phút) GV cho HS bày đồ chơi lên bàn nhóm thành một góc đồ chơi mini ở cuối lớp, con vật to đặt phía sau, con vật nhỏ đặt phía trước.\n- GV mời 4 đến 5 HS chia sẻ: Em làm con vật gì? Từ vật liệu nào? Con vật của em chơi thế nào?\n- GV nêu tiêu chí nhận xét sản phẩm: một là nhìn ra ngay đó là con vật gì; hai là các bộ phận gắn chắc, đồ chơi đứng vững và cầm chơi được; ba là màu sắc, hoa văn hài hoà; bốn là tận dụng được vật liệu tái sử dụng, sản phẩm sạch sẽ.\n- GV cho HS đi xem một vòng, mỗi bạn dán một ngôi sao vào đồ chơi mình thích rồi nói một câu vì sao thích.\n- GV khen ngợi, dặn HS lưu giữ sản phẩm cho tiết 3 và chuẩn bị lon hoặc hộp giấy để làm ống đựng bút; nhắc thu gom vụn giấy, nhựa, lau bàn và rửa tay sạch.","hs":"- HS bày đồ chơi lên bàn nhóm, con vật to ở sau, con vật nhỏ ở trước.\n- HS chia sẻ: tên con vật, vật liệu đã dùng và cách chơi món đồ chơi.\n- HS nghe và nhắc lại 4 tiêu chí nhận xét sản phẩm.\n- HS đi xem, dán ngôi sao vào đồ chơi mình thích và nói một câu vì sao thích.\n- HS lưu giữ sản phẩm, ghi nhớ việc chuẩn bị cho tiết 3, lau bàn và rửa tay."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu phim hướng dẫn biến vỏ chai, hộp giấy, nắp chai thành con vật; dừng ở mỗi bước để HS làm theo và tua lại chỗ nào cả lớp chưa kịp.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 1) HS trong nhóm cùng bàn xem nhóm mình làm con vật gì, ai lo phần thân, ai lo phần đầu.\n⚠ (Miền 4: An toàn) Vỏ chai, vỏ hộp phải rửa sạch và để khô trước khi dùng; cẩn thận khi dùng kéo cắt nhựa; chỉ mở đúng đoạn phim GV chỉ định.","hs":"- HS làm được đồ chơi con vật từ vật liệu tái sử dụng theo phim hướng dẫn.\n- HS phân công và làm việc được cùng bạn trong nhóm."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":32,"tiet":32,"bai":"Chủ đề 10: ĐỒ CHƠI TỪ TẠO HÌNH CON VẬT — Tiết 3: Thảo luận và vận dụng (làm ống đựng bút)","yccd":"1. Năng lực mĩ thuật\n- Củng cố kiến thức, kĩ năng đã học về tạo hình con vật.\n- Làm được một ống đựng bút từ vật liệu tái sử dụng, trang trí bằng tạo hình con vật.\n- Biết kết hợp công năng và trang trí trên sản phẩm.\n2. Năng lực chung\n- Giải quyết vấn đề và sáng tạo: tạo sản phẩm vừa đẹp vừa có ích.\n- Giao tiếp và hợp tác: trao đổi cách làm với bạn.\n3. Phẩm chất\n- Bảo vệ môi trường; chăm chỉ, ngăn nắp, biết làm đồ dùng học tập cho mình.","dodung":"- GV: hai ống đựng bút mẫu làm từ lon giấy và vỏ chai nhựa, trang trí hình con mèo và con cú; khay chia vật liệu theo loại; thiết bị trình chiếu.\n- GV chuẩn bị vật liệu thay thế cho lớp thiếu đồ dùng: lõi giấy, hộp sữa, vỏ hộp bánh, bìa carton cuộn tròn dán đáy, giấy báo cũ bọc ngoài, nắp chai, que kem, dây len, vải vụn, hột hạt, lá khô.\n- HS: sản phẩm các tiết trước, lon hoặc hộp giấy, chai nhựa đã rửa sạch và để khô, giấy màu, màu vẽ, kéo, keo dán, khăn lau tay, tờ báo cũ lót bàn.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV kiểm tra sản phẩm tiết 2 và vật liệu HS mang tới, khen ngợi, động viên; chia vật liệu dự phòng cho bạn còn thiếu.\n- GV chỉ vào hộp bút lộn xộn trên bàn một bạn và hỏi: Bút để lung tung thì khi cần có dễ tìm không? Nếu có một ống đựng bút xinh xắn thì bàn học sẽ thế nào?\n- Dự kiến HS trả lời: để lung tung thì khó tìm và hay rơi mất; có ống đựng bút thì bàn gọn gàng và đẹp hơn.\n- GV đưa hai ống đựng bút mẫu ra và dẫn vào bài: hôm nay cả lớp sẽ làm một ống đựng bút hình con vật từ vật liệu tái sử dụng.","hs":"- HS đặt sản phẩm tiết 2 và vật liệu lên bàn cho GV kiểm tra.\n- HS quan sát và trả lời câu hỏi của GV về chỗ để bút của mình.\n- HS nêu: để lung tung thì khó tìm; có ống đựng bút thì bàn học gọn và đẹp hơn.\n- HS quan sát hai ống đựng bút mẫu và nắm nhiệm vụ của tiết học."},{"ten":"2. Khám phá — Thảo luận về ống đựng bút","gv":"- (7 phút) GV cho HS thảo luận nhóm đôi trong hai phút: Em sẽ làm ống đựng bút hình con vật gì? Từ vật liệu nào? Con vật ấy có đặc điểm gì dễ nhận ra?\n- GV mời vài nhóm trình bày. Dự kiến HS trả lời: em làm hình con mèo từ lon giấy, con mèo có tai nhọn và ria dài; em làm hình con cú từ vỏ chai vì con cú có mắt to tròn.\n- GV cho HS chuyền tay xem ống đựng bút mẫu, hỏi thêm: Miệng ống phải rộng bao nhiêu để bỏ bút vào dễ? Đáy ống cần thế nào để không đổ? Dự kiến HS trả lời: miệng rộng hơn nắm tay một chút, đáy phải phẳng và hơi nặng.\n- GV chốt cách làm: giữ nguyên phần ống để đựng bút, chỉ trang trí bên ngoài; tai, mắt, cánh gắn ra phía ngoài chứ không che mất miệng ống.","hs":"- HS thảo luận nhóm đôi và chọn con vật cùng vật liệu cho ống đựng bút.\n- HS trình bày: con vật đã chọn, vật liệu sẽ dùng và đặc điểm dễ nhận ra.\n- HS chuyền tay xem mẫu và trả lời: miệng ống rộng vừa tay, đáy phẳng cho khỏi đổ.\n- HS nhắc lại ý chốt: chỉ trang trí bên ngoài, không che mất miệng ống."},{"ten":"3. Luyện tập — Sáng tạo","gv":"- (16 phút) GV làm mẫu chậm bước khó là bọc giấy quanh ống: bôi keo thành ba đường dọc thân ống, đặt mép giấy vào rồi lăn ống trên bàn cho giấy bám đều, mép giấy cuối dán chồng lên khoảng một đốt ngón tay.\n- GV nêu các bước thực hành: bước 1 chọn ống và lau khô; bước 2 bọc giấy màu hoặc giấy báo tô màu làm nền; bước 3 cắt và dán tai, mắt, mũi, cánh của con vật; bước 4 vẽ hoặc dán thêm hoa văn cho thân ống; bước 5 kiểm tra đáy ống, dán thêm một miếng bìa cho phẳng rồi thử cắm bút vào.\n- GV nhắc bạn thiếu lon giấy thì dùng lõi giấy, hộp sữa, vỏ hộp bánh, bìa carton cuộn tròn dán đáy; thiếu giấy màu thì dùng giấy báo tô màu, vải vụn, lá khô, dây len.\n- GV đi từng bàn hỗ trợ, nhắc HS làm xong phần nền mới dán chi tiết để keo kịp khô.\n- GV nhắc an toàn: GV cắt sẵn phần nhựa và mép sắc, HS không tự cắt; mũi kéo hướng xuống bàn, keo bôi mỏng; báo trước khi còn 3 phút để HS hoàn thiện và ghi tên vào đáy ống.","hs":"- HS quan sát GV làm mẫu cách bọc giấy quanh thân ống cho phẳng.\n- HS thực hành theo 5 bước: chọn ống, bọc nền, dán chi tiết con vật, vẽ hoa văn, làm phẳng đáy và thử cắm bút.\n- HS thiếu vật liệu thì dùng lõi giấy, hộp sữa, bìa carton cuộn tròn, giấy báo tô màu, vải vụn.\n- HS làm xong phần nền mới dán chi tiết để keo kịp khô.\n- HS giữ an toàn khi dùng kéo và keo, hoàn thiện sản phẩm và ghi tên vào đáy ống."},{"ten":"4. Vận dụng","gv":"- (8 phút) GV cho HS bày ống đựng bút lên bàn nhóm thành một hàng ở góc lớp, ống cao đặt phía sau, ống thấp đặt phía trước cho dễ nhìn.\n- GV mời 4 đến 5 HS chia sẻ nhanh: Ống đựng bút của em hình con vật gì? Em làm từ vật liệu nào? Em sẽ đặt ống ở đâu và đựng những gì?\n- GV nêu tiêu chí để HS tự soi lại bài: một là nhìn ra ngay hình con vật; hai là ống đứng vững, miệng ống còn rộng để cắm bút; ba là màu sắc và hoa văn hài hoà; bốn là sản phẩm sạch sẽ, tận dụng vật liệu tái sử dụng.\n- GV cho HS đi xem một vòng, mỗi bạn dán một ngôi sao vào sản phẩm mình thích rồi nói một câu vì sao thích.\n- GV khen ngợi, dặn HS lưu giữ sản phẩm cho tiết 4 và chuẩn bị màu, keo để hoàn thiện, trưng bày; nhắc thu gom giấy vụn, lau bàn và rửa tay sạch.","hs":"- HS bày ống đựng bút lên bàn nhóm theo hàng cao thấp.\n- HS chia sẻ: hình con vật, vật liệu đã dùng và nơi sẽ đặt ống đựng bút.\n- HS nghe và tự soi lại bài của mình theo 4 tiêu chí.\n- HS đi xem, dán ngôi sao vào sản phẩm mình thích và nói một câu vì sao thích.\n- HS lưu giữ sản phẩm, ghi nhớ việc chuẩn bị cho tiết 4, lau bàn và rửa tay."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":33,"tiet":33,"bai":"Chủ đề 10: ĐỒ CHƠI TỪ TẠO HÌNH CON VẬT — Tiết 4: Vận dụng (hoàn thiện) và trưng bày","yccd":"1. Năng lực mĩ thuật\n- Hoàn thiện ống đựng bút trang trí tạo hình con vật.\n- Trưng bày, giới thiệu và nêu cảm nhận về sản phẩm của mình và của bạn.\n- Biết đánh giá sản phẩm theo tiêu chí đơn giản.\n2. Năng lực chung\n- Giao tiếp và hợp tác: tự tin giới thiệu sản phẩm, lắng nghe nhận xét.\n3. Phẩm chất\n- Bảo vệ môi trường; trân trọng sản phẩm tự làm và biết sử dụng vào học tập.\n4. Tích hợp\n- Năng lực số 2.2 CB1a: Nhận biết được các công nghệ số đơn giản, phù hợp để chia sẻ dữ liệu, thông tin và nội dung số: HS xem lại phim góc trưng bày và nhận ra sản phẩm của mình.","dodung":"- GV: bàn kê làm góc trưng bày đồ chơi của lớp; bảng tiêu chí đánh giá viết to; thẻ tên, ngôi sao giấy cắt sẵn; thiết bị trình chiếu.\n- GV chuẩn bị vật liệu thay thế cho lớp thiếu đồ dùng: giấy màu vụn, giấy báo cũ, bìa carton, nắp chai, que kem, ống hút cũ, dây len, vải vụn, hột hạt, lá khô để HS bổ sung chi tiết.\n- HS: sản phẩm tiết 3, giấy màu, màu vẽ, keo dán, kéo để hoàn thiện; khăn lau tay, tờ báo cũ lót bàn.","hoatdong":[{"ten":"1. Khởi động","gv":"- (3 phút) GV cho HS lấy ống đựng bút của tiết 3 đặt lên bàn, kiểm tra nhanh xem sản phẩm nào bị bong chi tiết hoặc đáy chưa vững để nhắc HS sửa ngay.\n- GV hỏi: Sản phẩm của em còn thiếu gì? Dự kiến HS trả lời: ống em còn thiếu đuôi, tai bị bong keo, thân ống còn một khoảng trống chưa trang trí.\n- GV nêu nhiệm vụ tiết học: hoàn thiện ống đựng bút và trưng bày thành góc đồ chơi của lớp để cả lớp cùng xem.","hs":"- HS lấy ống đựng bút tiết 3 đặt lên bàn và kiểm tra lại sản phẩm.\n- HS trả lời: sản phẩm còn thiếu đuôi, tai bị bong, thân ống còn khoảng trống.\n- HS lắng nghe, nắm nhiệm vụ của tiết học và chuẩn bị đồ dùng."},{"ten":"2. Khám phá — Hoàn thiện","gv":"- (7 phút) GV treo bảng tiêu chí và đọc chậm cho HS nghe để biết cần hoàn thiện những gì.\n- GV gợi ý các cách làm sản phẩm sinh động hơn: thêm đuôi bằng dây len, thêm chân bằng que kem, dán một dải hoa văn lặp lại quanh thân ống, tô đậm viền mắt cho con vật nhìn có hồn.\n- GV hỏi gợi mở: Vì sao hoa văn nên lặp lại quanh thân ống? Đáy ống nhẹ quá thì sao? Dự kiến HS trả lời: hoa văn lặp lại nhìn đều và đẹp hơn; đáy nhẹ quá thì cắm bút vào sẽ bị đổ.\n- GV làm mẫu chậm cách chèn đáy: cắt một miếng bìa vừa lòng ống, đặt xuống đáy rồi dán viền quanh, nếu ống vẫn nhẹ thì cho thêm một nắm giấy báo vò chặt xuống dưới.","hs":"- HS đọc thầm bảng tiêu chí và biết mình cần hoàn thiện những gì.\n- HS nghe gợi ý và chọn cách làm cho sản phẩm của mình sinh động hơn.\n- HS trả lời: hoa văn lặp lại nhìn đều và đẹp; đáy nhẹ quá thì ống dễ đổ.\n- HS quan sát GV làm mẫu cách chèn đáy ống cho vững."},{"ten":"3. Luyện tập — Hoàn thiện sản phẩm","gv":"- (14 phút) GV nêu các bước hoàn thiện: bước 1 dán lại các chi tiết bị bong; bước 2 bổ sung tai, chân, đuôi còn thiếu; bước 3 trang trí hoa văn lặp lại quanh thân ống; bước 4 chèn và làm phẳng đáy cho ống đứng vững; bước 5 lau sạch sản phẩm, ghi tên vào thẻ đặt cạnh sản phẩm.\n- GV nhắc bạn thiếu vật liệu thì dùng giấy báo cũ, bìa carton, nắp chai, que kem, ống hút, dây len, vải vụn, hột hạt, lá khô.\n- GV đi từng bàn hỗ trợ, thử cắm bút vào ống của HS để kiểm tra xem ống có đổ không rồi hướng dẫn HS chỉnh lại.\n- GV nhắc an toàn và vệ sinh: mũi kéo hướng xuống bàn, không tự cắt vỏ chai, keo bôi mỏng, gom giấy vụn và mẩu nhựa bỏ vào sọt rác.\n- GV báo trước khi còn 3 phút để HS hoàn thiện và mang sản phẩm ra góc trưng bày.","hs":"- HS hoàn thiện theo 5 bước: dán lại chi tiết bong, bổ sung tai chân đuôi, trang trí hoa văn, làm phẳng đáy, lau sạch và ghi thẻ tên.\n- HS thiếu vật liệu thì dùng giấy báo, bìa carton, nắp chai, que kem, dây len, vải vụn.\n- HS thử cắm bút vào ống, thấy đổ thì chèn thêm cho đáy nặng và phẳng.\n- HS giữ an toàn khi dùng kéo và keo, gom rác bỏ vào sọt.\n- HS hoàn thiện đúng giờ và mang sản phẩm ra góc trưng bày."},{"ten":"4. Vận dụng — Trưng bày","gv":"- (7 phút) GV cho HS bày sản phẩm lên bàn trưng bày, xếp thành các nhóm con vật giống nhau và đặt thẻ tên phía trước để thành góc đồ chơi của lớp.\n- GV mời HS giới thiệu: Ống đựng bút của em hình con vật gì? Em làm từ vật liệu gì? Em thích sản phẩm nào của bạn nhất, vì sao?\n- GV nêu tiêu chí nhận xét sản phẩm: một là nhìn ra rõ hình con vật với đủ tai, mắt, chân, đuôi; hai là ống đứng vững, dùng đựng bút được; ba là hoa văn và màu sắc hài hoà, sắp xếp cân đối; bốn là sản phẩm sạch sẽ, tận dụng được vật liệu tái sử dụng.\n- GV cho HS đi xem một vòng, mỗi bạn dán một ngôi sao vào sản phẩm mình thích rồi nói một câu vì sao thích.\n- GV nhận xét, động viên; dặn HS mang sản phẩm về đặt trên bàn học và chuẩn bị đồ dùng đầy đủ cho tiết kiểm tra cuối năm; nhắc lau bàn, nhặt rác và rửa tay sạch.","hs":"- HS bày sản phẩm lên bàn trưng bày theo nhóm con vật và đặt thẻ tên.\n- HS giới thiệu: hình con vật, vật liệu đã dùng và sản phẩm của bạn mình thích.\n- HS nghe và nhắc lại 4 tiêu chí nhận xét sản phẩm.\n- HS đi xem, dán ngôi sao vào sản phẩm mình thích và nói một câu vì sao thích.\n- HS ghi nhớ việc chuẩn bị cho tiết kiểm tra cuối năm, lau bàn, nhặt rác và rửa tay."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV bày các đồ chơi của lớp thành một góc trưng bày rồi quay một đoạn phim ngắn đi vòng quanh góc ấy để cả lớp xem lại như đi hội chợ đồ chơi.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 1) HS lần lượt cầm sản phẩm giới thiệu trước lớp: đây là con vật gì, làm từ vật liệu gì, chơi ra sao.\n⚠ (Miền 4: An toàn) Đoạn phim chỉ quay sản phẩm và bàn tay, không quay cận mặt bạn nào khi bạn chưa đồng ý; phim giữ trong máy của lớp.","hs":"- HS xem lại phim góc trưng bày và nhận ra sản phẩm của mình.\n- HS giới thiệu được sản phẩm của mình trước lớp."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":34,"tiet":34,"bai":"KIỂM TRA, ĐÁNH GIÁ CUỐI NĂM","yccd":"1. Năng lực mĩ thuật\n- Vận dụng tổng hợp kiến thức, kĩ năng về nét, hình, khối, màu sắc, chân dung, tạo hình con vật đã học cả năm để tạo một sản phẩm mĩ thuật theo chủ đề tự chọn.\n- Trưng bày, giới thiệu và nêu được cảm nhận về sản phẩm của mình.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động hoàn thành sản phẩm đánh giá.\n- Giao tiếp và hợp tác: tự tin giới thiệu sản phẩm trước lớp.\n3. Phẩm chất\n- Chăm chỉ, trung thực trong đánh giá; trân trọng sản phẩm do mình và bạn tạo ra.","dodung":"- GV: bảng tiêu chí đánh giá cuối năm viết to treo trên bảng lớp; bảng nhóm, dây kẹp và bàn kê làm khu trưng bày; thẻ tên, ngôi sao giấy cắt sẵn; thiết bị trình chiếu.\n- GV chuẩn bị vật liệu thay thế cho bạn thiếu đồ dùng: mặt sau tờ lịch, giấy báo cũ, bìa carton, vỏ hộp sữa, nắp chai, lá khô, hột hạt, dây len, vải vụn, đất nặn dùng chung theo bàn.\n- HS: đồ dùng mĩ thuật đầy đủ (bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, đất nặn, kéo, hồ dán, vật liệu tái sử dụng), khăn lau tay, tờ báo cũ lót bàn.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV ổn định lớp, kiểm tra nhanh đồ dùng của từng bàn và cho mượn vật liệu dự phòng để bạn nào cũng đủ đồ làm bài.\n- GV nêu mục đích tiết học: đây là tiết kiểm tra, đánh giá cuối năm, mỗi bạn tự làm một sản phẩm mĩ thuật theo chủ đề mình thích để cho thấy mình đã học được những gì.\n- GV treo bảng tiêu chí và đọc chậm: một là chọn được chủ đề rõ ràng; hai là vận dụng được kiến thức đã học về nét, hình, khối, màu hoặc tạo hình con vật; ba là sắp xếp cân đối, màu sắc hài hoà; bốn là bài sạch sẽ, hoàn thành đúng giờ, có ý tưởng riêng.\n- GV động viên: bài phải là của chính mình, làm theo sức mình, ai cũng có thể làm tốt theo cách riêng.","hs":"- HS ổn định chỗ ngồi, bày đồ dùng lên bàn cho GV kiểm tra.\n- HS lắng nghe và nắm mục đích của tiết kiểm tra, đánh giá cuối năm.\n- HS đọc thầm và nhắc lại 4 tiêu chí đánh giá trên bảng.\n- HS chuẩn bị tinh thần tự làm bài của mình, không nhìn bài của bạn."},{"ten":"2. Khám phá — Ôn nhanh kiến thức cả năm","gv":"- (7 phút) GV cho HS nhắc lại nhanh các chủ đề đã học trong năm bằng hình thức hỏi đáp theo tổ, mỗi tổ kể một chủ đề.\n- GV nêu câu hỏi: Cả năm em đã học những chủ đề nào? Em đã làm sản phẩm bằng những cách nào? Cách nào em làm tốt nhất?\n- Dự kiến HS trả lời: em đã học về nét, hình cơ bản, khối, mảng màu, sắc màu thiên nhiên, gương mặt thân quen, bữa cơm gia đình, thầy cô của em, đồ chơi con vật; em đã vẽ, xé dán, in, nặn, đắp nổi, làm đồ chơi tái sử dụng; em làm xé dán tốt nhất.\n- GV gợi ý chọn chủ đề cho bài kiểm tra: gia đình em, ngôi trường của em, con vật em yêu, mùa hè của em; hỏi thêm: Em sẽ làm bằng cách nào? Cần vật liệu gì?\n- GV chốt và cho HS ghi tên chủ đề cùng cách làm đã chọn vào góc giấy để nhớ.","hs":"- HS tham gia hỏi đáp theo tổ, kể lại các chủ đề đã học trong năm.\n- HS nêu các cách làm đã học: vẽ, xé dán, in, nặn, đắp nổi, làm đồ chơi tái sử dụng.\n- HS chọn chủ đề và cách thể hiện phù hợp với sức mình.\n- HS ghi tên chủ đề và cách làm đã chọn vào góc giấy."},{"ten":"3. Luyện tập — Thực hành đánh giá","gv":"- (16 phút) GV nêu các bước làm bài: bước 1 nghĩ kĩ hình ảnh chính của chủ đề; bước 2 phác nhẹ hoặc chuẩn bị vật liệu; bước 3 làm hình ảnh chính to ở giữa bài; bước 4 thêm hình ảnh phụ và màu nền; bước 5 xem lại toàn bài, chỉnh chỗ chưa cân đối rồi ghi tên.\n- GV nhắc bạn thiếu giấy vẽ dùng mặt sau tờ lịch hoặc giấy báo cũ; thiếu đất nặn dùng vỏ hộp, bìa carton, giấy báo vò tròn; thiếu giấy màu dùng lá khô, vải vụn, hột hạt, nắp chai.\n- GV đi quanh lớp quan sát, ghi nhận cách làm việc của từng HS để đánh giá cả quá trình, chỉ gợi ý bằng câu hỏi chứ không làm hộ.\n- GV nhắc an toàn: mũi kéo hướng xuống bàn, đưa kéo cho bạn thì cầm phần lưỡi, hồ dán bôi mỏng, không đưa đất nặn và tay dính màu lên miệng, giữ chỗ ngồi gọn.\n- GV báo trước khi còn 3 phút để HS kịp hoàn thiện và mang bài ra khu trưng bày.","hs":"- HS làm bài theo 5 bước: nghĩ hình ảnh chính, phác hoặc chuẩn bị vật liệu, làm hình chính, thêm hình phụ và nền, chỉnh lại rồi ghi tên.\n- HS thiếu đồ dùng thì dùng mặt sau tờ lịch, giấy báo, vỏ hộp, lá khô, vải vụn, hột hạt.\n- HS tự làm bài của mình, chỉ hỏi GV khi thật sự gặp khó.\n- HS giữ an toàn khi dùng kéo, hồ dán và giữ chỗ ngồi gọn gàng.\n- HS hoàn thiện bài đúng giờ và mang ra khu trưng bày."},{"ten":"4. Vận dụng — Trưng bày, đánh giá","gv":"- (8 phút) GV cho HS treo tranh lên dây kẹp hoặc đặt sản phẩm lên bàn trưng bày theo chủ đề, đặt thẻ tên phía trước, tạo thành phòng tranh mini tổng kết năm học ở góc lớp.\n- GV mời HS giới thiệu: Sản phẩm của em nói về điều gì? Em đã dùng cách làm nào đã học? Em thấy mình tiến bộ nhất ở chỗ nào so với đầu năm?\n- GV cùng HS đối chiếu với 4 tiêu chí đã nêu đầu giờ để nhận xét, luôn nói điều làm được trước rồi mới nói điều cần cố gắng thêm.\n- GV cho HS đi xem một vòng, mỗi bạn dán một ngôi sao vào sản phẩm mình thích rồi nói một câu vì sao thích.\n- GV tổng kết năm học, khen ngợi sự tiến bộ của cả lớp; dặn HS giữ sản phẩm vào bìa hồ sơ cá nhân, giữ thói quen quan sát cái đẹp và tận dụng vật liệu tái sử dụng trong hè; nhắc lau bàn, nhặt rác, rửa tay.","hs":"- HS treo tranh hoặc đặt sản phẩm lên khu trưng bày và đặt thẻ tên.\n- HS giới thiệu: nội dung sản phẩm, cách làm đã dùng và điều mình tiến bộ nhất.\n- HS nghe nhận xét, đối chiếu bài của mình với 4 tiêu chí.\n- HS đi xem, dán ngôi sao vào sản phẩm mình thích và nói một câu vì sao thích.\n- HS cất sản phẩm vào bìa hồ sơ cá nhân, lau bàn, nhặt rác và rửa tay."}]},
{"lop":2,"mon":"Mĩ thuật","tuan":35,"tiet":35,"bai":"TRƯNG BÀY SẢN PHẨM CUỐI NĂM","yccd":"1. Năng lực mĩ thuật\n- Lựa chọn, sắp xếp và trưng bày được các sản phẩm mĩ thuật tiêu biểu đã làm trong năm học.\n- Giới thiệu, chia sẻ và nêu cảm nhận về sản phẩm của mình và của bạn.\n- Cảm nhận được vẻ đẹp và sự tiến bộ của bản thân qua các sản phẩm.\n2. Năng lực chung\n- Giao tiếp và hợp tác: phối hợp cùng bạn tổ chức trưng bày, giới thiệu sản phẩm.\n- Giải quyết vấn đề và sáng tạo: sắp xếp không gian trưng bày đẹp mắt.\n3. Phẩm chất\n- Yêu thích môn Mĩ thuật; trân trọng thành quả của mình và của bạn.\n4. Tích hợp\n- Năng lực số 2.5 CB1a: Phân biệt được chuẩn mực hành vi đơn giản và biết cách sử dụng công nghệ số và tương tác trong môi trường số: HS giới thiệu sản phẩm của mình với người xem một cách tự tin, lễ phép.","dodung":"- Giáo viên: không gian, bảng, giá trưng bày; thiết bị trình chiếu.\n- Học sinh: các sản phẩm mĩ thuật đã làm trong năm học, vật liệu trang trí không gian trưng bày.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV tạo không khí vui tươi, giới thiệu buổi trưng bày sản phẩm cuối năm.\n- GV nêu ý nghĩa của buổi trưng bày.","hs":"- HS hào hứng, lắng nghe.\n- HS chuẩn bị sản phẩm của mình."},{"ten":"2. Khám phá — Chọn và sắp xếp sản phẩm","gv":"- GV hướng dẫn HS lựa chọn các sản phẩm tiêu biểu đã làm trong năm.\n- GV gợi ý cách sắp xếp sản phẩm theo chủ đề, theo nhóm cho đẹp mắt.","hs":"- HS chọn sản phẩm tiêu biểu.\n- HS sắp xếp sản phẩm theo hướng dẫn."},{"ten":"3. Luyện tập — Trưng bày","gv":"- GV tổ chức cho HS trưng bày sản phẩm theo tổ/nhóm, trang trí không gian.\n- GV quan sát, hỗ trợ HS.","hs":"- HS phối hợp trưng bày, trang trí không gian.\n- HS chuẩn bị giới thiệu sản phẩm."},{"ten":"4. Vận dụng — Giới thiệu và chia sẻ","gv":"- GV tổ chức cho HS tham quan, giới thiệu sản phẩm; chia sẻ: Em thích sản phẩm nào nhất? Em tiến bộ ở điều gì?\n- GV nhận xét, tổng kết, động viên cả lớp; khích lệ HS tiếp tục yêu thích mĩ thuật.","hs":"- HS tham quan, giới thiệu và chia sẻ cảm nhận.\n- HS lắng nghe nhận xét, tổng kết."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV cùng HS chọn ảnh sản phẩm ưng ý nhất của mỗi bạn trong cả năm, ghép thành một trang triển lãm cuối năm có ghi tên chủ đề và tên tác giả dưới mỗi ảnh.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 1) HS mời cha mẹ, thầy cô xem trang triển lãm và tập nói lời giới thiệu ngắn về sản phẩm của mình.\n⚠ (Miền 4: An toàn) Trang triển lãm chỉ ghi tên gọi ở lớp của bạn, không ghi họ tên đầy đủ và địa chỉ; chỉ chiếu trong buổi tổng kết ở trường, không đăng lên mạng khi cha mẹ các bạn chưa đồng ý.","hs":"- HS chọn được sản phẩm tiêu biểu của mình để đưa vào triển lãm.\n- HS giới thiệu sản phẩm của mình với người xem một cách tự tin, lễ phép."}]}
];
